window.__D("text/maamarim-melukatim/c017",{"p":[[1500390005,"<h3>בס\"ד. ש\"פ חוקת-בלק, י\"ב תמוז ה'תשכ\"ט<sup data-n=\"157\">*</sup></h3>\n<b>וידבר</b> ה' אל משה גו' זאת חוקת התורה גו' ויקחו אליך פרה אדומה גו'<sup data-n=\"158\">1</sup>, ופירש רש\"י ויקחו אליך, לעולם היא נקראת על שמך, פרה שעשה משה במדבר. וצריך להבין, הרי רק פרה הראשונה עשה משה, ולמה נקראות כל הפרות (שמונת הפרות שעשו אח\"כ, וגם פרה העשירית שיעשה מלך המשיח<sup data-n=\"159\">2</sup>) על שמו של משה. ולהוסיף, דע\"פ הידוע<sup data-n=\"160\">3</sup> ששמו של כל דבר אשר יקראו לו מורה על ענינו ותוכנו, מובן, דזה שכל הפרות נקראות על שמו של משה הוא לפי שזה (השייכות למשה) הוא ענינם ותוכנם. ועפ\"ז צריך להבין עוד יותר זה שהפרות נקראות על שם משה, הרי עשיית הפרות הייתה ע\"י הכהנים<sup data-n=\"161\">4</sup> [וגם פרה הראשונה נעשתה ע\"י אלעזר הכהן<sup data-n=\"162\">5</sup>, ופירוש פרה שעשה משה הוא לכאורה רק שנעשתה ע\"פ הוראתו וציוויו<sup data-n=\"163\">6</sup>], ומהי שייכותן למשה, ועד שנקראות על שמו.\nב) <b>והענין</b> הוא, דאיתא בלקו\"ת<sup data-n=\"164\">7</sup>, דהטעם על זה שבפרה אדומה נאמר זאת חוקת התורה, הוא, לפי שמצות פרה אדומה היא כללות התורה. ולכן, כמו שהתורה נקראת על שמו של משה כמ\"ש<sup data-n=\"165\">8</sup> זכרו תורת משה עבדי<sup data-n=\"166\">9</sup>, כן גם פרה אדומה, שהיא כללות התורה, נקראת על שמו של משה<sup data-n=\"167\">10</sup>. ולכאורה יש להוסיף, דמ\"ש בלקו\"ת שמצות פרה אדומה היא כללות התורה, הכוונה היא בעיקר למצוות התורה [כמובן מהביאור בלקו\"ת שם<sup data-n=\"168\">11</sup>, דזה שמצות פרה אדומה הוא כללות התורה הוא כי יסוד כל המצוות הוא רצוא ושוב, ופרה אדומה הו\"ע רצוא ושוב]. ועפ\"ז כללות <i>מצוות</i> התורה שייכות למשה.<b>ויש</b> לבאר זה ע\"פ מ\"ש בתניא<sup data-n=\"169\">12</sup> דהטעם על זה שציוה משה רבינו לדור שנכנסו לארץ לקרות ק\"ש פעמיים בכל יום לקבל מלכות שמים במס\"נ (אף שהבטיח להם פחדכם ומוראכם יתן ה' וגו'<sup data-n=\"170\">13</sup>) הוא מפני שקיום התומ\"צ תלוי בזכירת ענין המס\"נ. ויש לומר, דזה שמשה דוקא ציוה זה לדור שנכנסו לארץ הוא, כי מס\"נ הו\"ע הביטול, וכיון שהאדם הוא מציאות (היפך ענין הביטול), לכן, בכדי שענין המס\"נ יהי' אצלו בגילוי [ובאופן שיהי' קבוע בלבו תמיד ממש יומם ולילה לא ימיש מזכרונו<sup data-n=\"171\">14</sup>], צריך לזה נתינת כח מיוחדת. והנתינת כח הוא ע\"י משה, כי משה הו\"ע הביטול, ונחנו מה<sup data-n=\"172\">15</sup>. ולכן ע\"י שמשה ציוה<sup data-n=\"173\">16</sup> לדור שנכנסו לארץ לקבל עליהם (פעמיים בכל יום) מלכות שמים במס\"נ, עי\"ז ניתן להם הכח לזכור תמיד ענין המס\"נ שלהם. וזהו לעולם היא נקראת על שמך, כי קיום התורה ומצוותי' [דפרה אדומה היא כללות התומ\"צ] תלוי בזכירת ענין המס\"נ, והכח לזכור תמיד ענין המס\"נ הוא ע\"י משה, וע\"י האתפשטותא דמשה שבכל דור<sup data-n=\"174\">17</sup>, עד לכ\"ק מו\"ח אדמו\"ר נשיא דורנו בעל השמחה והגאולה. ויש לומר, דע\"י שעבודתו של נשיא דורנו בכל משך שלושים שנות נשיאותו<sup data-n=\"175\">18</sup> היתה במס\"נ בגילוי, לכן הנתינת כח על זכירת המס\"נ מאתפשטותא דמשה שבדורנו הוא בגילוי עוד יותר.\n<b>ולהוסיף</b><b>,</b> דמהביאורים בזה שמצות פרה אדומה היא כללות כל התורה [שלכן נאמר בה זאת חוקת התורה], הוא<sup data-n=\"176\">19</sup>, כי היסוד דכל המצוות הוא שהם חוקה. היינו שהמצוות הם רצון העליון שלמעלה מהשכל, ולכן, גם קיומם צריך להיות בדרך קבלת עול, חוקה<sup data-n=\"177\">20</sup> חקקתי גזירה גזרתי. ועפ\"ז יובן עוד יותר<sup data-n=\"178\">21</sup> זה שפרה אדומה נקראת על שמו של משה, כי בכדי שקיום כל המצוות (הגם שיש עליהםטעם<sup data-n=\"179\">22</sup>) יהי' באופן דזאת <i>חוקת</i> התורה הוא ע\"י שהתורה (ומצותי'), גם לאחרי שנתלבשה בחכמה ושכל, נקראת על שמו של משה, שענינו הוא ביטול, תורת משה <i>עבדי</i>, ועי\"ז ישנה הנתינת כח לכל אחד מישראל (ע\"י בחינת משה שבו<sup data-n=\"180\">23</sup>) שקיום המצוות שלו יהי' בביטול דקבלת עול, כקיום מצות פרה אדומה, זאת חוקת התורה.\nג) <b>והנה</b> איתא במדרש<sup data-n=\"181\">24</sup> עה\"פ ויקחו אליך פרה אדומה, א\"ל הקב\"ה למשה, לך אני מגלה טעם פרה אבל לאחר חוקה. וצריך להבין דכיון שמשה השיג הטעם דכל המצוות, גם הטעם דמצות פרה אדומה, איך נמשך על ידו הנתינת כח לקיום המצוות באופן דחוקה חקקתי גזירה גזרתי. ולכאורה הי' אפשר לבאר ע\"פ מ\"ש במק\"א<sup data-n=\"182\">25</sup>, שבכל מצוה ישנם שני הענינים דחוקים ומשפטים. כי כל המצוות (גם המצוות דעדות ומשפטים שיש עליהם טעם) הם רצונו ית', ורצון הוא למעלה מטעם, למעלה גם מהטעמים שבחכמתו ית', ולאחרי שהרצון דמצוות (גם המצוות דחוקים, ואפילו מצות פרה אדומה) נמשך ונתלבש בחכמה (דתורה), ניתוסף בהם טעם. והחילוק שבין המצוות דעדות ומשפטים להמצוות דחוקים הוא, שבהמצוות דעדות ומשפטים, הטעמים שבחכמתו ית' נמשכו ונתלבשו בשכל הנבראים ועד בשכל אנושי, ובהמצוות דחוקים, הטעמים שלהם לא נתלבשו (כ\"כ) בשכל הנבראים. והטעם דמצות פרה אדומה הוא בחכמתו ית' (חכמה דאצילות) ולא נמשך כלל בשכל הנבראים. [וזה שמשה השיג טעם פרה הוא לפי שגם בהיותו למטה הי' בחינת חכמה דאצילות בגילוי<sup data-n=\"183\">26</sup>].\n<b>וזהו</b> שבכל המצוות ישנם שני הענינים דחוקים ומשפטים, שמצד הרצון דמצוות – כל המצוות הם חוקים, וקיומם צריך להיות בדרך קבלת עול, חוקה חקקתי גזירה גזרתי. ומצד הענין דטעמי המצוות – כל המצוות הם משפטים, וקיומם צריך להיות (גם) מצד הטעם. וע\"י שמשה ידע הטעם דמצות פרה, קיים גם מצוה זו מצד הטעם [משא\"כ בכל אחד, קיום מצות פרה אדומה מצד הטעם הוא<sup data-n=\"184\">27</sup> זה שמתבונן שגם מצוה זו יש לה טעם]. ועפ\"ז יובן בפשטות שגם אצל משה לא הי' חסר ח\"ו קיום המצוות באופן דחוקה חקקתי גזירה גזרתי, כי ענין זה שבקיום המצוות הוא מצד הרצון דמצוות. אבל ביאור זה צריך לביאור נוסף, כי היתרון דמצות פרה אדומה לגבי כל המצוות הוא, שבכל המצוות, הטעם שבהם מעלים על הרצון, ובמצות פרה אדומה שאין עלי' טעם (בשכל האדם) הרצון הוא בגילוי [ופירוש זאת חוקת התורה הוא שכל מצוות התורה הם חוקה כמו פרה אדומה]. ומזה שנאמר ויקחו אליך, דהפרה נקראת על שמו של משה, משמע, דענין המיוחד שבמצות פרה אדומה, שהחוקהשבה (רצון למעלה מטעם) הוא בגילוי, הוא גם לגבי משה, ולכאורה, כיון שמשה ידע טעם פרה, מהו החילוק לגבי משה בין מצות פרה אדומה לכל המצוות.\nד) <b>ויובן</b> זה בהקדים מ\"ש<sup data-n=\"185\">28</sup> תפלה למשה. ואיתא בזהר<sup data-n=\"186\">29</sup> שתפלה למשה היא תפלת עשיר<sup data-n=\"187\">30</sup>. ולהעיר ממ\"ש כ\"ק מו\"ח אדמו\"ר בעל הגאולה בשיחתו הידועה<sup data-n=\"188\">31</sup> שהמזמור תפלה למשה שייך להגאולה די\"ט כסלו [כידוע שאדמו\"ר הזקן הי' אומר בכל יום שיעור תהלים כמו שנחלק לימי החודש<sup data-n=\"189\">32</sup>, וכיון שהמזמור תפלה למשה הוא התחלת שיעור תהלים החדשי דיום הי\"ט לחודש, הרי אמר ביום גאולתו (י\"ט כסלו) מזמור זה], דמזה מובן, שמזמור זה שייך גם להגאולה די\"ב וי\"ג תמוז, הגאולה דנשיא דורנו ממלא מקומו של בעל הגאולה די\"ט כסלו. [ובפרט בשנה זו<sup data-n=\"190\">33</sup>, שבי\"ב תמוז, יום ההולדת דבעל הגאולה, הוא התחלת שנת הצדי\"ק דבעל הגאולה, ובו מתחילים לומר מזמור צדי\"ק שבתהלים הוא המזמור תפלה למשה]. והנה ענינו ותוכנו דמזמור זה הוא תפלה למשה [דהענינים הבאים בהמשך המזמור (לאחרי התיבות תפלה למשה איש האלקים) הם הענינים שמשה אמרם בתפלתו (ענינים פרטיים), אבל ענינו הכללי דהמזמור [שהוא גם שמו דהמזמור] הוא תפלה למשה], דתפלה למשה היא תפלת עשיר (כנ\"ל). ומזה מובן, שהשייכות דהמזמור להגאולה די\"ט כסלו ודי\"ב תמוז היא בעיקר מצד ענינו דכללות המזמור – תפלה למשה, תפלת עשיר, כדלקמן סעיף יג.\nה) <b>ויובן</b> זה בהקדים הדיוק דאדמו\"ר (מהורש\"ב) נ\"ע במאמרו ד\"ה תפלה למשה<sup data-n=\"191\">34</sup>, הרי ענין התפלה הוא שמתפלל להקב\"ה שימלא את מחסורו<sup data-n=\"192\">35</sup>, וכיון שהעשיר אינו חסר שום דבר, מהו\"ע תפלת עשיר. ויש לומר, שדיוק זה הוא (בעיקר) בנוגע לתפלת משה. דבעשיר בכלל יש לומר שהתפלה שלו היא שהקב\"ה ימלא את מחסורו הרוחני. משא\"כ במשה שגם בהיותו למטה האיר בו בגילוי המקור שלו כמו שהוא באצילות, ועד שאין מחיצה והפסק ביניהם, משה משה לא פסיק טעמא<sup data-n=\"193\">36</sup>, הרי מובן, דזה שמשה הי' עשיר בגשמיות הוא לפי שהי' עשיר ברוחניות, היינו שגםברוחניות לא הי' חסר שום דבר, גם לא חסרון שבדוגמת סוס לרכוב עליו ועבד לרוץ לפניו, ולכן מדייק בהמאמר מהו\"ע תפלת עשיר.\n<b>וממשיך</b> בהמאמר<sup data-n=\"194\">37</sup>, דענין העשיר הוא לא רק שאינו חסר שום דבר אלא שהוא מושפע בריבוי השפע. וכמאמר רז\"ל<sup data-n=\"195\">38</sup> עה\"פ<sup data-n=\"196\">39</sup> די מחסורו אשר יחסר לו, די מחסורו ואי אתה מצווה לעשרו. וכיון שבדי מחסורו אשר יחסר לו נכלל גם החסרון דסוס לרכוב עליו ועבד לרוץ לפניו, ואעפ\"כ אמרו ואי אתה מצווה לעשרו, הרי מובן, שגם כשיש לו כל צרכיו (כולל גם סוס לרכוב עליו ועבד לרוץ לפניו), אינו (עדיין) עשיר, כי ענין העשיר הוא (דלא רק שיש לו כל צרכיו, אלא) שהוא מושפע בריבוי השפע. וע\"פ מ\"ש לעיל דזה שמשה הי' עשיר בגשמיות הוא לפי שהי' עשיר ברוחניות, מובן, דנוסף לזה שבמשה לא הי' שום חסרון ח\"ו (גם לא חסרון שבדוגמת סוס לרכוב עליו וכו'), כי האירו בו בגילוי כל הגילויים השייכים לעולמות, הנכללים בשני הענינים דממלא כל עלמין וסובב כל עלמין, שהגילוי דענינים אלה הוא מילוי החסרון [דאור הממלא, כיון שהוא <i>מקור</i> לעולמות, לכן, כשאור זה אינו בגילוי בעולם, העולם הוא חסר ממש. ואור הסובב, שהוא למעלה ממקור לעולמות ורק שייך לעולמות, לכן, כשאינו מתגלה בעולם אור זה, החסרון דעולם הוא דוגמת החסרון דסוס לרכוב עליו ועבד לרוץ לפניו. וכמאמר רז\"ל<sup data-n=\"197\">40</sup> עה\"פ<sup data-n=\"198\">41</sup> ויכל אלקים ביום השביעי מה הי' העולם חסר מנוחה בא שבת בא מנוחה, מנוחה היא בחינת סובב שלמעלה מהאור המתלבש בעולם, ואעפ\"כ כשלא הי' גילוי זה בעולם, הי' העולם חסר, אלא שחסרון זה הוא לא שהי' חסר איזה פרט בהעולם עצמו, כי כל הפרטים דהעולם נתהוו ע\"י <i>מלאכת</i> הבריאה (אור המתלבש בעולם) שנשלמה לפני שבת, וזה שהעולם הי' חסר מנוחה הוא דוגמת החסרון דסוס לרכוב עליו (שאין זה דבר הכרחי לצורך קיום חיותו), וכשבא שבת ונמשך ונתגלה אור הסובב, נתמלא גם חסרון זה. וענין העשירות דמשה הוא, דנוסף על זה שהאירו בו בגילוי הגילויים דממלא וסובב], האיר אצלו בגילוי גם הגילוי דאוא\"ס שלמעלה משייכות לעולמות. וכמבואר בהמאמר<sup data-n=\"199\">42</sup>, דזה שמשה נקרא עשיר הוא לפי שמשה הוא בחינת דעת עליון. ומהמעלות שבדעת עליון על דעת תחתון הוא, שדעת תחתון מקבל מחיצוניות הכתר, אריך – סובב, ודעת עליון מקבל מפנימיות הכתר, עתיק – אוא\"ס שלמעלה מגדר עולמות. ועפ\"ז צריך להבין עוד יותר הענין דתפלה למשה, תפלת עשיר, הרי ענין התפלה הוא שהקב\"ה ימלא את מחסורו, וכיון שמשה הי' עשיר הן בגשמיות והן ברוחניות, הרי לא רק שלא הי' חסר (בפועל) שום דבר אלא שלא הי' שייך אצלו ענין החסרון<sup data-n=\"200\">43</sup>, ומהו\"ע התפלה שלו.ו) <b>ונקודת</b> הביאור בזה (בהמאמר<sup data-n=\"201\">44</sup>), דתפלת עשיר היא לא בשביל עצמו אלא בשביל כנסת ישראל. כדאיתא במדרש<sup data-n=\"202\">45</sup> עה\"פ תפלה למשה, משל למה הדבר דומה לשלשה שבאו ליטול כו' מאת המלך כו' בא השלישי, אמר לו המלך מה אתה מבקש, אמר לו, איני מבקש על עצמי דבר, אלא מדינה פלונית היא חרבה והיא שלך, גזור שתיבנה כו', כך משה לא ביקש לעצמו אלא בשביל ישראל. ולכאורה, ביאור זה צריך לביאור נוסף. דלפי הנ\"ל התפלה שהעשיר מתפלל (בשביל אחרים) אינה שייכת להעשירות שלו [דזה שהוא מתפלל בשביל אחרים הוא מפני שהוא רוצה בטובתם], ופירוש תפלת עשיר (בפשטות) הוא שהתפלה שלו היא <i>מפני</i> שהוא עשיר<sup data-n=\"203\">46</sup>.\n<b>ויובן</b> זה ע\"פ המבואר בהמאמר<sup data-n=\"201\">44</sup> דכנסת ישראל היא בחינת מלכות, ובקשת משה עבור כנסת ישראל היתה (בשביל ישראל כפשוטם, וגם) בשביל ספירת המלכות. ולכן<sup data-n=\"204\">47</sup> אומר במדרש שבקשת משה עבור כנסת ישראל היא ע\"ד הבקשה מדינה פלונית כו', דמדינה היא מלכות, והיא חריבה הוא החסרון שנעשה במלכות (ענין מיעוט הירח), והבקשה גזור שתיבנה היא שיומשך גילוי עצמות אוא\"ס במלכות שעי\"ז תיבנה בבחינת בנין עדי עד. דכשנתמלא החסרון דמלכות ע\"י שנמשך בה הגילוי ששייך למלכות, שאז היא מתעלית להדרגא כמו שהיתה קודם שנסתלק ונחסר ממנה האור, אזי אפשר שהאור שנמשך בה יסתלק עוד פעם, ובכדי שהבנין שלה יהי' בבחינת בנין עדי עד (שאין שייך שתיחרב ח\"ו) הוא ע\"י שנמשך בה גילוי עצמות אוא\"ס שלמעלה מהאור השייך לעולמות (מלכות), דבאור זה אין שייך צמצום וסילוק. וזהו שתפלת משה נקראת תפלת עשיר דפירוש תפלת עשיר הוא שהתפלה שלו היא <i>מפני</i> שהוא עשיר (כנ\"ל), כי זה שמשה התפלל שיומשך במלכות גילוי עצמות אוא\"ס (שעי\"ז דוקא תיבנה בבחינת בנין עדי עד) הוא מפני שהי' עשיר, בחינת דעת עליון שמקבל מעתיק, עצמות אוא\"ס שלמעלה מגדר עולמות.\nז) <b>וצריך</b> להבין, דלפי הנ\"ל [שתפלתו של משה שיומשך עצמות אוא\"ס במלכות הוא מפני שמשה הוא דעת עליון ולכן ביכלתו להמשיך אור זה במלכות], המשכת הגילוי במלכות ע\"י משה הוא (לכאורה) בדרך מלמעלה למטה<sup data-n=\"205\">48</sup>. ומהו\"ע <i>תפלה</i> למשה (<i>תפלת</i> עשיר), דתפלה היא מלמטה למעלה. ויש לומר הביאור בזה, דכשההמשכה במלכות היא בדרך מלמעלה למטה, אזי, גם כשהגילוי הוא עצמות אוא\"ס שלמעלה מענין הצמצום, דבכללות הוא בחינת עצם האור שלא נגע בו הצמצום, מ\"מ, כיון דזה שאין שייך שיסתלק האור מהמלכות הוא מפני <i>שהאור</i> הוא למעלה מענין הצמצום, הרי בנוגע להמלכות, אין זה אמיתית הענין דבנין עדי עד, מכיון שמצד המלכות אפשר שיסתלק ממנה האור. ואמיתית הענין דבנין עדי עד הואכשהמשכת גילוי זה במלכות הוא (לא רק מצד למעלה אלא גם) מצד המלכות<sup data-n=\"206\">49</sup>. וזהו <i>תפלה</i> למשה, דתפלה היא עבודת הנבראים, ולכן ההמשכה שע\"י תפלה היא באופן ששייכת להמטה עצמו, להנבראים וכן לספירת המלכות שורש הנבראים. אלא שההמשכה שע\"י תפלה בכלל, כיון שתפלה היא עבודת הנבראים, לכן ההמשכה שע\"י זה היא המשכה ששייכת לעולמות<sup data-n=\"207\">50</sup>, ובההמשכה שע\"י תפלה למשה, שתי המעלות. המשכת עצמות אוא\"ס שלמעלה משייכות לעולמות, ואעפ\"כ ההמשכה היא נמשכת במלכות ובאופן שהיא שייכת להמלכות עצמה.\nח) <b>ובעומק</b> יותר יש לומר, שהיתרון בההמשכה שע\"י תפלת משה לגבי ההמשכה בדרך מלמעלה למטה, הוא לא רק באופן ההמשכה (שההמשכה שע\"י תפלת משה שייכת יותר להמטה, כנ\"ל) אלא גם בההמשכה עצמה. והענין הוא, דהטעם על זה שכל מה שנברא בששת ימי בראשית צריך תיקון<sup data-n=\"208\">51</sup>, הוא, כי כוונת הבריאה היא בשביל עבודת האדם, ולכן נברא העולם באופן שתיקונו יהי' ע\"י עבודת האדם, שעי\"ז נעשה האדם שותף להקב\"ה במעשה בראשית<sup data-n=\"209\">52</sup>. וזהו גם הטעם על זה שהתהוות העולמות מהמלכות היתה ע\"י הצמצום שנחסר האור מבחינת המלכות [וכמ\"ש<sup data-n=\"210\">53</sup> את עשית את השמים גו', את חסר ה', דזה שהמלכות נעשית מקור להוות את העולמות (עשית את השמים גו') הוא ע\"י שנחסרו ממנה ה' פרצופים, את חסר ה'<sup data-n=\"211\">54</sup>. וי\"ל דהחסרון שהי' בהמלכות שממנה נברא העולם הוא השורש והסיבה להחסרון דהעולם, דכל מה שנברא בששת ימי בראשית צריך תיקון], הוא בכדי שמילוי החסרון דהמלכות יהי' ע\"י עבודת האדם. ולהוסיף, דהגם שהצמצום הי' רק בהאור השייך לעולמות, באור הגבול (שורש הממלא) וגם באור הבל\"ג (שורש הסובב), [אלא שפעולת הצמצום באור הגבול הוא<sup data-n=\"212\">55</sup> בהאור עצמו, שנעשה בו ירידה והגבלה ועד שנעשה מקור להוות את העולמות, ופעולת הצמצום באור הבל\"ג הוא רק<sup data-n=\"212\">55</sup> שלא יאיר במקום החלל<sup data-n=\"213\">56</sup>. דזהו שבעיגול הגדול (אור הבל\"ג) נגע בו הצמצום, דענין נגיעת הצמצום הוא שהאור יהי' רק שם (בהעיגול) ולא יתגלה לחוץ<sup data-n=\"214\">57</sup>] אבל בעצם האור לא הי' הצמצום כלל, היינו שהצמצום גם לא נגע בו [שלכן, מצד אורזה אפשר להיות הגילוי גם בעולמות], מ\"מ, כיון שהכוונה בכל הגילויים (גם בהגילוי דעצם האור שלמעלה מגדר עולמות, למעלה גם מ(השורש ד)סובב כל עלמין) הוא בשביל ישראל, לכן, גם המשכת אור זה היא ע\"י עבודת האדם.\nט) <b>ועפ\"ז</b> יש לבאר מ\"ש בהמאמר<sup data-n=\"215\">58</sup> דבהגילויים שלמעלה יש ג' מדריגות בכללות. ממלא כל עלמין, סובב כל עלמין ועצמות אוא\"ס שלמעלה מממלא וסובב. ובג' מדריגות אלה הם ג' האהבות שבפסוק<sup data-n=\"216\">59</sup> ואהבת, בכל לבבך, בכל נפשך ובכל מאדך. האהבה דבכל לבבך היא בבחינת ממלא כל עלמין, דכיון שהחיות דבחי' ממכ\"ע הוא מלובש בהנבראים בפנימיותם, לכן, ע\"י ההתבוננות נרגש חיות זה גם בנפש הבהמית, והאהבה היא בכל לבבך בשני יצריך<sup data-n=\"217\">60</sup>. האהבה דבכל נפשך היא בבחינת סוכ\"ע, דכיון שאור הסובב הוא למעלה מהתלבשות בעולמות, לכן, ע\"י שנרגש בו ההפלאה דאוא\"ס (סובב), אהבתו את הוי' היא באופן דמסירת נפש [בכל נפשך, אפילו נוטל את נפשך<sup data-n=\"217\">60</sup>], שרוצה לצאת ממציאותו וליכלל באוא\"ס. ואהבה זו היא רק בנפש האלקית. כי ההשגה [באופן דהכרה והרגשה, שאז דוקא מביאה ההשגה לאהבה] בההפלאה דאוא\"ס יכולה להיות רק בנפש האלקית, ששרשה הוא בשם הוי'<sup data-n=\"218\">61</sup>, סובב. והאהבה דבכל מאדך היא בעצמות אוא\"ס שלמעלה גם מסובב. כי אמיתית הבל\"ג הוא בעצמות אוא\"ס (משא\"כ אור הסובב יש בו איזה ציור והגבלה), ולכן, האהבה שע\"י גילוי עצמות אוא\"ס היא בכל מאדך, בלי גבול. ולאחרי שמבאר השייכות דג' האהבות לג' מדריגות הנ\"ל, מסיים, דמזה מובן ענינם של ג' המדריגות, דממלא הוא מתלבש בעולמות, וסובב הוא למעלה מהתלבשות אבל שייך לעולמות, ועצמות אוא\"ס אינו בגדר עולמות.\n<b>וצריך</b> להבין, דלכאורה, הביאור בהשייכות דג' האהבות לג' המדריגות דלמעלה הוא <i>לאחרי</i> הבנת הענינים דג' המדריגות, ומהמשך הענינים בהמאמר משמע דענין זה [שג' מדריגות אלה הם ג' האהבות] מוסיף ביאור בג' המדריגות. ויש לומר מהביאורים בזה, דהטעם על זה שישנם למעלה ג' מדריגות שבהם נכללים כל הגילויים, הוא, כי כל הגילויים דלמעלה הם בשביל עבודת האדם, וכיון שבאהבת ה' [שהיא עיקר העבודה, דלית פולחנא כפולחנא דרחימותא<sup data-n=\"219\">62</sup>] ישנם ג' האהבות, בכל לבבך בכל נפשך ובכל מאדך, לכן כללות כל הגילויים דלמעלה נחלקים לג' מדריגות (ממלא וסובב ואוא\"ס שלמעלה מסובב) שבהתאם לג' אהבות הנ\"ל. וכיון שהבנת ענין על בוריו הוא ע\"י שמבארים אותו מיסודו ושרשו, לכן, התחלת הביאור (בהמאמר) של ג' המדריגות דלמעלה הוא איך שבהם הם ג' האהבות, כי זהו השורש והסיבה לזה שנמשכו ג' המדריגות.יו\"ד) <b>ויש</b> לומר, דהטעם בפנימיות הענינים על זה שהמשכת וגילוי ג' הענינים דממלא וסובב ועצמות אוא\"ס הוא ע\"י ג' האהבות דבכל לבבך ובכל נפשך ובכל מאדך, הוא, כי הכוונה בכל הגילויים היא בכדי שעל ידם תהי' אח\"כ בריאת העולם, ולכן, כמו שבריאת העולם היתה באופן <i>שכל</i> הענינים שבו<sup data-n=\"220\">63</sup> יתתקנו ע\"י עבודת האדם, בכדי שעי\"ז יהי' האדם שותף להקב\"ה במעשה בראשית, עד\"ז הוא בנוגע להגילויים דלמעלה, שהתהוותם (המשכתם) היתה באופן שהגילוי שלהם<sup data-n=\"221\">64</sup> יהי' ע\"י עבודת האדם, בכדי שהשותפות של האדם להקב\"ה במעשה בראשית תהי' לא רק בהעולם עצמו אלא גם בהגילויים דלמעלה שעל ידם היתה בריאת העולם. וכיון שעיקר עבודת האדם הוא אהבת ה' דלית פולחנא כפולחנא דרחימותא (כנ\"ל), לכן, הגילוי דג' המדריגות הנ\"ל (שבהם נכללים כל הענינים דלמעלה), הוא ע\"י ג' האהבות דבכל לבבך ובכל נפשך ובכל מאדך. וע\"י שהענינים דלמעלה נמשכים ומתגלים ע\"י עבודת האדם, נעשה בהם עלי' למעלה יותר מכמו שהם מצד עצמם<sup data-n=\"222\">65</sup>.\n<b>וזהו</b> <i>תפלה</i> למשה, דהמשכת הגילוי דעצמות אוא\"ס שלמעלה מסובב שהמשיך משה במלכות היתה ע\"י תפלה דוקא, הגם דכיון שמשה הוא דעת עליון שמקבל מעתיק (עצמות אוא\"ס שלמעלה מסובב) הי' ביכלתו להמשיך במלכות אור זה בדרך מלמעלה למטה, כי ע\"י שהמשכת האור היא ע\"י תפלה, עבודת האדם (בדרך מלמטה למעלה), נשלמת הכוונה שבשבילה נאצל האור, ועי\"ז נעשה בו עלי' ומיתוסף בהבל\"ג שלו. שהבל\"ג שבו הוא לא רק כמו שהוא מצד עצמו, עצם האור שאין שייך בו צמצום וסילוק, אלא (גם) כמו שהוא מצד העצמות. ולכן, בנין המלכות שנעשה ע\"י האור כמו שנמשך ע\"י תפלת משה הוא בנין עדי עד.\nיא) <b>וצריך</b> ביאור, דהעילוי שנעשה בהגילויים דלמעלה ע\"י עבודת האדם הוא (בעיקר<sup data-n=\"223\">66</sup>) <i>כשההמשכה והגילוי</i> שלהם היא ע\"י עבודת האדם, וכיון דזה שע\"י תפלת משה היתה ההמשכה והגילוי הוא רק בנוגע כנסת ישראל (כנסת ישראל כפשוטו, וגם ספירת המלכות), אבל בנוגע למשה אין שייך לכאורה לומר שההמשכה והגילוי היתה ע\"י תפלתו, שהרי משה הוא עשיר, דענין העשיר הוא שמאירים אצלו בגילוי כל הגילויים ואפילו הגילוי דעצמות אוא\"ס שלמעלה משייכות לעולמות, ועפ\"ז, העלי' וההוספה שנעשית בהאור ע\"י תפלת משה היא לכאורה רק לגבי אחרים ולא לגבי משה עצמו. ויש לומר הביאור בזה, דכיון שמשה הוא רוען של ישראל, לכן, כשחסר איזה ענין בכנסת ישראל, הוא כמו שחסר הענין גם אצלו, דנוסף לזה שהצער שלו על זה שחסר לישראל הי' צער גדול ביותר כאילו שהוא עצמו הי'החסר, הנה גם החסרון דישראל הי' החסרון שלו<sup data-n=\"224\">67</sup>. כי משה וישראל הם חד, ובלשון רש\"י<sup data-n=\"225\">68</sup> שמשה הוא ישראל וישראל הם משה. ולכן, הגם שמשה הי' עשיר והאירו בו כל הגילויים, מ\"מ, כיון שישראל היו חסרים הגילוי, ורק ע\"י עבודה (תפלתו של משה) נתחדש הגילוי לגבם – גם לגבי משה נתחדש הגילוי ע\"י תפלתו. [ולהוסיף, דזה שמשה הוא רוען של ישראל, זהו ענינו העיקרי. וכל המעלות שלו, כולל זה שהי' עשיר גם ברוחניות, בחינת דעת עליון שמקבל מעתיק, הם טפלים, בחינת חיצוניות, לגבי זה שהי' רוען של ישראל<sup data-n=\"226\">69</sup>. ועפ\"ז יובן יותר שגם לגבי משה נתחדש הגילוי ע\"י תפלה, הגם שמצד העשירות שלו (בחינת דעת עליון) האירו אצלו גם לפנ\"ז כל הגילויים, כי זה שהאירו אצלו כל הגילויים גם לפנ\"ז מצד העשירות שלו הוא בחינת החיצוניות שבו. אבל בנוגע להפנימיות שלו, זה שהוא רוען של ישראל, נתחדש הגילוי ע\"י תפלה]. ולכן העילוי שנעשה בהגילויים דלמעלה ע\"י שנמשכו ע\"י עבודה (תפלה), הוא גם בנוגע משה.\nיב) <b>וכמו</b> כן הוא באתפשטותא דמשה שבכל דור, עד לכ\"ק מו\"ח אדמו\"ר בעל הגאולה, שענינו העיקרי והפנימי הוא זה שהוא רוען של ישראל, והענינים דישראל הם ענינו דהנשיא. ועפ\"ז יש לבאר העילוי שנתחדש בהגאולה די\"ט כסלו ובהגאולה די\"ב תמוז ע\"י המאסר, שהוא כיתרון האור מן החושך, דלכאורה, כיון שבנוגע להנשיאים לא שייך לומר שבהיותם במאסר הי' לגבם איזה ענין של חושך, [וכמובן גם מהשיחה הידועה דבעל הגאולה<sup data-n=\"227\">70</sup> בנוגע להמאסר של אדמו\"ר הזקן שהמאסר הי' בהסכמתו, דמזה מובן, שלגבם ההעלמות וההסתרים דהמאסר הם רק בחיצוניות], איך נעשה עי\"ז יתרון האור. וי\"ל מהביאורים בזה, דכיון שעיקר ענינם של הנשיאים הוא זה שהם רועי ישראל ונשיאי ישראל, לכן, ההעלם וההסתר דהמאסר שהי' בנוגע ישראל הוא העלם והסתר גם לגבי הנשיאים. ולכן, בהגאולה מהמאסר, כשהחושך נהפך לאור, נעשה יתרון האור.\nיג) <b>והנה</b> נתבאר לעיל (סעיף ד) שהשייכות דהגאולה די\"ט כסלו ודי\"ב תמוז להמזמור תפלה למשה הוא (הן להענינים הפרטיים שנאמרו בהמזמור ומכש\"כ) לענינו ותוכנו דכללות המזמור – תפלה למשה, תפלת עשיר. וע\"פ המובא לעיל מהמאמר דענין העשירות הוא גילוי עצמות אוא\"ס שלמעלה מסובב [והשייכות דתפלת עשיר (מדינה פלונית כו' גזור שתיבנה) לעשירות היא כי בכדי שבנין המלכות (המדינה) יהי' בבחינת בנין עדי עד הוא ע\"י שנמשך בה גילוי עצמות אוא\"ס], יש לומר, דיתרון האור שנעשה בהגאולה די\"ט כסלו ודי\"ב תמוז הוא המשכת גילוי עצמות אוא\"ס שלמעלה מממלא וסובב.<b>ויש</b> לומר, דזהו שהגאולה (די\"ט כסלו ודי\"ב תמוז) היתה נס גלוי שלמעלה מהטבע, ואעפ\"כ הי' הנס מלובש בטבע, והגם שהנס נתלבש בטבע הי' זה באופן שהטבע לא העלים והסתיר על הנס, ועד שראו כל אפסי ארץ שזהו נס גלוי, כי שורש הטבע הוא משם אלקים, ממלא, ושורש הנסים הוא משם הוי', סובב, וכיון שבהגאולה הי' הגילוי דעצמות אוא\"ס שלמעלה מסובב וממלא, הכולל ומחבר את שניהם, לכן היתה הגאולה באופן שהנס והטבע נתחברו יחד, יחוד הוי' ואלקים.\n<b>ויש</b> לומר, שהגילוי דאוא\"ס שלמעלה מסובב וממלא בהחיבור דנס (ששרשו מסובב) וטבע (ששרשו מממלא) הוא רק שנרגש בהם ענין שלמעלה משניהם, שעי\"ז הם מתחברים. אבל זה שהטבע עצמו הי' אז באופן שלא העלים והסתיר על הנס, ועד שגם המנגדים [שנשארו אז בתקפם] ומ\"מ הוכרחו לסייע [וע\"י התוקף שלהם] בהשחרור והגאולה, הוא ע\"י שבהמלכות עצמה (שורש הנבראים) נתגלה שרשה האמיתי. ועפ\"ז יובן עוד יותר הקשר והשייכות דהגאולה להמזמור תפלה למשה, תפלת עשיר, דענין <i>תפלת</i> עשיר הוא מדינה פלונית כו' גזור שתיבנה, המשכת גילוי עצמות אוא\"ס במלכות.\n<b>ולהוסיף</b><b>,</b> שע\"י החיבור דנס וטבע שהי' בהגאולה, ניתן הכח לכל ההולכים באורחותיו של בעל הגאולה, שהאמונה שלמעלה מהשכל (נס) תומשך גם בשכל (טבע), ושהשכל לא יעלים ויסתיר על האמונה. ועד\"ז הוא בנוגע להענין דיפוצו מעינותיך חוצה [שהותחל בהגאולה די\"ט כסלו<sup data-n=\"228\">71</sup>, וניתוסף עוד יותר בהגאולה די\"ב תמוז] שע\"י החיבור דנס וטבע שהי' בהגאולה ניתן הכח להפיץ המעיינות דפנימיות התורה (שלמעלה מהעולם, נס) חוצה, ובאופן שגם כשהם נמצאים חוצה נראה בגלוי שהם המעיינות דפנימיות התורה. וזה שגם כשהם נמצאים חוצה הם באופן שרואים בגלוי שהם מעיינות, הוא לא רק מפני שהמעיינות הם בגילוי אלא גם מפני שהחוצה נעשה באופן שאינו מעלים ומסתיר על המעיינות, ויתירה מזו, שהוא כלי להמעיינות. וזה נעשה הכנה קרובה לקיום היעוד ונגלה כבוד הוי' וראו כל בשר יחדו כי פי הוי' דיבר<sup data-n=\"229\">72</sup>, שהבשר יראה אלקות (לא רק מצד הגילוי דכבוד הוי', אלא גם) מצד הבשר עצמו.\nיד) <b>וזהו</b> וידבר ה' אל משה גו' דבר אל בני ישראל ויקחו אליך פרה אדומה גו', דזה שהפרה נקראת על שמו של משה – הגם שענין המיוחד שבמצות פרה אדומה הוא שהחוקה שבה (רצון שלמעלה מחכמה) הוא בגילוי, וכיון שמשה ידע טעם פרה הרי לגבי' אין חילוק בין מצות פרה אדומה לכל המצוות – כי ע\"י שמצות פרה אדומה היא חוקה לגבי ישראל, היא חוקה גם לגבי משה. וזהו דבר אל בני ישראל ויקחו אליך גו', דע\"י דבר אל בני ישראל – עי\"ז הוא ויקחו אליך, הענין דזאת חוקת התורה בנוגע למשה. אלא שענין זה (שמישראל נמשך למשה) הוא בנוגע להמצוה עצמה, דזה שהיא חוקה (בלי טעם) הוא בעיקר בישראל. אבלבנוגע לקיום המצוה, בכדי שישראל יוכלו לקיים המצוה דפרה אדומה ועד\"ז כל המצוות בביטול דקבלת עול (באופן דחוקה חקקתי גזירה גזרתי), הנתינת כח על זה הוא ממשה, שענינו הוא ביטול, ונחנו מה. ויש לומר, דע\"י שמשה ידע טעם פרה, והביטול דקבלת עול נמשך גם בההשגה שלו, ניתן הכח לכל אחד מישראל שהאמונה והקבלת עול יונח (זאָל זיך אָפּלייגן) גם בהשכל שלו.\n<b>ויש</b> לומר, דזהו שארז\"ל חוקה&lt;20&gt; חקקתי גזירה גזרתי ואין לך רשות להרהר אחרי'<sup data-n=\"230\">73</sup>, שהקבלת עול שלו היא באופן שלא רק שהוא מקיים בפועל ציווי הקב\"ה (גם כשאינו מבין), אלא שאינו מהרהר כלל, כי גם בשכלו מונח הענין דקבלת עול. ויש לקשר זה עם מאמר המדרש<sup data-n=\"231\">74</sup> שפרה אדומה רומזת על הגלויות, פרה זו מצרים אדומה זו בבל תמימה זו מדי אשר אין בה מום זה יון, כי ע\"י זה שהשכל הוא באופן שמונח אצלו הענין דקבלת עול שלמעלה מהשכל, הוא הכנה קרובה לגאולה העתידה, שהגילוי אלקות בעולם יהי' גם מצד העולם. וזוהי השייכות דזאת חוקת התורה לשריפת הפרה, דע\"י שהקבלת עול הוא באופן שאינו מהרהר, כי גם בשכלו מונח הענין דקבלת עול, נעשה שריפת (הפרה שרומזת על) הגלות, כפתגם הידוע דבעל הגאולה<sup data-n=\"232\">75</sup>, והולכים כולנו יחד עם נשיאינו בעל הגאולה בראשנו להגאולה האמיתית והשלימה בביאת משיח צדקנו, בקרוב ממש.\n**********",[["157","*","יצא לאור ב<b>קונטרס חג הגאולה י\"ב-י\"ג תמוז – תנש\"א</b>, \"לקראת חג הגאולה י\"ב-י\"ג תמוז . . <i>י\"א תמוז</i>,<i> ה'תנש\"א</i>*\"."],["158","1","פרשתנו (חוקת) יט, א-ב."],["159","2","רמב\"ם הל' פרה אדומה ספ\"ג."],["160","3","שעהיוה\"א פ\"א. וראה בארוכה תשובות וביאורים (קה\"ת תשל\"ד) סימן א (נדפס באגרות-קודש ח\"א ס\"ע רפח ואילך)."],["161","4","רמב\"ם הל' פרה אדומה פ\"א הי\"א."],["162","5","פרשתנו יט, ג."],["163","6","ע\"ד פרה העשירית שיעשה מלך המשיח, שהפירוש (בפשטות) הוא לא שמשיח עצמו יעשה (כי עשיית הפרה צריכה להיות ע\"י כהן), אלא שתיעשה ע\"פ הציווי שלו."],["164","7","ריש פרשתנו (נו, א)."],["165","8","מלאכי ג, כב."],["166","9","שבת פט, א."],["167","10","ראה עד\"ז כלי יקר כאן."],["168","11","נו, ב ואילך.\n*) <i>ולהעיר</i>,<i> שמאמר זה שייך במיוחד לשנה זו (תנש\"א [בה י\"ל המאמר]) – שנת הצדי\"ק להולדת כ\"ק אדמו\"ר שליט\"א – כי בו מבואר המזמור תפלה למשה</i>,<i> מזמור צדי\"ק שבתהלים</i>."],["169","12","ספכ\"ה."],["170","13","עקב יא, כה."],["171","14","לשון אדה\"ז בתניא שם."],["172","15","בשלח טז, ח."],["173","16","ע\"פ מ\"ש בפנים יומתק לשון אדה\"ז בתניא שם \"למה ציוה משה רבינו ע\"ה במשנה תורה לדור שנכנסו לארץ כו'\" – ולכאורה הול\"ל \"למה נצטוה הדור שנכנסו לארץ כו'\", ומה נוגע בזה שהציווי הי' ע\"י משה רבינו ושהציווי נאמר במשנה תורה? וע\"פ מ\"ש בפנים יש לומר שבזה מרמז שהכח על זכירת המס\"נ הוא ממשה. ובכדי להדגיש זה עוד יותר מוסיף \"במשנה תורה\" – שמשנה תורה אמר משה לא רק בתור שליח אלא מפי עצמו (מגילה לא, ב וראה פרש\"י שם), היינו שזה נתעצם בהשגתו (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381211\" data-slug=\"likkutei-torah\" data-id=\"4001381211\">לקו\"ת שה\"ש כ, ג</a>)."],["174","17","תקו\"ז תס\"ט (קיב א. קיד, א)."],["175","18","ב' ניסן תר\"פ – יו\"ד שבט ה'שי\"ת. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181312\" data-slug=\"likkutei-sichot\" data-id=\"1300181312\">לקו\"ש חי\"ח ע' 303</a> ואילך."],["176","19","ראה לקו\"ש ח\"ד ע' 1056. ובכ\"מ."],["177","20","תנחומא פרשתנו ג. שם ח. במדב\"ר ריש פרשתנו. ועוד."],["178","21","היתרון בהביאור דלקמן הוא, כי מזה <i>שפרה אדומה</i> (שהוא כללות התורה) נקראת על שמו של משה, משמע, שהמצוות עצמם שייכים למשה, ולפי הביאור דלעיל שהשייכות למשה הוא מצד ענין המס\"נ, אין זה נוגע להמצוות עצמם, כי זה שקיום התומ\"צ תלוי בזכירת ענין המס\"נ הוא \"כי בזה יוכל <i>לעמוד נגד יצרו</i>\" (תניא ספכ\"ה), משא\"כ זה שקיום המצוות צ\"ל (בקב\"ע) מפני הציווי הו\"ע שנוגע לקיום המצוות עצמם.\nויתירה מזה יש לומר להביאור דלקמן, שהשייכות דמצוות למשה היא לא רק בנוגע לקיום המצוות אלא גם בנוגע המצוות עצמם. דזה שגם לאחרי שהמצוות (רצונו ית') נמשכו בתורה (חכמה) נרגש שהם רצון שלמעלה מהחכמה, הוא, כי החכמה (תורה) שבה נמשך הרצון דמצוות היא תורת משה עבדי."],["179","22","גם המצוות דחוקים. שהרי אינם היפך השכל לגמרי כפרה אדומה (ראה סה\"מ תרכ\"ט ע' רלז [בהוצאת תשנ\"ב ע' רנח] ובכ\"מ), ובערך החוקה דפרה אדומה – גם המצוות דחוקים הם מובנים קצת."],["180","23","<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא רפמ\"ב</a>."],["181","24","במדב\"ר פרשתנו פי\"ט, ו. תנחומא פרשתנו ח."],["182","25","ראה לעיל ס\"ע יד ואילך (וראה גם לעיל ח\"ב ס\"ע קסד ואילך). לעיל ח\"ג ע' קמג ואילך."],["183","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380916\" data-slug=\"likkutei-torah\" data-id=\"4001380916\">לקו\"ת נצבים מט, ב</a>. ובכ\"מ."],["184","27","ראה עד\"ז לעיל ח\"ג שם."],["185","28","תהלים צדי\"ק, א*."],["186","29","ראה זח\"א קסח, ב."],["187","30","ראה גם נדרים לח, א שמשה הי' עשיר."],["188","31","דליל כ' כסלו תרצ\"ד (לקו\"ד כרך א צז, א ואילך)."],["189","32","לקו\"ד שם. וכן נהגו הנשיאים שלאחריו, ממלאי מקומו – מכתב כ\"ק מו\"ח אדמו\"ר, נדפס ב\"קובץ מכתבים\" שבסו\"ס תהלים אהל יוסף יצחק (ע' 200). אגרות-קודש שלו ח\"ג ע' תעג ואילך."],["190","33","תשכ\"ט, שנת אמירת מאמר זה."],["191","34","דשנת תר\"ס – נדפס בסה\"מ תר\"ס ע' מט ואילך. וראה בארוכה ד\"ה זה די\"ג תמוז שנה זו (תשכ\"ט) – לקמן ע' לו ואילך."],["192","35","ראה רמב\"ם הל' תפלה פ\"א ה\"ב."],["193","36","זח\"ג (באד\"ר) קלה, א. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370336\" data-slug=\"torah-or\" data-id=\"3901370336\">תו\"א משפטים עה, ג</a>. המשך תרס\"ו ע' רטז. ובכ\"מ.\n*) <i>ע\"פ המנהג לומר בכל יום הקאַפּיטל תהלים המתאים לשנות חייו (מכתב כ\"ק מו\"ח אדמו\"ר</i>,<i> נדפס ב</i>\"<i>קובץ מכתבים</i>\"<i> שבסו\"ס תהלים אהל יוסף יצחק (ע' 214)</i>.<i> אגרות-קודש שלו ח\"א ע' לא</i>.<i> ח\"י ע' נג</i>.<i> וראה גם מאמרי אדה\"ז הקצרים ע' שמא</i>.<i> סה\"מ י\"א ניסן ע' 1 ואילך) – התחילו בי\"א ניסן שנה זו (תנש\"א – שנת הדפסת המאמר) אמירת מזמור צדי\"ק שבתהלים</i>. <b>המו\"ל</b>."],["194","37","סה\"מ תר\"ס ס\"ע נג ואילך."],["195","38","כתובות סז, ב."],["196","39","ראה טו, ח."],["197","40","פרש\"י עה\"פ בראשית ב, ב. פרש\"י ד\"ה ויכל – מגילה ט, א (וראה ב\"ר פ\"י, ט). תוד\"ה חצבה – סנהדרין לח, א."],["198","41","בראשית שם."],["199","42","סה\"מ תר\"ס ע' נח. וראה שם ע' נג."],["200","43","ראה בארוכה ד\"ה תפלה למשה שבהערה 34."],["201","44","שם ע' נח."],["202","45","שוחר טוב ויל\"ש עה\"פ. מדרש תהלים באָבער שם."],["203","46","בדוגמת תפלת עני, שהתפלה שלו היא <i>מפני</i> שהוא עני."],["204","47","סה\"מ תר\"ס שם ע' סב."],["205","48","וראה בסה\"מ תר\"ס שם ע' סב – דתפלה למשה היא ע\"ד <i>תורה</i>."],["206","49","ועפ\"ז יומתק שההקדמה להבקשה \"גזור שתיבנה\" היא \"והיא שלך\", \"היינו שבשרשה היא בבחינת פנימיות ועצמות א\"ס\" (סה\"מ תר\"ס שם) – די\"ל, דכיון ש\"היא שלך\" לכן ההמשכה במלכות (גזור שתיבנה) תהי' מצד ענינה דהמלכות."],["207","50","דהגם שע\"י התפלה נמשך רצון חדש (שלמעלה מהשתלשלות) – הרי גם הרצון חדש הוא בנוגע ענין השייך לעולם, למלאות בקשת המתפלל."],["208","51","ב\"ר פי\"א, ו."],["209","52","ראה שבת קיט, ריש ע\"ב."],["210","53","נחמי' ט, ו."],["211","54","המאמר ד\"ה תפלה למשה תר\"ס בא בהמשך להמאמר ד\"ה הקול קול יעקב תר\"ס ושם (ע' מה ואילך) מבואר ענין את חסר ה'. וראה גם לקמן ע' קד, ובהנסמן שם."],["212","55","ואולי יש לומר שב\"את עשית את השמים\" דוגמת שני ענינים אלה: חסר ה', שנחסרו מהמלכות ה' פרצופים – הוא שנסתלקו <i>מהמלכות</i> (אבל לא נעשה שינוים בהם עצמם); ועי\"ז <i>ירדה</i> המלכות ונעשית מקור להוות העולמות, \"עשית את השמים גו'\"."],["213","56","ראה בארוכה המשך תער\"ב ח\"ב ע' תתקכז ואילך. ובכ\"מ."],["214","57","ראה סה\"מ תרמ\"ג ע' פ. המשך תרס\"ו ע' קצד-ה. ובכ\"מ."],["215","58","סה\"מ תר\"ס שם ע' נד ואילך."],["216","59","ואתחנן ו, ה."],["217","60","ברכות נד, א במשנה. ספרי (הובא בפרש\"י) עה\"פ."],["218","61","אגה\"ת פ\"ד (צד, א)."],["219","62","ראה זהר ח\"ב נה, ב. ח\"ג רסז, א. וראה לקו\"ת שלח מב, ג."],["220","63","וכלשון המדרש שבהערה 51 <i>כל</i> מה שנברא בששת ימי בראשית צריך תיקון."],["221","64","שהוא ה\"תיקון\" שלהם."],["222","65","ראה עד\"ז לקו\"ד כרך ב שג, א-ב, שע\"י מחשבת האדם בהענינים דלמעלה, נעשה בהם עלי' בדוגמת העלי' שנעשית בדברים גשמיים ע\"י שמביאים תועלת לעבודת ה' (ומכש\"כ כשמקיימים בהם מצוה). ויש לומר, דהעלי' בהענינים דלמעלה ע\"י <i>שנמשכים</i> ע\"י עבודת האדם היא באופן נעלה יותר, מכיון שעבודת האדם היא בנוגע להמשכת הענינים עצמם (ולא רק שהאדם משתמש בהם לעבודת ה')."],["223","66","ראה הערה הקודמת."],["224","67","וזה שתפלת משה נקראת תפלת <i>עשיר</i> – אף שהחסרון דכנס\"י (שעל זה התפלל) הוא (כמו) החסרון שלו – ראה ד\"ה תפלה למשה תשכ\"ט הנ\"ל סעיף ט (לקמן ע' מה)."],["225","68","פרשתנו (חוקת) כא, כא."],["226","69","ולכן אמר \"ואם אין מחני נא מספרך אשר כתבת – מכל התורה כולה\" (תשא לב, לב. פרש\"י שם) – כי אפילו תורה, אף שמשה נתן נפשו על התורה (מכילתא לבשלח טז, א. שמו\"ר פ\"ל, ד. וש\"נ), אינה הפנימיות דמשה, כישראל. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211175\" data-slug=\"likkutei-sichot\" data-id=\"1300211175\">לקו\"ש חכ\"א ע' 175</a> ואילך."],["227","70","לקו\"ד ח\"א לז, סע\"ב ואילך."],["228","71","ספר השיחות תורת שלום ס\"ע 112 ואילך."],["229","72","ישעי' מ, ה. וראה לעיל ח\"ג ע' קצג ובהערות שם."],["230","73","פרש\"י ריש פרשתנו, מיומא סז, ב."],["231","74","יל\"ש פרשתנו רמז תשנט."],["232","75","אגרות-קודש שלו ח\"ו ע' שעב. \"היום יום\" בתחלתו."]]],[1500390006,"<h3>בס\"ד. י\"ג תמוז ה'תשכ\"ט<sup data-n=\"233\">*</sup></h3>\n<b>תפלה</b> למשה איש האלקים גו'<sup data-n=\"234\">1</sup>, ומבאר כ\"ק מו\"ח אדמו\"ר בשיחתו הידועה<sup data-n=\"235\">2</sup> דמזמור זה שייך להגאולה די\"ט כסלו [כידוע שאדמו\"ר הזקן הי' אומר בכל יום שיעור תהלים כמו שנחלק לימי החודש<sup data-n=\"236\">3</sup>, וכיון שהמזמור תפלה למשה הוא התחלת שיעור תהלים החדשי דיום הי\"ט לחודש, הרי אמר ביום גאולתו (י\"ט כסלו) מזמור זה]. וממשיך בהשיחה, שדוד מלך ישראל הי' לו בקבלה<sup data-n=\"237\">4</sup> שמזמור זה חיברו משה, כדאיתא במדרש<sup data-n=\"238\">5</sup> אחד עשר מזמורים אמר משה כנגד אחד עשר שבטים. וממשיך בהשיחה, דהתחלת המזמור הוא אד' מעון אתה גו' וסיום המזמור<sup data-n=\"239\">6</sup> הוא ויהי נועם אד' גו', מעון ונועם הם אותם האותיות. וצריך להבין הקשר דג' הענינים (השייכות דהמזמור להגאולה די\"ט כסלו, שמזמור זה חיברו משה והשייכות דמעון ונועם). גם צריך להבין מה שמביא ראי' מהמדרש שמזמור זה חיברו משה, והרי בהמזמור עצמו נאמר שהוא תפלה למשה.\nב) <b>ויש</b> לבאר ע\"פ הידוע<sup data-n=\"240\">7</sup> שבהגאולה די\"ט כסלו הותחל הענין דיפוצו מעינותיך חוצה, שהוא הכנה וכלי לאתי מר דא מלכא משיחא<sup data-n=\"241\">8</sup>. ועפ\"ז, השייכות דמזמור זה להגאולה די\"ט כסלו מורה (גם) על שייכותו לגאולה העתידה. וזהו שלאחרי שאומר בהשיחה שמזמור זה שייך להגאולה די\"ט כסלו ממשיך שמזמור זה חיברו משה, דמשה הוא גואל ראשון הוא גואל אחרון<sup data-n=\"242\">9</sup>. [ומדייק <i>שדוד מלך ישראל</i> הי' לו בקבלה שמזמור זה חיברו משה, שבזה מרמז, דענין משה שנוגע כאן הוא זהשמשה גאל את ישראל מגלות מצרים, שהגאולה ממצרים היא הקדמה להגאולה העתידה<sup data-n=\"243\">10</sup> ע\"י דוד מלכא משיחא, כימי צאתך מארץ מצרים אראנו נפלאות<sup data-n=\"244\">11</sup>]. ומביא את מאמר המדרש אחד עשר מזמורים אמר משה, דבאחד עשר שני ענינים. אחד שלפני (ולמעלה מ)עשר הוא אוא\"ס שלמעלה מעשר ספירות, אנת<sup data-n=\"245\">12</sup> הוא <i>חד</i> ולא בחושבן<sup data-n=\"246\">13</sup>, ואחד <i>עשר</i> הוא המשכת אחד (חד ולא בחושבן) בעשר, בכל העשר ספירות<sup data-n=\"247\">14</sup> ועד בספירת המלכות. ואדרבה, עיקר המשכת בחינת חד ולא בחושבן הוא במלכות, כי שורש המלכות הוא בפנימיות הכתר. דכל הספירות שרשם בחיצוניות הכתר שנמנה במנין עשר ספירות<sup data-n=\"248\">15</sup>, ושורש המלכות הוא בפנימיות הכתר שאינו נמנה במנין הספירות<sup data-n=\"248\">15</sup>, חד ולא בחושבן. אלא שבגילוי, המלכות היא למטה מכל הספירות, ועד שירדה להיות מקור להוות עולמות בי\"ע<sup data-n=\"249\">16</sup>, עד לעוה\"ז הגשמי. ולע\"ל יהי' גילוי שורש המלכות (חד ולא בחושבן) במלכות [ובפרט כמו שירדה בבי\"ע<sup data-n=\"249\">16</sup>] ועי\"ז – בעולמות בי\"ע עד בעוה\"ז הגשמי, ואדרבה, עיקר הגילוי יהי' בעוה\"ז הגשמי, ועי\"ז תושלם הכוונה דדירה בתחתונים<sup data-n=\"250\">17</sup>, שעוה\"ז התחתון שאין תחתון למטה ממנו<sup data-n=\"251\">18</sup> יהי' דירה לו ית', לו לעצמותו<sup data-n=\"252\">19</sup>.\n<b>ועפ\"ז</b> יש לבאר מה שמביא בהשיחה מאמר המדרש אחד עשר מזמורים אמר משה, שבזה מרמז השייכות דהמזמור תפלה למשה לגאולה העתידה, שענינו של מזמור זה [שהוא הראש והתחילה<sup data-n=\"253\">20</sup> דאחד עשר המזמורים] הוא המשכת אחד (חד ולא בחושבן) בעשר (בכל העשר ספירות, עד במלכות). ועפ\"ז יש לבאר מה שממשיךבהשיחה דמעון הוא אותיות נועם<sup data-n=\"254\">21</sup>, דמבואר בהדרושים ד\"ה תפלה למשה<sup data-n=\"255\">22</sup> דמעון הוא מלכות [ונקראת בשם מעון, מלשון דירה ובית ע\"ד ביתו זו אשתו<sup data-n=\"256\">23</sup>] ונועם (תענוג) הוא עתיק, ומעון אותיות נועם הוא ששורש המלכות הוא בעתיק<sup data-n=\"257\">24</sup>. ויש לומר, דזה שמביא בהשיחה בהמשך להענין דאחד עשר שמעון הוא אותיות נועם, הוא לרמז, שהגילוי דאחד (חד ולא בחושבן) בעשר (עשר ספירות) יהי' בעיקר במלכות, כי שורש המלכות הוא בעתיק.\nג) <b>וביאור</b> הענין בפרטיות יותר, יובן ע\"פ מ\"ש אדמו\"ר (מהורש\"ב) נ\"ע במאמר ד\"ה זה<sup data-n=\"258\">25</sup>, דאיתא בזהר<sup data-n=\"259\">26</sup> שתפלה למשה היא תפלת עשיר<sup data-n=\"260\">27</sup>. דזהו החילוק בין תפלה לדוד<sup data-n=\"261\">28</sup> לתפלה למשה, דתפלה לדוד היא תפלת עני ותפלה למשה היא תפלת עשיר. ומדייק בהמאמר, הרי ענין התפלה הוא שמתפלל להקב\"ה שימלא את מחסורו<sup data-n=\"262\">29</sup>, וכיון שהעשיר אינו חסר שום דבר<sup data-n=\"263\">30</sup>, מהו ענין תפלת עשיר. וביותר צריך ביאור ע\"פ מה שארז\"ל<sup data-n=\"264\">31</sup> עה\"פ<sup data-n=\"265\">32</sup> די מחסורו אשר יחסר לו, די מחסורו ואי אתה מצווה לעשרו, אשר יחסר לו אפילו סוס לרכוב עליו ועבד לרוץ לפניו. דמזה מובן שענין העשירות הוא לא רק שאינו חסר שום דבר (אפילו סוס לרכוב עליו ועבד לרוץ לפניו) אלא שהוא מושפע בריבוי השפע<sup data-n=\"266\">33</sup>. ועפ\"ז צריך להבין עוד יותר מהו ענין תפלת עשיר. ומבואר בכ\"מ<sup data-n=\"267\">34</sup> וגם במאמר הנ\"ל<sup data-n=\"268\">35</sup>, דתפלת עשיר היא לא בשביל עצמו. וכדאיתא במדרש<sup data-n=\"269\">36</sup> עה\"פ תפלה למשה, משל למה הדבר דומה לשלשה שבאו ליטול כו' מאת המלך כו', בא השלישי, אמר לו המלך מה אתה מבקש, אמר לו, איני מבקש על עצמי דבר, אלא מדינה פלונית היא חרבה והיא שלך, גזור שתיבנה כו', כך משה לא ביקש לעצמו אלא בשביל ישראל. ולכאורה ביאור זה צריך לביאורנוסף. דכיון שתפלה היא עבודה שבלב<sup data-n=\"270\">37</sup>, הרי מובן, שגם כשמתפלל עבור אחרים התפלה שלו היא באופן שהחסרון שלהם נוגע ללבו (של האדם המתפלל) וכאילו שהוא עצמו הוא החסר (וכל שהחסרון שלהם נוגע לו יותר, תפלתו היא גדולה יותר), הרי, שגם התפלה עבור אחרים היא מצד זה שהוא חסר, ולמה נק' בשם תפלת עשיר.\n<b>ונקודת</b> הביאור בזה הוא, דענין העשירות הוא לא רק שיש לו די צרכיו בהרחבה, ועוד יותר מדי צרכיו, אלא שהוא עשיר בעצם. והענין הוא, דעשיר ועני הוא משפיע ומקבל<sup data-n=\"271\">38</sup>. דמזה מובן, שגם כשיש לו שפע מרובה אבל השפע שיש לו הוא לא משל עצמו אלא שקיבל מאחרים, הוא עני, מקבל. וענין העשיר הוא, <i>שמצד עצמו</i> יש לו הכל [ויש לקשר זה עם מארז\"ל<sup data-n=\"272\">39</sup> אין עני אלא בדעת ואין עשיר אלא בדעת, כי דעת הוא הכרה והרגשה<sup data-n=\"273\">40</sup>, ומהמעלות שבהכרה והרגשה על השכלה והשגה (חכמה ובינה), הוא, דכשאדם משכיל ומבין איזה דבר אין זה שהוא בעצמו יודע את הדבר<sup data-n=\"274\">41</sup> ורק שמקבל<sup data-n=\"274\">41</sup> את הידיעה מהשכל שהשפיע לו ידיעה זו. וענין ההכרה וההרגשה הוא, שהוא בעצמו מכיר ומרגיש את הדבר<sup data-n=\"275\">42</sup>. וזהו שענין העניות והעשירות הוא בעיקר בדעת, דכיון שהידיעה שמצד ההשכלה וההבנה היא כמו ידיעה נקנית אבל הוא <i>בעצמו</i> אינו יודע, לכן, גם לאחרי שיש לו השכלה והבנה הוא נשאר עני (חסר), וע\"י הדעת דוקא הוא יוצא מעניותו ונעשה עשיר. והנה ידוע<sup data-n=\"276\">43</sup> דענין התוקף הוא בדעת. דכשאדם מחליט לעשות איזה דבר מפני שמכיר ומרגיש שכן צריך לעשות, ההחלטה היא בתוקף גדול הרבה יותר מההחלטה שמצד ההבנה וההשגה. והטעם על זה הוא, דהשגה היא בדרך שקו\"ט, שנותנת מקום להשגה אחרת. ולכן ההחלטה שמצד ההשגה אינה בתוקף כ\"כ<sup data-n=\"277\">44</sup>. וההכרה וההרגשה היא בעצם הסברא, דבעצם הסברא אין נתינת מקום לסברא הפכית, ולכן ההחלטה שמצד ההכרה אינה משתנית. ועפ\"ז יש לומר, דזה שהחו\"ב עצמם (בלי דעת) הם בחינת עניות, הוא לא רק בנוגע להאדם [כי הידיעה שמצד חו\"ב היא דבר נוסף על האדם והאדם עצמו הוא חסר הידיעה, עני], אלא גם בנוגע לההשכלה וההשגה עצמם, כיון שבההשגה דחו\"ב יש נתינת מקום להשגה הפכית]. וכיון שהוא עשיר בעצם, הרי מובן, שאין שייך בו חסרון<sup data-n=\"278\">45</sup>. ולכן, הגם שהחסרון של אלה שהתפלל עבורם נוגעלו ביותר, והתפלה שמתפלל עבורם היא כאילו שהוא עצמו הי' החסר, מ\"מ, לא נעשה עי\"ז חסרון בו, ותפלתו היא תפלת עשיר.\nד) <b>ויובן</b> זה בהקדים, דענין העשירות בפשטות הוא, כמובא לעיל (סעיף ג) מהמאמר, שהעשיר יש לו לא רק די צרכיו אלא שהוא מושפע בריבוי השפע. ועפ\"ז, החילוק בין עני גם כשיש לו די מחסורו לעשיר הוא בשני ענינים. שגם באותם הדברים שישנם גם להעני, אינו דומה להעשיר. דהעני מצד עצמו הוא חסר גם דברים אלה (כנ\"ל שם), ורק <i>שבפועל</i> ישנם לו דברים אלה. ושהעשיר הוא מושפע בריבוי השפע – ריבוי שפע שלא ישנו כלל לעני. ולכאורה צריך לומר, דברוחניות, שני הענינים תלויים זה בזה. שבכדי שהענינים שהוא מוכרח בהם (די מחסורו) יהיו אצלו לא באופן שמקבל אותם משל אחרים אלא מצד עצמו, הוא דוקא ע\"י ריבוי השפע שלמעלה ממילוי החסרון. והענין בעבודה הוא, דכשהעבודה של האדם היא רק כפי השגת השכל שלו, אזי, נוסף לזה שהעבודה היא במדידה והגבלה (די מחסורו), הוא חסר (בפנימיות) גם עבודה זו, כיון שמצד ההשגה יש נתינת מקום לההיפך. ובכדי שתהי' עבודתו את ה' באופן שלא ישאר בו שום נתינת מקום לההיפך הוא דוקא ע\"י העבודה שלמעלה ממדידה והגבלה – עשירות.\n<b>ובכדי</b> לבאר ענין העשירות שלמעלה ממילוי החסרון, מקדים בהמאמר<sup data-n=\"279\">46</sup>, שגם במילוי החסרון יש שני ענינים, כמ\"ש די מחסורו אשר יחסר לו ואמרו רז\"ל אשר יחסר לו אפילו סוס לרכוב עליו ועבד לרוץ לפניו. והיינו שדי מחסורו הוא שצריך לספק לו כל הדברים הנצרכים לכל אחד, ולאח\"ז מוסיף אשר יחסר לו, שצריך לספק לו גם זה אשר יחסר <i>לו</i> (סוס לרכוב עליו ועבד לרוץ לפניו) מצד זה שדרכו בכך<sup data-n=\"280\">47</sup>. ועשירות הוא ריבוי שפע, למעלה גם מאשר יחסר לו. ומבאר, דג' ענינים אלה [שני הענינים שבמילוי החסרון ועשירות] ישנם גם למעלה [וכידוע<sup data-n=\"281\">48</sup> שכל הענינים שלמטה משתלשלים מענינם למעלה]. והענין הוא, דבהגילויים שלמעלה יש ג' מדריגות בכללות. ממלא כל עלמין, סובב כל עלמין ועצמות אוא\"ס שלמעלה מממלא וסובב. ממכ\"ע הוא האור המתלבש בעולמות ובהנבראים להחיות אותם לפי ערכם. וכמרז\"ל<sup data-n=\"282\">49</sup> מה הנפש ממלאה את הגוף כך הקב\"ה ממלא את העולם, דכמו שחיות הנפש המתלבש בהגוף הוא לפי אופן אברי הגוף, דבכל אבר החיות הוא לפי ערכו, עד\"ז הוא בהחיות דממלא כל עלמין, שהוא מחי' כל עולם וכל נברא לפי ערכו<sup data-n=\"283\">50</sup>. וסוכ\"ע הוא האור שלמעלה מהתלבשות בעולמות, שלכן הוא סובב ומקיף את העולמות בשוה, אבל שייך לעולמות (שלכן נקרא בשם סובב כל <i>עלמין</i>). והוא ע\"ד חיות הנפש עצמה, מה שהנפש היא חי בעצם, דהגם שהוא למעלה באין ערוךמהחיות המתפשט ומתלבש בגוף, מ\"מ הוא כמו מקור שממנו נמשך החיות המתפשט ומתלבש בהגוף. ובחינה זו נקראת בשם חַי עולמים (חַי בפתח). דהחילוק בין חַי (בפתח) לחֵי (בצירי) הוא, דבחֵי עולמים בצירי, תיבת חֵי דבוקה לעולמים, היינו החיות של העולמות – ממלא, ובחַי עולמים בפתח, תיבת חַי אינה דבוקה לעולמים, היינו בחינת חי בעצם – סובב. ויש לומר, דזה שגם בחינת חי בעצם (סובב) נק' חי <i>עולמים</i> הוא לפי שהוא כמו מקור שממנו נמשך החיות דהעולמות. ומוסיף בהמאמר<sup data-n=\"284\">51</sup>, דבחינת הסובב נק' גם בשם חיי החיים. דחיים הוא החיות המתפשט ומתלבש בעולמות (ממלא), ובחינת הסובב שממנו נמשך החיות דהעולמות נק' חיי החיים. וזהו שארז\"ל<sup data-n=\"285\">52</sup> מחי' חיים יתן לך חיים, דמחי' חיים (בחינת חיי החיים) הוא המקור שמשם נמשכים חיים.\n<b>וזהו</b> שארז\"ל<sup data-n=\"286\">53</sup> ע\"פ<sup data-n=\"287\">54</sup> מזמור שיר ליום השבת, מזמור שיר לעתיד לבוא ליום שכולו שבת ומנוחה לחי העולמים, חַי העולמים בפתח<sup data-n=\"288\">55</sup> הוא בחינת הסובב, ולע\"ל תהי' שביתה ומנוחה גם מבחינת חי העולמים, כי אז יהי' גילוי עצמות אוא\"ס שלמעלה משייכות לעולמות (למעלה גם מסובב). וכמ\"ש<sup data-n=\"289\">56</sup> יחיינו מיומיים ביום השלישי יקימנו ונחי' לפניו, ואיתא בלקו\"ת<sup data-n=\"290\">57</sup> דיומיים הם שני הגילויים דממכ\"ע וסוכ\"ע ויום השלישי הוא גילוי עצמות אוא\"ס שלמעלה משייכות לעולמות. דזהו ביום השלישי יקימנו ונחי' <i>לפניו</i> – פנימיות ועצמות א\"ס. [ולהעיר, דפירוש הפשוט ביומיים ויום השלישי הוא שהם ג' זמנים. יומיים הם עולם הזה וגן עדן או עולם הזה וימות המשיח ויום השלישי הוא תחיית המתים<sup data-n=\"291\">58</sup>. והקשר דשני הפירושים הוא<sup data-n=\"292\">59</sup>, שבשני הזמנים דיומיים הם הגילויים דממלא וסובב, ובתחה\"מ יהי' גילוי העצמות].\n<b>וג'</b> ענינים הנ\"ל – שני הענינים שבמילוי החסרון (די מחסורו ואשר יחסר לו) ועשירות – בהגילויים שלמעלה הם בג' מדריגות הנ\"ל. שני הענינים דמילוי החסרון הם שני הגילויים דממלא וסובב. דכיון שגם אור הסובב שייך לעולמות, לכן,כשאור זה אינו מתגלה בעולם, העולם הוא חסר. וכמאמר רז\"ל<sup data-n=\"293\">60</sup> עה\"פ<sup data-n=\"294\">61</sup> ויכל אלקים ביום השביעי מה הי' העולם חסר מנוחה בא שבת בא מנוחה, מנוחה היא בחינת סובב שלמעלה מהאור המתלבש בעולם, ואעפ\"כ כשלא הי' גילוי זה בעולם, הי' העולם חסר, וכשבא שבת ונמשך ונתגלה אור זה, נתמלא החסרון. ולכן גם הגילוי דסובב הוא מילוי החסרון. אלא שמילוי החסרון שע\"י הגילוי דממלא הוא ע\"ד די מחסורו, ומילוי החסרון שע\"י גילוי הסובב הוא ע\"ד אשר יחסר לו אפילו סוס לרכוב עליו ועבד לרוץ לפניו. ועשירות הוא גילוי עצמות אוא\"ס שלמעלה משייכות לעולמות.\nה) <b>והנה</b> החילוק בין די מחסורו ואשר יחסר לו (בנוגע לעני כפשוטו) הוא לא רק בזה שהשפע דאשר יחסר לו הוא שפע גדול יותר (אפילו סוס לרכוב עליו ועבד לרוץ לפניו), אלא גם שענין אשר יחסר לו הוא דוקא למי שדרכו בכך. וע\"פ הידוע שכל הענינים שבתורה הם בתכלית הדיוק, צריך לומר, שהדמיון דשני הגילויים דממלא וסובב לשני הענינים דדי מחסורו ואשר יחסר לו הוא לא רק מפני שגילוי הסובב הוא גילוי נעלה יותר, אלא גם לפי שהענין דמילוי החסרון שע\"י גילוי הסובב הוא דוקא למי שדרכו בכך. ויש לומר הביאור בזה ע\"פ מ\"ש בהמאמר<sup data-n=\"295\">62</sup>, דג' המדריגות שבאהבה – בכל לבבך, בכל נפשך ובכל מאדך – הם בג' מדריגות הנ\"ל<sup data-n=\"296\">63</sup>. האהבה דבכל לבבך היא בבחינת ממכ\"ע. דע\"י שיתבונן שהחיות של כל דבר הוא אלקות, יבוא לאהבה את ה' בכל לבבך, בשני יצריך<sup data-n=\"297\">64</sup>. דכיון שהחיות דבחינת ממכ\"ע הוא מלובש בהנבראים בפנימיותם, לכן, ע\"י ההתבוננות נרגש חיות זה גם בנפש הבהמית. והאהבה דבכל נפשך היא בבחינת סובב כל עלמין. דע\"י ההתבוננות שהחיות האלקי שמתלבש בעולמות הוא הארה בלבד שבאין ערוך לגבי עצמות אוא\"ס (סובב), נרגש אצלו ההפלאה דאוא\"ס, ועי\"ז יבוא להאהבה דבכל נפשך, שאהבתו את הוי' היא באופן דמסירת נפש (אפילו נוטל את נפשך<sup data-n=\"297\">64</sup>), שרוצה לצאת ממציאותו וליכלל באוא\"ס. ואהבה זו היא רק בנפש האלקית. ושני טעמים לזה. כי ההשגה [באופן דהכרה והרגשה, שאז דוקא מביאה ההשגה לאהבה] בההפלאה דאוא\"ס יכולה להיות רק בנפש האלקית, ששרשה הוא בשם הוי'<sup data-n=\"298\">65</sup>, סובב<sup data-n=\"299\">66</sup>. משא\"כ הנבראים, כיון ששרשם הוא משם אלקים<sup data-n=\"298\">65</sup>, ממלא<sup data-n=\"299\">66</sup>, אי אפשר להיות בהם [אפילו במלאכים ומכ\"ש בנה\"ב] ההשגה (באופן דהכרה והרגשה) בהוי', סובב. וגם, לפי שנפש הבהמית ענינה הוא מציאות, והאהבה דבכל נפשך היא שרוצה <i>לצאת</i> ממציאותו וליכלל באוא\"ס, היפך ענין המציאות. דהאהבה דבכל לבבך, הבאה ע\"יההתבוננות וההכרה שהחיות של כל דבר הוא אלקות, שייכת <i>למציאותו</i> של האדם האוהב. [דכמו שהאדם אוהב את עצמו, היינו שהוא אוהב את החיות ורוצה בהתפשטות החיות בו, כמו\"כ, כשמבין ומרגיש שהעיקר הוא החיות האלקי, הוא רוצה באלקות]. ולכן, אהבה זו שייכת גם לנפש הבהמית. משא\"כ האהבה דבכל נפשך, שהיא הרצון לצאת ממציאותו וליכלל באוא\"ס, היא רק בנפש האלקית. דכיון ששרשה היא בשם הוי' (סובב), וגם לאחרי שירדה למטה היא חלק משם הוי' כמ\"ש<sup data-n=\"300\">67</sup> כי חלק הוי' עמו, לכן יש לה הרצון לצאת ממציאותה וליכלל בשרשה, סובב. וע\"פ הידוע<sup data-n=\"301\">68</sup> שירידת הנשמה למטה היא ירידה צורך עלי', היינו שע\"י ירידתה למטה תתעלה למדריגה נעלית יותר מכמו שהיתה קודם ירידתה, מובן, שהכוונה בירידת הנשמה למטה היא שתתעלה למעלה משרשה, והיא האהבה דבכל מאדך, המס\"נ והכליון בעצמות אוא\"ס שלמעלה גם מסובב. ועפ\"ז יש לומר, דזה שמילוי החסרון שע\"י גילוי הסובב הוא ע\"ד אשר יחסר <i>לו</i> למי שהי' דרכו בכך, הוא, לפי שהנשמות היו רגילים (לפני ירידתם למטה) בגילוי הסובב.\nו) <b>וצריך</b> להבין, דלפי ביאור הנ\"ל, זה שגילוי הסובב הוא בכלל מילוי החסרון הוא דוקא בנוגע לנשמות, משא\"כ בנוגע לנבראים אין שייך לומר לכאורה שגילוי הסובב הוא מילוי החסרון, כיון שאין דרכם בכך. ומזה שמביא בהמאמר מה שארז\"ל מה הי' <i>העולם</i> חסר מנוחה כו', מובן דכשלא ישנו גילוי הסובב (מנוחה) הוא חסרון גם בהעולם. ויש לומר, דכיון שעיקר הכוונה בירידת הנשמה למטה היא (לא בשביל העלי' דהנשמה, אלא) בכדי לתקן [ולהעלות<sup data-n=\"302\">69</sup>] את העולם<sup data-n=\"303\">70</sup>, לכן, ע\"י האהבה דבכל נפשך של הנשמות כמו שירדו למטה בעולם, מתעלה העולם למדריגה נעלית יותר מכמו שהוא מצד עצמו, שנעשה שייך להדרגא דסובב (<i>ע\"ד</i> השייכות דנשמות לסובב), ועד, שכשאינו מאיר גילוי הסובב, העולם הוא חסר.\nז) <b>ויש</b> להוסיף ביאור בזה, ע\"פ מ\"ש בהמאמר<sup data-n=\"304\">71</sup> דשני הענינים דסובב וממלא הם שני השמות דהוי' ואלקים. וכמבואר בכ\"מ<sup data-n=\"305\">72</sup> דשם אלקים הוא לא רק המגן ונרתק שמעלים ומסתיר על האור דשם הוי'<sup data-n=\"306\">73</sup>, אלא שגם האור דשם הוי' כמו שנמשך ומתצמצם ע\"י שם אלקים להיות מקור לנבראים, שבכללות הוא אור הממלא, נקרא אלקים. וע\"פ מ\"ש בתניא<sup data-n=\"307\">74</sup> שהתהוות העולם היא משם הוי' (הוי' לשון מהווה<sup data-n=\"308\">75</sup>), אלא שבאם ההתהוות היתה משם הוי' עצמו הי' העולם בטל במציאות, ולכןההתהוות בפועל היתה ע\"י שם אלקים, יש לומר, שעד\"ז הוא גם בהענין דסובב וממלא, שעיקר חיות העולם הוא מאור הסובב (הוי'), אלא שבכדי שהעולם יהי' מוגבל, המשכת החיות בעולם היא ע\"י ממלא (אלקים). ושני ענינים בזה. שעצם חיות העולם הוא מסובב, אלא שבאם הי' נמשך בו החיות מהסובב עצמו לא הי' העולם מוגבל (כ\"כ) וכל הנבראים היו בשוה [וע\"ד המבואר בתניא<sup data-n=\"309\">76</sup>, דבאם התהוות העולם היתה משם הוי' עצמו לא הי' בו ההתחלקות דזמן ומקום], וע\"י שהחיות (שמהסובב) נמשך ע\"י הממלא (שמתלבש בכל נברא לפי ערכו), נעשה בהם התחלקות. ועוד ענין בזה, שגם החיות דעולם (שבהגבלה ובהתחלקות) שנמשך מאור הממלא הוא (לא מצד עצמו, אלא) מצד הסובב.\n<b>והענין</b> הוא, דמבואר בהמאמר (הובא לעיל סעיף ד), דממלא הוא דוגמת חיות הנפש המתפשט בהגוף וסובב הוא דוגמת חיות הנפש עצמה, חי בעצם. וע\"פ המבואר במק\"א<sup data-n=\"310\">77</sup> דזה שהחיות המתפשט מהנפש מחי' את הגוף הוא לפי שהוא דבוק בהנפש עצמה שהוא חי בעצם [כי הדרגא דהתפשטות החיות (מצד עצמו) אין בכחה להחיות דבר, וזה שהחיות המתפשט מהנפש מחי' את הגוף הוא לפי שהוא דבוק בהנפש שהיא חי בעצם], יש לומר, דכמו\"כ הוא בהענין דממלא וסובב, דהכח שבאור הממלא (התפשטות החיות) להחיות את הנבראים הוא (לא מצד עצמו, אלא) מפני שהוא דבוק בהסובב, חי בעצם. [ועפ\"ז יש לבאר מ\"ש בהמאמר (הובא לעיל סעיף ד) דבחינת הסובב נק' חיי החיים או חַי עולמים (חַי בפתח), דיש לומר, דשני השמות חיי החיים וחי עולמים מורים על שני ענינים. דזה שנק' חיי <i>החיים</i> הוא לפי שממנו נמשך <i>החיות דממלא</i>, וזה שנק' חי <i>עולמים</i> הוא לפי שממנו נמשך הכח בהחיות דממלא להחיות את <i>העולמות</i>]. ויש להוסיף, דזה שבהחיות המתפשט להחיות את הגוף מתגלה הענין דחי בעצם (בזה שביכלתו להחיות את הגוף), אף שעצם הוא למעלה מהתפשטות<sup data-n=\"311\">78</sup>, הוא, לפי שהענין דחי בעצם הוא (גם) העצם של החיות המתפשט<sup data-n=\"312\">79</sup>. [ועפ\"ז י\"ל הכוונה בזה שהסובב נק' חיי החיים, דהחיות (המהות<sup data-n=\"313\">80</sup> והעצם) של החיים (ממלא) הוא הסובב]. ויש לומר, דע\"י שני הענינים שבהחיות המלובש בהעולם – שבגילוי הוא חיות מוגבל, ושבפנימיות הוא בלתי מוגבל (שלכן ביכלתו להוות את הנבראים, כנ\"ל) – ישנם דוגמת שני ענינים אלה בהעולם. דבחיצוניות, החיות שהעולם צריך אליו הוא רק חיות מצומצם ומועט[וגילוי הסובב הוא בכלל עשירות]. ובפנימיות העולם, נרגש הפנימיות של החיות שבו, דזה שיש בו הכח להחיות הוא לפי שהוא דבוק בהדרגא דחי בעצם. וע\"י הדרגא דבכל נפשך דהנשמות מתגלה הפנימיות דהעולם. ועי\"ז, גם <i>העולם</i> חסר הגילוי דסובב, וע\"י גילוי הסובב נתמלא החסרון דהעולם.\nח) <b>ועד\"ז</b> הוא בענין העשירות, גילוי עצמות אוא\"ס שלמעלה מסובב, שע\"י גילוי ענין זה בנש\"י, יהי' לע\"ל <i>מעין</i> גילוי זה גם בעולם<sup data-n=\"314\">81</sup>. ועפ\"ז יש לבאר מ\"ש בהמאמר<sup data-n=\"315\">82</sup> בביאור מאמר המדרש שתפלת משה היתה לא בשביל עצמו אלא בשביל ישראל, שכנסת ישראל היא בחינת מלכות, ובקשת משה (תפלת עשיר) בשביל כנס\"י היתה שיומשך במלכות גילוי עצמות אוא\"ס (עשירות) [ועפ\"ז מבאר שם מ\"ש במדרש דבקשת משה עבור ישראל היא ע\"ד הבקשה מדינה פלונית כו' גזור שתיבנה, דמדינה הוא מלכות והבקשה גזור שתיבנה היא שיומשך גילוי עצמות אוא\"ס במלכות שעי\"ז תיבנה בבחינת בנין עדי עד]. וצריך ביאור, דבקשת משה בשביל ישראל היתה בשביל ישראל כפשוטם כמבואר במדרש, ובהמאמר מבאר שבקשת משה בשביל כנס\"י היא בשביל המלכות. ויש לומר, דע\"י המשכת גילוי עצמות אוא\"ס בישראל, עי\"ז יהי' גילוי זה במלכות, השורש דעולם, ועי\"ז – בהעולם. ולהוסיף, דכמו שנת\"ל (סעיף ז) בענין גילוי הסובב שנמשך בעולם ע\"י ישראל, שזהו ע\"י שמגלים הפנימיות דהחיות של העולם, עד\"ז הוא בנוגע להגילוי דאוא\"ס שלמעלה מסובב שנמשך ע\"י ישראל בעולם, שזהו ע\"י שמגלים פנימיות ושורש המלכות. וכמבואר בהמאמר<sup data-n=\"316\">83</sup> בפירוש מדינה פלונית היא שלך, דשורש המלכות הוא בהעצמות.\n<b>ויש</b> לומר, דמהטעמים על זה שמביא בהמאמר (הובא לעיל סעיף ד) מ\"ש יחיינו מיומיים ביום השלישי גו' ומבאר דיומיים הם ב' הגילויים דממלא וסובב ויום השלישי הוא גילוי עצמות אוא\"ס, וג' גילויים אלו מתגלים בג' זמנים, הוא לרמז, דהגם שזמן הוא מגדרי העולם&lt;76&gt; והחיות דהעולם (המלובש בו בפנימיותו) הוא ממלא, מ\"מ, שייך העולם גם לסובב וגם לאוא\"ס שלמעלה מסובב. ולהעיר, שעד\"ז הוא בנוגע למקום [שגדר העולם הוא מקום וזמן&lt;76&gt;], דענין המקום שבעולם הוא שיש בו חילוקי דרגות מעלה ומטה<sup data-n=\"317\">84</sup>, דהגם שההתחלקות מעלה ומטה שבעולם הוא מצד החילוק בהחיות המלובש בו, ממלא [כמארז\"ל<sup data-n=\"318\">85</sup> נטה ימינו וברא שמים נטה שמאלו וברא ארץ, דשמים (עולמות העליונים) הם מבחינת ימין וארץ (עולמות התחתונים) הם מבחינת שמאל, והחילוק דימין ושמאל הוא בהחיות דבחינת ממלא כמ\"ש בהמשך ההילולא<sup data-n=\"319\">86</sup> ומובן גם בפשטות], מ\"מ, כללות כל העולמות נחלקים לשלשהעולמות בריאה יצירה ועשי'<sup data-n=\"320\">87</sup>, שהם <i>דוגמת</i> ג' גילויים הנ\"ל. וכמבואר בכ\"מ<sup data-n=\"321\">88</sup>, שחומר (בריאה), עצם המציאות שלמעלה מצורה וגילוי, הוא דוגמת העלם העצמי דעצמות אוא\"ס, וצורה (יצירה), גילוי החומר, הוא דוגמת הסובב שהוא גילוי עצמות אוא\"ס, ותיקון (עשי'), ציור פרטי, הוא דוגמת הממלא שמתלבש בכל עולם ובכל נברא לפי ערכו. וזהו גם מ\"ש בהמאמר<sup data-n=\"322\">89</sup> בפירוש נוסח ברכת בורא נפשות, דחסרונן לשון רבים הם ב' הענינים דמילוי החסרון שמצד ממכ\"ע וסוכ\"ע, ועל כל מה שבראת להחיות בהם, דפירש בטור<sup data-n=\"323\">90</sup> שהם דברים הבאים לעידון ולתענוג, הו\"ע ריבוי השפע דעשירות שמצד גילוי עצמות אוא\"ס, דיש לומר, שמהטעמים שמביא פירוש זה בהמאמר, הוא לרמז, שגם בעולם העשי' (כולל גם עוה\"ז הגשמי) ישנם ג' הענינים.\n<b>אלא</b> שהחיות האלקי המלובש בהעולם (ממלא) הוא בגילוי בהעולם, וזה שגם גילוי חיות זה הוא ע\"י העבודה דישראל [וכמו שנתבאר בד\"ה זאת חוקת התורה<sup data-n=\"324\">91</sup> שגילוי ג' הענינים דממלא סובב ועצמות אוא\"ס הוא ע\"י ג' האהבות דבכל לבבך ובכל נפשך ובכל מאדך], הוא, כי זה שהחיות דממלא הוא בגילוי בהעולם הוא שבהעולם נרגש שהוא חי, אבל אין נרגש בו שהחיות שבו הוא אלקות, וע\"י העבודה דישראל נרגש בהעולם שהחיות שבו הוא אלקות. וגילוי זה הוא גם עכשיו, בעולם הזה. והחיות דסובב שאינו מלובש בהעולם ורק סובב ומקיף עליו, ומכש\"כ אוא\"ס שלמעלה מסובב – <i>המשכתם</i> בעולם היא ע\"י העבודה דישראל, והגילוי דהמשכות אלו יהי' לע\"ל, בימות המשיח (גילוי הסובב) ותחיית המתים (גילוי עצמות אוא\"ס שלמעלה מסובב), כנ\"ל (סעיף ד).\nט) <b>ומבאר</b> בהמאמר<sup data-n=\"325\">92</sup>, דזה שמשה נקרא עשיר [וכנ\"ל סעיף ג שתפלה למשה היא תפלת עשיר] הוא לפי שמשה הוא בחינת דעת עליון. והענין הוא, דדעת תחתון מקבל מחיצוניות הכתר, אריך, ודעת עליון מקבל מפנימיות הכתר, עתיק. והחילוק בין אריך לעתיק הוא, שאריך הוא שורש ומקור הנאצלים, בחי' סובב [וכנ\"ל סעיף ד שסובב הוא כמו מקור לעולמות], ועתיק הוא בחינה תחתונה שבמאציל, עצמות אוא\"ס שלמעלה מגדר עולמות. וכיון שגילוי הסובב (אריך) הוא בכלל מילוי החסרון וענין העשירות הוא דוקא בעצמות אוא\"ס שלמעלה מסובב (עתיק), לכן, גם בדעת, ענין העשירות הוא דוקא בדעת עליון שמקבל מפנימיות הכתר.\n<b>וע\"פ</b> המבואר לעיל סעיף ד דשלילת העניות (חסרון) היא דוקא ע\"י העשירות שלמעלה ממילוי החסרון, משא\"כ כשהשפע הוא רק די מחסורו [כולל גםהענין דאשר יחסר <i>לו</i>, אפילו סוס לרכוב עליו ועבד לרוץ לפניו] נשאר (בפנימיות) חסרון גם בנוגע לשפע המצומצם, צריך לומר, דגם כשהעבודה היא מצד הדעת, הכרה והרגשה, אבל רק דעת תחתון שמקבל מאריך, העבודה היא כמו דבר נוסף עליו, והאדם <i>עצמו</i> (בפנימיותו) חסר העבודה, היינו שנשאר מקום בהאדם ששם אין מאיר גילוי אלקות. דהגם שענין ההכרה וההרגשה (גם דדעת תחתון) הוא שהאדם <i>עצמו</i> מכיר ומרגיש (כנ\"ל סעיף ג), מ\"מ, כיון שענינו של האדם הוא מציאות (ולא שענינו הוא הרגשת אלקות), הרי ההכרה וההרגשה שלו באלקות היא כמו דבר נוסף עליו.\n<b>ובעומק</b> יותר יש לומר, דזה שבהעבודה דדעת תחתון נשאר עדיין חסרון, הוא לא רק מפני שהאדם וההכרה שלו באלקות הם שני דברים, אלא שגם מצד ההכרה עצמה (ההכרה דדעת תחתון) יש נתינת מקום למציאות שמחוץ לאלקות<sup data-n=\"326\">93</sup>. דכיון שדעת תחתון מקבל מחיצוניות הכתר, אריך, דבכללות הוא בחינת סובב שהוא כמו מקור לעולמות, לכן, גם מצד הדעת עצמו יש נתינת מקום למציאות. וזה גופא הוא הסיבה לזה שע\"י הגילוי דדרגא זו בהאדם נשאר הוא במציאותו, מציאות שמחוץ לאלקות. ובכדי שיתמלא החסרון לגמרי, היינו שלא יהי' שום מקום שאין מאיר בו גילוי אלקות, הוא ע\"י העבודה דדעת עליון שמקבל מפנימיות הכתר, עתיק, דבכללות הוא עצמות אוא\"ס. דלגבי עצמות אוא\"ס אין שום מציאות שחוץ ממנו, ואדרבה, אמיתית המצאו ית' היא היא אמיתית המציאות של כל הנמצאים<sup data-n=\"327\">94</sup>. ולכן ע\"י הגילוי דדעת עליון, הכרת האדם באלקות היא באופן שזה (הכרת אלקות) היא כל מציאותו.\n<b>ועפ\"ז</b> יש לבאר מה שתפלת משה למלאות החסרון דכנסת ישראל נקראת בשם תפלת עשיר, אף שהחסרון דכנס\"י הי' בודאי נוגע לו במאד, כי משה הוא בחינת דעת עליון (כנ\"ל), ומצד דעת עליון, ענין העשירות, אין שייך ענין החסרון. היינו, דנוסף לזה שבמשה עצמו אין שייך שום חסרון ח\"ו, אלא שלגבי משה, גם החסרון דכנס\"י שהתפלל עליהם אינו חסרון, כי דעת עליון מקבל מעתיק, ולכן נרגש בו שאמיתית המצאו ית' הוא אמיתית המציאות של כל הנמצאים ואינם חסרים מאומה. והגם שמשה התפלל עליהם, דענין התפלה הוא למלאות החסרון – יש לומר, שהתפלה שלו היתה שענין זה (שהאמת היא שאינם חסרים מאומה) יהי' נרגש בגילוי גם אצלם. אבל במשה הי' נרגש זה (שאינם חסרים מאומה) בגילוי גם כשהיו במצב שהוצרך להתפלל עליהם, ולכן, התפלה שלו היא תפלת עשיר. ולהוסיף, דזה שתפלת משה נקראת תפלת עשיר הוא לא רק מפני שגם אז (בעת התפלה) הי' עשיר, אלא יתירה מזה, שהתפלה שלו היתה <i>מפני</i> שהוא עשיר. כי תפלת משה שיתמלא החסרון דכנס\"י [דכנס\"י כפשוטו, ועי\"ז – החסרון דמלכות, ודהעולם] הוא שיתמלא החסרון לגמרי, שלא יהי' שום מקום שאין מאיר בו גילוי אלקות, ובכדי שיתמלא החסרון <i>לגמרי</i> הוא דוקא ע\"י הגילוי דדעת עליון, כנ\"ל.יו\"ד) <b>ויש</b> לומר, דע\"י שדוד כתב המזמור תפלה למשה בספר תהלים שנאמר ע\"י כל ישראל, גם ע\"י אנשים פשוטים, ניתן הכח לכאו\"א מישראל, לגלות בחינת העשירות שבו (מצד בחינת משה שבכ\"א מישראל<sup data-n=\"328\">95</sup>), ועי\"ז – למלאות החסרון דמלכות ודהעולם, מילוי החסרון לגמרי, שלא יהי' מקום בעולם שאין מאיר בו גילוי אלקות. ויש לקשר זה עם מאמר המדרש<sup data-n=\"329\">96</sup> בפירוש איש האלקים, בשעה שעלה לרקיע איש ובשעה שירד מן הרקיע אלקים, ומבאר כ\"ק מו\"ח אדמו\"ר בשיחה הנ\"ל (שהובאה בתחילת המאמר)<sup data-n=\"330\">97</sup>, דאדם (מוחין<sup data-n=\"331\">98</sup>) הוא למעלה מאיש (מדות<sup data-n=\"331\">98</sup>), ומ\"ש במדרש בשעה שעלה לרקיע איש הוא להורות שגם בעת התפלה, כשמתבונן בדרגות הכי נעלות ומשיג אותם בטוב, עולה לרקיע, צריך לזכור שהוא איש, שיש לו מדות שצריך לבררם ולזככם, ועי\"ז, בשעה שיורד מן הרקיע (לאחרי התפלה) הוא אלקים, אלקים מלשון דין<sup data-n=\"332\">99</sup> ואלקים מלשון כח וגבורה<sup data-n=\"333\">100</sup>, שהוא בעל כח וגבורה לעשות דין בעצמו שהנהגתו בפועל תהי' כדבעי.\n<b>וע\"פ</b> המבואר דענינו של משה (המודגש בתפלה למשה) הוא זה שמשה הי' עשיר, צריך לומר, שהעבודה דאיש האלקים שייכת לענין העשירות. והענין הוא, דג' הענינים שלמעלה (ממלא, סובב ואוא\"ס שלמעלה מסובב) יש דוגמתם באדם. שהגילויים דהנשמה הם דוגמת הגילויים דממלא וסובב, ועצם הנשמה היא דוגמת עצמות אוא\"ס. וכמו שלמעלה, מצד הגילויים דממלא וסובב יש נתינת מקום למציאות שמחוץ לאלקות וזה שאמיתית המציאות של כל הנמצאים הוא אלקות הוא דוקא מצד עצמות אוא\"ס (כנ\"ל סעיף ט), עד\"ז הוא בעבודת האדם, שבכדי שההתבוננות שבתפלה תהי' באופן שתפעול על הנהגתו במשך כל היום, איש האלקים, הוא ע\"י שהתפלה שלו קשורה עם עצם הנשמה, משה, עשירות.\nיא) <b>ולהוסיף</b><b>,</b> דמבואר בהמאמר<sup data-n=\"334\">101</sup>, שבתפלת משה על כנס\"י, היא ספירת המלכות, שני ענינים. המשכת הארה מעצמות אוא\"ס שעי\"ז אפשר להיות עליית המלכות (מלמטה למעלה) בעצמות אוא\"ס, ועי\"ז נעשה אח\"כ המשכת העצמות במלכות (מלמעלה למטה). ויש לומר, דשני ענינים אלה (במלכות) הם ע\"י שני הענינים באיש האלקים [בשעה שעלה לרקיע איש ובשעה שירד מן הרקיע אלקים] שבעבודת האדם. דע\"י העבודה דבשעה שעלה לרקיע איש, שגם בההתבוננות דתפלה הוא זוכר שיש לו מדות שצריך לבררם ולזככם, דזה שהתפלה שלו היא באופן זה הוא ע\"ישהתפלה שלו קשורה עם עצם הנשמה (כנ\"ל סעיף יו\"ד), הוא המשכת הארה מעצם הנשמה (מלמעלמ\"ט) שעי\"ז מתעלים ענינים התחתונים שבו להתפלה – עי\"ז נמשך הארה מעצמות אוא\"ס לרומם ולהעלות את המלכות לשרשה בהעצמות. וע\"י העבודה דבשעה שירד מן הרקיע אלקים, דע\"י שהתפלה קשורה עם עצם הנשמה היא פועלת על הנהגתו במשך כל היום, הוא המשכת וגילוי עצם הנשמה בענינים התחתונים שבו – עי\"ז הוא המשכת וגילוי העצמות במלכות, גזור שתיבנה בבחינת בנין עדי עד.\n<b>ויש</b> לומר דזהו שהתחלת המזמור הוא אד' <i>מעון</i> אתה גו', וסיום המזמור הוא ויהי <i>נועם</i> אד' גו', דבתחלת המזמור מדבר בענין המלכות כמו שעולה בשרשה בעתיק, ולכן נאמר מעון שקאי על המלכות (כנ\"ל סעיף ב) אלא שמעון הוא אותיות נועם שמורה על עליית המלכות בעתיק, ובסיום המזמור מדבר בענין עתיק (נועם) שנמשך במלכות, וע\"י המלכות – בעולמות בי\"ע עד בעוה\"ז הגשמי. ונאמר ויהי נועם אד' אלקינו <i>עלינו</i>, כי עיקר הגילוי הוא לישראל, ועי\"ז יומשך מעין גילוי זה בכל העולם&lt;71&gt;, בגאולה האמיתית והשלימה ע\"י משיח צדקינו, בקרוב ממש.\n**********",[["233","*","יצא לאור ב<b>קונטרס י\"א ניסן – תנש\"א</b>, \"לקראת יום הבהיר י\"א ניסן תחילת שנת הצדי\"ק להולדת כ\"ק אדמו\"ר שליט\"א . . <i>מוצש\"ק צו</i>,<i> שבת הגדול</i>,<i> שנת ה'תנש\"א</i>*\"."],["234","1","תהלים צדי\"ק**, א."],["235","2","ליל כ' כסלו תרצ\"ד (לקו\"ד כרך א צז, א ואילך)."],["236","3","לקו\"ד שם. וכן נהגו הנשיאים שלאחריו, ממלאי מקומו – מכתב כ\"ק מו\"ח אדמו\"ר, נדפס ב\"קובץ מכתבים\" שבסו\"ס תהלים אהל יוסף יצחק (ע' 200). אגרות-קודש שלו ח\"ג ע' תעג ואילך."],["237","4","וברד\"ק עה\"פ: תפלה זו מצאה דוד כתובה, והיתה קבלה אצלם שהיתה למשה רבינו, וכתבה בספרו זה."],["238","5","שוחר טוב עה\"פ. הובא בפרש\"י עה\"פ."],["239","6","פסוק י\"ז (בגימטריא טו\"ב)."],["240","7","ספר השיחות תורת שלום ס\"ע 112 ואילך."],["241","8","כמ\"ש באגה\"ק הידועה דהבעש\"ט, נדפסה גם בכתר שם טוב בתחלתו."],["242","9","ראה שמו\"ר פ\"ב, ד. זח\"א רנג, א. שעה\"פ להאריז\"ל פ' ויחי. תו\"א ר\"פ משפטים.\n*) <i>בי\"ב תמוז זה התחילה שנת הצדי\"ק להולדת כ\"ק אדמו\"ר מהוריי\"צ נ\"ע</i>,<i> והתחילו לומר אז מזמור צדי\"ק שבתהלים – ע\"פ המנהג (דלהלן בשוה\"ג הבא) לומר בכל יום הקאַפּיטל תהלים המתאים לשנות חייו</i>.\n**) <i>ע\"פ המנהג לומר בכל יום הקאַפּיטל תהלים המתאים לשנות חייו (מכתב כ\"ק מו\"ח אדמו\"ר</i>,<i> נדפס ב</i>\"<i>קובץ מכתבים</i>\"<i> שבסו\"ס תהלים אהל יוסף יצחק (ע' 214)</i>.<i> אגרות-קודש שלו ח\"א ע' לא</i>.<i> ח\"י ע' נג</i>.<i> וראה גם מאמרי אדה\"ז הקצרים ע' שמא</i>.<i> סה\"מ י\"א ניסן ע' 1 ואילך) – מתחילים בי\"א ניסן שנה זו (תנש\"א – שנת הדפסת המאמר) אמירת מזמור צדי\"ק שבתהלים</i>."],["243","10","וכידוע דבגאולת מצרים נתחדש כללות ענין הגאולה ונפתח הצינור על כל הגאולות, גם על גאולה העתידה (ד\"ה כימי צאתך ה'תש\"ח פי\"ב – סה\"מ ה'תש\"ח ע' 164)."],["244","11","מיכה ז, טו."],["245","12","תקו\"ז בהקדמה (יז, א)."],["246","13","אוה\"ת דברים ע' יט. אוה\"ת (יהל אור) לתהלים ע' מח. סה\"מ עטר\"ת ע' תקפז."],["247","14","ראה <i>עד\"ז</i> אוה\"ת דברים ויהל אור שם.\nועפ\"ז יש לבאר מ\"ש במדרש (שמו\"ר פמ\"ב, ח, הובא בסה\"מ עטר\"ת שם) ש\"אחד עשר\" רומז על \"מיוחד שבעשרה כו' אנכי ה' אלקיך\" – דלכאורה, הרי גם \"אנכי\" הוא בכלל עשרת הדברות, ואיך זה מתאים עם הביאור שאחד עשר הוא פנימיות הכתר שאינו נמנה במנין הספירות, חד <i>ולא</i> בחושבן, וגם במדרש נקרא \"מיוחד <i>שבעשרה</i>\"*? וע\"פ מ\"ש בפנים יש לומר, דזה שגם אנכי (חד ולא בחושבן) נכלל בעשרת הדברות הוא, כי הכוונה דמתן תורה היא להמשיך \"אחד\" ב\"עשר\", ע\"ד הפירוש ד\"אחד עשר\" שבפנים."],["248","15","ע\"ח שער מב (שער דרושי אבי\"ע) פ\"א, הובא בסה\"מ עטר\"ת שם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380276\" data-slug=\"likkutei-torah\" data-id=\"4001380276\">לקו\"ת בחוקותי מו, ג</a>. ובכ\"מ. ע\"ח שער כג (שער מוחין דצלם) פ\"ה, הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381170\" data-slug=\"likkutei-torah\" data-id=\"4001381170\">לקו\"ת שה\"ש י, ב</a>. ובכ\"מ."],["249","16","ראה לקמן הערה 24."],["250","17","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו."],["251","18","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["252","19","המשך תרס\"ו ס\"ע ג. ובכ\"מ. – נסמנו לעיל ח\"ב ע' שח הע' 32."],["253","20","היינו שבעתיק עצמו הוא הראש והתחילה. ולכן, המשכתו בעשר (השתלשלות) היא בה\"סיום\" שלהם, ע\"ד <i>סוף</i> מעשה במחשבה <i>תחלה</i> (ד\"ה ביום השני גו' ה'תשל\"ב (לעיל ח\"ג ע' שנא ואילך). ובכ\"מ).\n*) <i>בסה\"מ עטר\"ת שם דב</i>\"<i>אנכי</i>\"<i> נכללים ב' הבחינות שבכתר</i>.<i> ובזה מבאר ב' הדיעות אם אנכי נמנה בתרי\"ג מצוות או שאינו נמנה – שפנימיות הכתר אינו נמנה</i>,<i> וחיצוניות הכתר נמנה</i>.<i> אבל לכאורה אין זה ביאור על הדיוק שבפנים ההערה</i>,<i> כי מפורש שם (ריש ע' תקפח) ד</i>\"<i>מיוחד שבעשרה</i>\"<i> הוא </i>\"<i>חד ולא בחושבן</i>\",<i> וצריך ביאור השייכות דבחינת </i>\"<i>חד </i><b>ולא</b><i> בחושבן</i>\"<i> ל</i>\"<i>מיוחד </i><b>שבעשרה</b>\".<i> ואכ\"מ</i>."],["254","21","לקו\"ת וס' הליקוטים להאריז\"ל עה\"פ."],["255","22","מאמרי אדה\"ז – אתהלך לאזניא ע' קנז. סה\"מ תר\"ס ע' נט."],["256","23","משנה ריש מסכת יומא. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381130\" data-slug=\"likkutei-torah\" data-id=\"4001381130\">לקו\"ת ברכה ק, ב</a>."],["257","24","בסה\"מ אתהלך לאזניא ובסה\"מ תר\"ס שם, דפירוש הכתוב \"מעון אתה היית לנו בדור ודור\" הוא המלכות כמו שירדה בבי\"ע להוות הזמן. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381129\" data-slug=\"likkutei-torah\" data-id=\"4001381129\">לקו\"ת ברכה שם (ק, א</a>-ב), דזה שהמלכות נקראת \"בית\" [הן מצד זה שהיא דרגא הכי תחתונה, כמו בית שעשוי מאבנים, דומם, והן מצד זה ששורש המלכות הוא בעתיק, כמו בית שהוא מקיף הרחוק] – הוא בעיקר בירידתה בבי\"ע."],["258","25","דשנת תר\"ס – נדפס בסה\"מ תר\"ס ע' מט ואילך."],["259","26","ראה זח\"א קסח, ב."],["260","27","ראה גם נדרים לח, א שמשה הי' עשיר."],["261","28","תהלים פו, א."],["262","29","ראה רמב\"ם הל' תפלה פ\"א ה\"ב."],["263","30","ראה ד\"ה זאת חוקת התורה דש\"פ חו\"ב י\"ב תמוז שנה זו (תשכ\"ט (לעיל ס\"ע כה ואילך)), דזה שמשה הי' עשיר בגשמיות הוא לפי שהי' עשיר ברוחניות."],["264","31","כתובות סז, ב."],["265","32","ראה טו, ח."],["266","33","כ\"ה הלשון בסה\"מ תר\"ס ע' נד."],["267","34","המשך תער\"ב ח\"ב ס\"פ שעה (ס\"ע תשעא ואילך). ספר השיחות תורת שלום ע' 183."],["268","35","ע' נח."],["269","36","שוחר טוב ויל\"ש עה\"פ. מדרש תהלים באָבער שם."],["270","37","תענית ב, א."],["271","38","ראה שמו\"ר פל\"א, ה. תנחומא משפטים ט. וראה סה\"מ תרכ\"ז ע' שצט ואילך. קונטרסים ח\"א (קיט, א ואילך)."],["272","39","ראה נדרים מא, א: אין עני אלא בדעה. כתובות סח, א: עני – עני בדעת; עשיר – עשיר בדעת."],["273","40","סה\"מ עת\"ר ע' קטו ואילך. (תרפ\"ח ע' פג ואילך). ובכ\"מ."],["274","41","כ\"ה הלשון בהמשך תער\"ב ח\"ב פשמ\"ה (ע' תשח), אלא ששם מבואר ענין זה בנוגע לבינה דוקא (משא\"כ בחכמה)."],["275","42","להעיר מסה\"מ עת\"ר שם (ע' קיד. שם ע' קטז), דענין הלימוד הוא בחכמה ובינה, משא\"כ הדעת היא בכח עצמו דוקא. אלא שבסה\"מ עת\"ר שם מדבר בענין לימוד שרב מלמד את תלמידו וכיו\"ב. ויש לומר, שעד\"ז הוא בהאדם עצמו, דבחו\"ב – החו\"ב <i>מלמדים</i> את האדם עצמו, משא\"כ הדעת."],["276","43","ראה סה\"מ עת\"ר ע' קיח (וראה שם ריש ע' קיט). תרפ\"ח ע' פה."],["277","44","דנוסף לזה <i>שמצד האדם</i> אין ההחלטה בתוקף, לפי שהידיעה שמצד ההשגה היא כמו ידיעה נקנית (כנ\"ל בפנים) – גם מצד ההשגה אין ההחלטה בתוקף כ\"כ, כבפנים."],["278","45","ראה סה\"מ תרצ\"ט ע' 206, דענין העשירות הוא ש\"אינו שייך ענין החסרון כלל\"."],["279","46","סה\"מ תר\"ס שם ס\"ע נג ואילך."],["280","47","רמב\"ם הל' מתנות עניים פ\"ז ה\"ג."],["281","48","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>."],["282","49","מדרש תהלים מזמור קג. ובברכות י, א: מה הקב\"ה מלא כל העולם אף נשמה מלאה את כל הגוף. ובויק\"ר פ\"ד, ח: הנפש הזו ממלא את הגוף והקב\"ה ממלא את עולמו."],["283","50","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380211\" data-slug=\"likkutei-torah\" data-id=\"4001380211\">לקו\"ת אמור לא, ב</a>. ובכ\"מ."],["284","51","סה\"מ תר\"ס שם ע' נה-ו."],["285","52","יומא עא, א."],["286","53","סוף מס' תמיד."],["287","54","תהלים צב, א."],["288","55","בסה\"מ תר\"ס שם (ע' נו) \"ועי\"ש בתויו\"ט שצ\"ל חי בפתח\". וצ\"ע דבתויו\"ט שם מפורש שצ\"ל חי בצירי. ואולי יש לומר דבהמאמר מביא מתויו\"ט \"שצ\"ל חי\" (ולא חיי), ולאח\"ז מוסיף עוד ענין (<i>לא</i> מהתויו\"ט) – \"בפתח\". אבל גם לפירוש זה צ\"ע, כי גירסת התויו\"ט שם היא \"חיי\" (בשני יודי\"ן) אלא שמקיים גם גירסת הרע\"ב \"חי\" (ביו\"ד אחד), והלשון בסה\"מ תר\"ס שם הוא \"<i>שצ\"ל</i> חי\"."],["289","56","הושע ו, ב."],["290","57","דרושים לר\"ה סד, א."],["291","58","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600433\" data-slug=\"or-hatorah-hb\" data-id=\"8316600433\">אוה\"ת נ\"ך</a> להושע שם ס\"ג-ד (ע' תלג)."],["292","59","ראה גם ד\"ה יחיינו מיומיים תרנ\"ט (סה\"מ תרנ\"ט ע' טו-ז), תרצ\"א (סה\"מ קונטרסים ח\"א קמז, א). בסה\"מ תרנ\"ט שם [ועד\"ז בסה\"מ קונטרסים שם] \"יומיים שהם עוה\"ז וג\"ע . . בחי' ממכ\"ע וסוכ\"ע\". אבל בכ\"מ, שבג\"ע הוא גילוי הממלא והגילוי דסובב יהי' בימות המשיח (ראה ד\"ה לה\"ע תחיית המתים ה'תשמ\"ו ס\"ד ואילך (לעיל ח\"ג ע' רכג ואילך). וש\"נ)."],["293","60","פרש\"י עה\"פ בראשית ב, ב. פרש\"י ד\"ה ויכל – מגילה ט, א (וראה ב\"ר פ\"י, ט). תוד\"ה חצבה – סנהדרין לח, א."],["294","61","בראשית שם."],["295","62","סה\"מ תר\"ס שם ע' נד ואילך."],["296","63","ראה גם לעיל ח\"א ע' צב ואילך. <i>וש\"נ</i>."],["297","64","ואתחנן ו, ה. ברכות נד, א במשנה. ספרי (הובא בפרש\"י) עה\"פ."],["298","65","אגה\"ת פ\"ד (צד, א)."],["299","66","ראה לקמן סעיף ז."],["300","67","האזינו לב, ט. וראה אגה\"ת שם (צג, סע\"ב)."],["301","68","ראה לעיל ח\"א ס\"ע רמז ואילך, ובהנסמן בהערות שם. <i>ובכ\"מ</i>."],["302","69","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310036\" data-slug=\"tanya\" data-id=\"3401310036\">תניא פל\"א (מ, סע\"ב</a>)."],["303","70","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>)."],["304","71","סה\"מ תר\"ס שם ע' נה."],["305","72","המשך תרס\"ו ע' רכב. ובכ\"מ. וראה גם סהמ\"צ להצ\"צ סב, א דענין יחוד הוי' ואלקים הוא היחוד דסובב וממלא."],["306","73","כמ\"ש (תהלים פד, יב) כי שמש ומגן הוי' אלקים – שעהיוה\"א רפ\"ד."],["307","74","שעהיוה\"א שם."],["308","75","שעהיוה\"א שם. וראה זח\"ג רנז, סע\"ב. פרדס שער א (שער עשר ולא תשע) פ\"ט."],["309","76","שעהיוה\"א פ\"ז (פב, א)."],["310","77","ד\"ה בראשית ברא ה'תשי\"ג פ\"ג (תורת מנחם – התוועדויות ח\"ז ע' 123 ואילך). וראה גם המשך תרס\"ו ע' קעז."],["311","78","דזה שאור הוא מעין המאור, הוא ע\"ד כמו שהוא באור השמש דזה שהוא אור הוא לפי שהשמש היא בהירה (המשך תרס\"ו שם. ובכ\"מ), שעד\"ז הוא בהתפשטות הנפש, דלפי שהנפש היא חי בעצם לכן ההתפשטות דהנפש הוא <i>חיות</i>. אבל אין זה ביאור לכאורה על זה שבהחיות המתפשט מתגלה הענין דחי <i>בעצם</i>. וראה הערה הבאה."],["312","79","לכאורה, עד\"ז הוא באור, ש\"מהותו הוא המאור\" (סה\"מ ה'תש\"ג ע' 174. ובכ\"מ). אבל יש לומר, דזה שאור מהותו הוא המאור הוא – שכל מהותו הוא <i>גילוי</i> המאור, היינו שישנם שני ענינים: המאור עצמו וגילוי המאור. משא\"כ בחיות, באם מהותו של החיות המתפשט הי' זה שהוא \"<i>גילוי</i> הנפש\", לא הי' מתגלה בו הענין דחי <i>בעצם</i>. ולכן צ\"ל שמהותו של החיות המתפשט הוא הענין דחי בעצם עצמו כמו שהוא בגילוי."],["313","80","ראה סה\"מ ה'ש\"ת ע' 12."],["314","81","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא ספל\"ו (מו, ב</a>)."],["315","82","סה\"מ תר\"ס ע' נח."],["316","83","שם ע' סב."],["317","84","ראה רמב\"ם הל' יסוה\"ת פ\"ב ה\"ו."],["318","85","ראה פדר\"א פי\"ח. זהר ח\"א ל, א. ח\"ב כ, א. לז, א. פה, ב."],["319","86","באתי לגני ה'שי\"ת פ\"א (סה\"מ ה'תש\"י ע' 12-111)."],["320","87","<a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא פמ\"ט (סט, א</a>)."],["321","88","הגהות לד\"ה פתח אלי' תרנ\"ח ע' יא ואילך."],["322","89","ס\"ע נז ואילך."],["323","90","או\"ח סימן רז. הובא גם בשו\"ע אדה\"ז שם ס\"ב.\nבטור שם מפרש גם חסרונן. וי\"ל, דזה שבהמאמר מביא פירוש הטור רק על \"להחיות בהם\" – כי לפי פירוש הטור \"חסרונן\" הוא \"צרכי סיפוקן כו' שהם <i>הכרחיים לצורך קיום חיותם</i>\" (ב\"י שם; שו\"ע אדה\"ז שם), ובהמאמר מבואר דב\"חסרונן\" לשון רבים נכלל גם החסרון ד\"אשר יחסר <i>לו</i>\" לפי שהי' דרכו בכך."],["324","91","דש\"פ חו\"ב י\"ב תמוז שנה זו (תשכ\"ט (לעיל ע' כט ואילך))."],["325","92","ע' נח. וראה שם ע' נג."],["326","93","<i>וע\"ד</i> המבואר לעיל ס\"ג בענין השגה, שהיא נותנת מקום להשגה הפכית."],["327","94","רמב\"ם הל' יסוה\"ת בתחלתן."],["328","95","<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא רפמ\"ב</a>."],["329","96","דב\"ר (פי\"א, ד) עה\"פ (ברכה לג, א) וזאת הברכה גו' איש האלקים. וראה גם מדרש תהלים כאן בשינוי לשון."],["330","97","לקו\"ד קי, ב ואילך."],["331","98","לקו\"ד שם קז, ב. ובכ\"מ – ראה ספר הערכים-חב\"ד ערך אדם ס\"ט. <i>וש\"נ</i>."],["332","99","ראה ב\"ר פל\"ג, ד (בסופה). ועוד. פרש\"י עה\"פ נח ח, א. וראה בהנסמן ב\"שערי זהר\" לברכות ס, ב."],["333","100","כמ\"ש (יחזקאל יז, יג) ואת אילי הארץ לקח (סה\"מ עטר\"ת ע' שס. תרפ\"ח ע' סט. קונטרסים ח\"א צז, א. ועוד). ובסה\"מ תרפ\"ח שם מובא (בהמשך לפסוק זה) גם מ\"ש בשו\"ע אדה\"ז (או\"ח ס\"ה ס\"ג): וכשמזכיר שם אלקים יכוין שהוא תקיף ואמיץ."],["334","101","ס\"ע נח ואילך. וראה שם ע' סב."]]],[1500390007,"<h3>בס\"ד. ש\"פ חוקת-בלק, י\"ב תמוז<sup data-n=\"335\">*</sup> ה'תשל\"ו</h3>\n<b>נתת</b> ליראיך נס להתנוסס מפני קשט סלה<sup data-n=\"336\">1</sup>, ומביא כ\"ק מו\"ח אדמו\"ר בעל הגאולה והשמחה במאמרו (ד\"ה זה<sup data-n=\"337\">2</sup>) פי' הת\"י יהבתא לדחליך נסא לאתנסאה בי' (מלשון נסיון) מן בגלל קושטי' דאברהם לעלמין. והנה פסוק זה אמרו דוד נעים זמירות ישראל<sup data-n=\"338\">3</sup> בשם כאו\"א מישראל<sup data-n=\"339\">4</sup>. שמזה מובן, דכל הפרטים שבכתוב זה ישנם ג\"כ אצל כאו\"א מישראל<sup data-n=\"340\">5</sup>. וכמובן ג\"כ מפי' התרגום דמפני קשט סלה היינו קושטי' דאברהם, וידוע<sup data-n=\"341\">6</sup> דבחי' האבות ישנה אצל כאו\"א, דאין קורין אבות אלא לשלשה<sup data-n=\"342\">7</sup>, ראש צורים גו'<sup data-n=\"343\">8</sup>, ובפרט אברהם שהוא ראש לאבות<sup data-n=\"344\">9</sup>. ומזה מובן דגם מש\"נ נתת ליראיך גו' (שהטעם ע\"ז הוא מפני קשט סלה) קאי ג\"כ על כאו\"א מישראל, וכמ\"ש<sup data-n=\"345\">10</sup> ועתה ישראל מה ה' אלקיך שואל מעמך כי אם ליראה גו', דלגבי בחי' משה שבכאו\"א יראה היא מילתא<sup data-n=\"346\">11</sup> זוטרתא<sup data-n=\"347\">12</sup>. וי\"ל שלכן כאו\"א מישראל, גם אשר בשם ישראל יכונה<sup data-n=\"348\">13</sup>, נקרא ליראיך. וז\"ש נתת ליראיך נס להתנוסס מפני קשט סלה, שהקב\"ה נותן לכאו\"א מישראל נס להתנוסס (מלשון נסיון), כי בכאו\"א ישנו הקושטי' דאברהם.\nב) <b>וממשיך</b> בהמאמר, וידוע דאברהם אבינו ע\"ה פתח הצנור<sup data-n=\"349\">14</sup> דמסירת נפש. ויש לומר שבזה מבאר טעם הדבר שעבודת הנסיונות קשורה עם קושטי' דאברהם דוקא. דלכאורה הרי עיקר עבודת אברהם לא היתה בענין דליראיך, עבודתהיראה, כ\"א בהאהבה וכמש\"נ<sup data-n=\"350\">15</sup> אברהם אוהבי, ע\"ז מבאר שאאע\"ה פתח הצנור דמס\"נ, שעבודת הנסיונות היא ע\"י מס\"נ דוקא, דמס\"נ היא שלימות ענין היראה והביטול<sup data-n=\"351\">16</sup>. וז\"ש<sup data-n=\"352\">17</sup> לאחרי נסיון העקידה עתה ידעתי כי ירא אלקים אתה. והנה זה שעבודת הנסיונות היא ע\"י מס\"נ דוקא, הכוונה בזה היא לדרגא נעלית שבה. דהנה כללות העבודה בתומ\"צ צ\"ל מיוסדת על עבודה דמס\"נ, וכדאיתא בתניא<sup data-n=\"353\">18</sup> הטעם למה צוה משה רבינו ע\"ה לדור שנכנסו לארץ לקרות ק\"ש כו' משום שקיום התומ\"צ תלוי בזה שיזכור ענין המס\"נ כו', וכן כללות עסק התומ\"צ והתפלה אצל הנשמה הוא ענין של מס\"נ כו' כיון שאינה מהרהרת בצרכי הגוף כו'<sup data-n=\"354\">19</sup>, אבל מ\"מ עבודתו בגלוי אינה ענין של מס\"נ, כ\"א עבודה דתומ\"צ, שמקיים המ\"ע בכל פרטיהן ונזהר במל\"ת בכל פרטיהן, שמזה מובן שאין זה עבודת המס\"נ כמו שהיא לעצמה, אלא כמו שהיא קשורה עם עבודה דתומ\"צ ומלובשת בה, שהיא עבודה ע\"פ טו\"ד. וי\"ל שבכחות הנפש הו\"ע העבודה מצד מקיף הקרוב השייך לפנימי ומתלבש בו, ע\"ד כח הרצון שמתלבש בחכמה, ועל ידה בכללות כח השכל ומדות, כחות הפנימיים של האדם, משא\"כ עבודת הנסיונות היא ע\"י עבודת המס\"נ עצמה, ומה שנשתלשל מזה עניני עבודה בעשר כחות נפשו הוא ע\"ד טפל ותוצאה מעיקר ענינו, שהו\"ע המס\"נ. וי\"ל שבכחות הנפש היא בחי' מקיף הרחוק, בחי' יחידה שבנפש<sup data-n=\"355\">20</sup>. ועפ\"ז יש לקשר ב' הפירושים שבפסוק נתת גו' נס להתנוסס, א' ענין הנסיונות כפי' הת\"י (כנ\"ל), ב' ענין הנסים<sup data-n=\"356\">21</sup>, ונס להתנוסס הוא (ע\"ד לשון חז\"ל<sup data-n=\"357\">22</sup>) נס בתוך נס, כי עבודת הנסיונות היא מצד בחי' נס בתוך נס שבנפש, בחי' יחידה.\nג) <b>וזהו</b> ג\"כ מה שממשיך בהמאמר דתחלת עבודת אברהם היתה הכרת אלקות מעניני עולם, וכדאיתא במדרש<sup data-n=\"358\">23</sup> משל לאחד שהי' עובר ממקום למקום וראה בירה אחת דולקת אמר תאמר שהבירה זו בלא מנהיג, הציץ עליו בעל הבירה כו', כך לפי שהי' אבינו אברהם אומר תאמר שהעולם הזה בלא מנהיג, הציץ עליו הקב\"ה ואמר לו אני הוא בעל העולם, דיש לפרש דהענין דאני הוא בעל העולם שנתגלה לאברהם הו\"ע הניצוץ בורא המתלבש בניצוץ נברא, שהניצוץ נברא שבומתלבש הניצוץ בורא הו\"ע יחידה שבנפש כמבואר בע\"ח<sup data-n=\"359\">24</sup>. והכרת אלקות זו פרסם ג\"כ בכל העולם, וכמ\"ש<sup data-n=\"360\">25</sup> ויקרא שם בשם ה' א-ל עולם א\"ת ויקרא אלא ויקריא<sup data-n=\"361\">26</sup>, שהקריא זה בכל העולם דיש בעה\"ב לבירה זו, וכמבואר בכ\"מ<sup data-n=\"362\">27</sup> הדיוק בלשון א-ל עולם, ולא א-ל העולם, דהיינו לא שאלקות הו\"ע בפ\"ע ועולם ענין בפ\"ע אלא שאלקות מושל ושולט על העולם, כ\"א שעולם ואלקות כולא חד, דאין עוד מלבדו<sup data-n=\"363\">28</sup>. וזהו הקשר בין הכרת אלקות דאברהם לעבודת הנסיונות שלו, כי עבודת הנסיונות היא ע\"י מס\"נ שמצד יחידה שבנפש. שזהו ג\"כ מה שמס\"נ דאברהם לא היתה כמס\"נ דר\"ע שאמר<sup data-n=\"364\">29</sup> מתי יבוא לידי ואקיימנו, כ\"א שכל ענינו הי' לפרסם אלקותו ית' בעולם<sup data-n=\"365\">30</sup>, אלא שאם צריך מס\"נ ע\"ז הי' מוכן לזה. והיינו כי אאע\"ה לא הי' מציאות לעצמו, ואנכי עפר ואפר<sup data-n=\"366\">31</sup>, שזהו\"ע המס\"נ שמצד בחי' יחידה. ודוקא מצד ביטול זה בא לידי תוקף הכי גדול, ועד שאף שאחד הי' אברהם<sup data-n=\"367\">32</sup>, וכל העולם כולו מעבר אחד והוא מעבר אחד<sup data-n=\"368\">33</sup>, מ\"מ וירש את הארץ<sup data-n=\"367\">32</sup>, שפרסם אלקותו ית' בכל העולם, שעי\"ז בונים את העולם שיהי' דירה לו ית' בתחתונים<sup data-n=\"369\">34</sup>.\nד) <b>והנה</b> טעם הדבר שעבודת הנסיונות היא ע\"י מס\"נ דוקא, מבאר בהמאמר<sup data-n=\"370\">35</sup> כי בנסיון הניצוץ אלקי מוסתר ונעלם ביותר. ומבאר בהקדם ההפרש שבין עבודת הבירורים לעבודת הנסיונות (כי אף שגם הנסיונות הם מעבודת הבירורים שבשבילה ירדה הנשמה למטה<sup data-n=\"371\">36</sup>, מ\"מ יש הפרש ביניהם), דבעבודת הבירורים ההתעסקות היא עם הדבר המתברר, וכמו מאכל גשמי שהניצוץ הוא בהמאכל המתברר והבירור הוא ע\"י ההתעסקות בו (וכן הוא גם בכללות צרכי האדם שנקראיםבשם אכילה<sup data-n=\"372\">37</sup>), משא\"כ בנסיון שאופן בירורו הוא לא ע\"י ההתעסקות בהדבר כ\"א ע\"י התעסקות האדם עם עצמו. והענין הוא, דהנה עבודת הבירורים היא בדרך מלחמה, דנהמא אפום חרבא ליכול<sup data-n=\"373\">38</sup>. שזהו ע\"י הקדמת התפלה וכמ\"ש<sup data-n=\"374\">39</sup> בחרבי ובקשתי ות\"א בצלותי ובבעותי, וכמבואר בכ\"מ<sup data-n=\"375\">40</sup> בענין ברכות ק\"ש (שהן ההקדמה לק\"ש, ואהבת גו', כללות ענין התפלה<sup data-n=\"376\">41</sup>) שהיא התבוננות בשרש נה\"ב והבירורים כו', שעי\"ז הוא מבררם כו'. ולכן היא עבודה בדרך מלחמה והתלבשות בהמתברר שמתבונן בשרשו ועי\"ז מברר אותו. ועד\"ז הוא בכללות העבודה דתומ\"צ, שהיא ע\"י מלחמה עם היצה\"ר, שצריך לטעון (אויס'טענה'ן זיך) וללחום עמו בכל מיני תכסיסי מלחמה כו' ובהתבוננות בכמה דרכים איך לנצחו. משא\"כ בענין הנסיונות הרי העבודה בהם אינה ע\"י שמעלה אותם, כ\"א בדרך דחי' וביטול. והוא ע\"ד ההפרש שבמצוות גופא בין מ\"ע ומל\"ת. דמ\"ע ענינם עשי' ופעולה, והיינו שמתעסק עם הדבר שבו מקיים המצוה (מיטן ענין און אין דעם ענין), אבל מל\"ת ענינם סור מרע<sup data-n=\"377\">42</sup>, שסר מן הרע ודוחה אותו.\nה) <b>והנה</b> עם היות שאופן העבודה דמל\"ת הוא ע\"י דחי' וביטול, מ\"מ, בזה משתווה להעבודה דמ\"ע, דשניהם הם בענין של מציאות שחל עליו הגדר דעשי' והעדר העשי', אלא שבמ\"ע הוא מצווה על העשי' ובמל\"ת על העדר העשי'. ולכן גם ההתעסקות במל\"ת היא לא רק בהאדם עצמו, כי אם גם בהמתברר. דעם היות שעיקר עבודת מל\"ת היא בזה שמושל ושולט על יצרו שלא יאכל וכיו\"ב, שזהו בדרך דחי' וביטול, מ\"מ, מכיון שעבודתו היא עם דבר שיש לו מציאות בגשם וחומר, הרי יש לו שייכות, בדרך שלילה עכ\"פ, להדבר המתברר. משא\"כ עבודת הנסיונות שהיא בענין (בלשון המאמר<sup data-n=\"378\">43</sup>) שאינו דבר מצד עצמו רק שהועמד דבר להעלים ולמנוע, ולכן ההתעסקות של האדם היא עם עצמו, לעורר את הכח העצמי שבו שהוא התוקף לעמוד נגד הנסיון, ולא להתפעל ממנו כלל, ועד שאינו נכנס בטענות ומענות ורק עומד בתוקף שאחרת אי אפשר ומבטל הנסיון מכל וכל. וע\"י תוקף זה מתבטל הוא באמת כי מתגלה אמיתית הדבר שהוא ענין שאין לו מציאות, וכל מציאותו היא רק כדי שיתגלה אצל האדם עצם נפשו, שהוא הרצון הפנימי שלו שלמעלה מהתלבשות בכלים. וע\"ד הנסיון דאברהם בנסיון העקידה (שעיקר פתיחת הצנור דמס\"נ ע\"י אברהם הי' בהנסיון דעקידה<sup data-n=\"379\">44</sup>), שעיקר הנסיון הי' בענין הזריזות, וכמבואר באגה\"ק<sup data-n=\"380\">45</sup>דזריזותי' דאאע\"ה היא העומדת לעד לנו כו' עד עולם. וכמארז\"ל<sup data-n=\"381\">46</sup> דנעשה לפניהם נהר גדול כו' ומ\"מ לא נתפעל אברהם והלך למלאות שליחותו של הקב\"ה, וירד לתוך המים כו', ועי\"ז נתבטל מציאות הנהר, כי ע\"י התוקף שלו נתגלה האמת שכל מציאותו של הנהר היתה רק כדי לנסותו כו'. וכן לאח\"ז (בנסיון העקידה עצמה) דא\"ל הקב\"ה לא אמרתי לך כו' אסקתי' אחתי'<sup data-n=\"382\">47</sup>. ועד\"ז היתה גם ההנהגה של כ\"ק מו\"ח אדמו\"ר בעל השמחה והגאולה בישבו במאסר (כמסופר ברשימותיו<sup data-n=\"383\">48</sup> ושיחותיו<sup data-n=\"384\">49</sup>), שהחליט בתחלתו להיות עז ותקיף בלי חת ולא להתחשב כלל עם המצב כו', וכך היתה הנהגתו כל ימי שבתו במאסר, ועי\"ז, הנה לא זו בלבד שהנהגה זו נתנה לו התוקף לעמוד נגד כל הקשיים וההעלמות וההסתרים של המאסר (שההעלם והסתר הי' לא רק על ענינים גשמיים שלו, כ\"א גם על עניניו הרוחניים, וכמודגש שבעת ישיבתו במאסר לא היתה האפשריות להתעסק בהפצת היהדות והמעינות), הנה עוד זאת, שעי\"ז נתבטל ההעלם והסתר. דעם היות שלכתחלה הי' נראה שהם מציאות חזקה וגדולה (כמסופר ברשימותיו), הנה ע\"י התוקף שלו נתבטלו ממציאותם, ועד שנשתחרר באופן גלוי לעין כל. ועי\"ז נעשה גם יתרון בבעל השמחה והגאולה עצמו, וע\"ד שהי' בהענין די\"ט כסליו, דע\"י המאסר והגאולה נעשה עילוי בנוגע לחסידות כמבואר בכ\"מ<sup data-n=\"385\">50</sup>, עד\"ז גם כאן<sup data-n=\"386\">51</sup> שנעשה עילוי בבעל השמחה והגאולה כנ\"ל, שנתרבה העבודה דהפצת התורה ביתר שאת מכמו שהיתה לפנ\"ז, ועד שהתחיל עי\"ז בפועל ענין ההפצה בכל העולם כולו, ובאופן דמעתה ועד עולם<sup data-n=\"387\">52</sup>. וע\"ד מה דאיתא בגמרא<sup data-n=\"388\">53</sup> דכאשר ישנם ג' דורות עוסקים בתורה שוב אין התורה פוסקת מזרעו כי התורה מחזרת על אכסניא שלה, עד\"ז בענינינו, שכבר ישנם (כתוצאה מהגאולה די\"ב-י\"ג תמוז) ג' דורות של לומדי תורה ומקיימי מצוותי', ועוד יותר מחבבי&lt;13&gt; תורה ומצוותי' (שעי\"ז קיום המצוות שלהם הוא בהידור<sup data-n=\"389\">54</sup>). שכל זה הוא ע\"י שעמד בתוקף הכי גדול למעלה מכל חשבונות, שעי\"ז ביטל הנסיון באופן הכי נעלה. ומכיון דבתר רישא גופא אזיל<sup data-n=\"390\">55</sup>, הרי כן צריך להיות גם בעבודת כאו\"א, שנלך בדרך ישרה אשר הורנו מדרכיו ונלכה באורחותיו<sup data-n=\"391\">56</sup>, לעמוד בתוקף שלא להתפעל משום מניעות ועיכובים בעבודת ה', כי מאחר שהולך למלאות שליחותו בעלמא דין, הרי אין להנסיון מציאות, ורק מנסה ה' אלקיכם אתכם לדעת הישכם אוהבים את ה' אלקיכם<sup data-n=\"392\">57</sup>, וע\"י התוקף ומס\"נ מתבטל הנסיון.ו) <b>ולהבין</b> כ\"ז בפרטיות יותר, יש להקדים תחלה כללות ענין ירידת הנשמה למטה שהיא ירידה גדולה מאיגרא רמה לבירא עמיקתא<sup data-n=\"393\">58</sup>. דהנה הנשמה קודם ירידתה למטה טהורה היא<sup data-n=\"394\">59</sup>, ויש בזה כמה פירושים<sup data-n=\"395\">60</sup>, א' דקאי על עולם האצילות, ב' טהירו תתאה, ג' טהירו עילאה. וירידתה היא למטה ביותר, לא רק לעולמות בי\"ע, עלמין דפרודא בכלל, כ\"א לעוה\"ז התחתון שאין תחתון למטה ממנו<sup data-n=\"396\">61</sup>, שרובו ככולו רע רק מעט טוב מעורב בתוכה<sup data-n=\"397\">62</sup>, עד שמעשה עוה\"ז קשים כו' (כמבואר בתניא<sup data-n=\"398\">63</sup> בשם הע\"ח<sup data-n=\"399\">64</sup>), ועוד זאת, דהעבודה בעוה\"ז גופא היא בהמטה מטה ביותר, במקום דלמצרים ירדתם ובאופן דיצה\"ר יש ביניכם<sup data-n=\"400\">65</sup>, שצריך ללחום עם היצה\"ר והיום אומר לו עשה כך ולמחר כו' עבוד ע\"ז<sup data-n=\"401\">66</sup>, שהוא ההיפך של אנכי ולא יהי' לך (השרש לרמ\"ח מ\"ע ושס\"ה ל\"ת, כמבואר בתניא<sup data-n=\"402\">67</sup>), אלא שירידה זו צורך עלי'<sup data-n=\"403\">68</sup>. כי אף שהנשמה לא ירדה לתקן עצמה כו' אלא לתקן גופו ונפשו הבהמית וחלקו בעולם (כמבואר בע\"ח<sup data-n=\"404\">69</sup> הובא בתניא<sup data-n=\"405\">70</sup>), אבל מ\"מ, ע\"י ירידת הנשמה למטה הרי היא מתעלית לבחי' נעלית יותר מכמו שהיתה קודם ירידתה<sup data-n=\"406\">71</sup>, שלמעלה גם מטה\"ע. ועוד יותר, לבחי' שאין לה ערך ושייכות לענין של השתלשלות ודרגא ומעלה, עד שאין שייך לומר אפילו זה שיש בה מעלה לגבי סדר השתלשלות, כ\"א בלשון הידוע<sup data-n=\"407\">72</sup> לאשתאבא בגופא דמלכא, בעצמותו ומהותו ית'<sup data-n=\"408\">73</sup>. ובלשון הזהר במ\"א<sup data-n=\"409\">74</sup>, בבחי' זו דלא משתכחי במלכא אלא ישראל בלחודייהו (שלמעלה גם מתומ\"צ). והעלי' היא ע\"י העבודה בתומ\"צ, דאני נבראתי לשמש את קוני<sup data-n=\"410\">75</sup>, וכמ\"ש<sup data-n=\"411\">76</sup> ויניחהו גו' לעבדה ולשמרה, לעבדה אלו רמ\"ח מ\"ע ולשמרה אלו שס\"ה מל\"ת<sup data-n=\"412\">77</sup> (דכל מקום שנאמר השמר כו'אינו אלא בל\"ת<sup data-n=\"413\">78</sup>), וצ\"ל לזה הקדמת התורה דגדול לימוד שמביא לידי מעשה<sup data-n=\"414\">79</sup>. וגם ניצוח היצה\"ר הוא ע\"י התורה כמארז\"ל<sup data-n=\"415\">80</sup> בראתי יצה\"ר ובראתי לו תורה תבלין, ואם פגע בך מנוול זה משכהו לבהמ\"ד כו'. וז\"ש&lt;42&gt; סור מרע ועשה טוב בקש שלום ורדפהו, דקאי על מ\"ע ומל\"ת ותורה, כמבואר בלקו\"ת פרשתנו (בלק)<sup data-n=\"416\">81</sup>.\nז) <b>אמנם</b> צלה\"ב טעם הדבר, שדוקא ע\"י עבודת הנשמה למטה הרי היא מתעלית לבחי' נעלית יותר מכמו שהיתה לפני ירידתה, ועד לעלי' כזו שהיא שלא בערך מדריגתה הקודמת. והענין הוא<sup data-n=\"417\">82</sup>, כי הניצוצות שבענינים הגשמיים שרשם בעולם התוהו שלמעלה מעולם התיקון. וכמש\"נ<sup data-n=\"418\">83</sup> כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי ה' יחי' האדם. ומפרש האריז\"ל<sup data-n=\"419\">84</sup> דמוצא פי ה' שבלחם הוא הניצוץ אלקי שבו. ואף שגם בהאדם ישנו מוצא פי ה' המחי' אותו, מ\"מ צריך להמוצא פי ה' שבלחם דוקא, כי כל הגבוה יותר יורד למטה יותר<sup data-n=\"420\">85</sup>. וכמשל האבן הנמצאת בראש החומה, הנה כאשר היא נופלת למטה ה\"ה נופלת בריחוק יותר מן החומה מהאבן הנופלת מאמצע החומה כו'<sup data-n=\"421\">86</sup>. ולכן, מכיון שהמוצא פי ה' שבלחם נפל למטה יותר מהמוצא פי ה' שבאדם, שהרי הלחם הוא מצומח, ובפרט שבעת האכילה כבר אינו צומח כ\"א דומם (ועוד זאת, שאכילת לחם היא עם מלח<sup data-n=\"422\">87</sup> שהוא דומם), והאדם הוא מדבר, הרי זה גופא הוכחה שהניצוצות הנמצאים בהלחם שרשם הוא למעלה מהמוצא פי ה' שבאדם, גם מאדם העליון, בחי' תיקון. ולכן דוקא על ידם יחי' האדם, האדם שלמטה, ו(עי\"ז) האדם העליון כביכול<sup data-n=\"423\">88</sup>. ולהעיר מעוד ענין בזה, המבואר במ\"א<sup data-n=\"424\">89</sup> בארוכה ההפרש שבין עולם התיקון לעולם התוהו, דשניהם נתהוו ברצון העליון, אלא שבעולם התיקון הוא באופן דדין הניין לי'<sup data-n=\"425\">90</sup>, ובעולם התוהו הוא באופן דדין לא הניין לי'<sup data-n=\"425\">90</sup>. והיינו, דבעולם התוהו ישנו הרצון העליון, אלא שהוא בהעלם והסתר, ובגילוי הו\"ע של היפך הרצון דדין לא הניין לי'. ולכן משתלשל מזה למטה, שהענינים שנתהוו מעולם התוהו, עם היות שבגילוי הם ענינים של היפך הקדושה דדין לא הניין לי', מ\"מ, גם בהם ישנם ניצוצות דקדושה, ואדרבה, דוקא בהם ישנו תוקף, של אורות דתוהו. וזהו מה שע\"י ירידת הנשמה למטה ה\"המתעלית לבחי' נעלית יותר מכמו שהיתה קודם ירידתה, שזהו מצד הבירורים של הניצוצות דעולם התוהו, שעי\"ז יורש האורות דתוהו, שזהו\"ע מורשה קהלת יעקב<sup data-n=\"426\">91</sup>.\nח) <b>והנה</b><b>,</b> עפ\"י הכלל הנ\"ל דכל הגבוה יותר נופל למטה יותר מוכרח לומר, שגם בניצוצות דתוהו גופא, כל מה שנפל למטה יותר שרשו ממקום גבוה יותר. שמזה מובן שיש מעלה בהבירורים שע\"י מל\"ת על הבירורים דמ\"ע, דעם היות שגם הניצוצות שבדברים גשמיים שבהם הוא קיום מ\"ע שרשם מעולם התוהו, מ\"מ אין הנפילה בהם כ\"כ, שהרי הן עניני היתר שמק\"נ. משא\"כ במל\"ת, שהן בענינים שהן אסורים וקשורים בידי החיצונים<sup data-n=\"427\">92</sup>, הרי זה גופא הוכחה ששרש הניצוצות המלובשים בהם הוא למעלה יותר. שלכן ע\"י העבודה דמל\"ת, גם בתחילת העבודה שאינו מהפך את הזדונות לזכיות ורק דוחה אותם, נמשך אור נעלה יותר מכמו בהעבודה דמ\"ע. וכמבואר בלקו\"ת<sup data-n=\"428\">93</sup>, דמ\"ע שייכות לו\"ה, בחי' והנגלות<sup data-n=\"429\">94</sup>, ול\"ת לי\"ה, בחי' הנסתרות לה\"א<sup data-n=\"429\">94</sup> (וגם – י\"ה הוא שם קדוש בפ\"ע<sup data-n=\"430\">95</sup>), שהחילוק ביניהם הוא חילוק שבאין ערוך. ובכללות הוא ההפרש בין אור פנימי לאור מקיף, דמ\"ע ממשיכות אור פנימי שהוא אור המתלבש בכלים, ומל\"ת ממשיכות אור מקיף שלא יכילנו הכלי. והנה מעלה זו במל\"ת לגבי מ\"ע הוא גם כאשר העבודה בעניני ל\"ת היא רק באופן של דחי'. ועאכו\"כ כאשר העבודה בהם היא באופן שמהפך הזדונות לזכיות, שאז ממשיך אור שלמעלה באין ערוך גם מהאור הנמשך ע\"י מל\"ת באופן של דחי'. וכמובן מזה שענין זה דזדונות נעשו לו כזכיות הוא רק ע\"י עבודת התשובה<sup data-n=\"431\">96</sup>, שהרי העבודה הרגילה (תמידים כסדרם) בענינים אסורים היא רק בדרך דחי'. וההפרש שבין ב' עבודות אלו הוא חילוק שבאין ערוך, כמובן מכ\"מ, שההפרש ביניהם הוא כערך הגבול לגבי הבל\"ג. וכמו שהוא בענין הזמן, דעבודת התשובה היא בשעתא חדא וברגעא חדא<sup data-n=\"432\">97</sup>, למעלה ממדידה דזמן, משא\"כ עבודה הרגילה היא מדודה בהמשך ושטח של זמן<sup data-n=\"433\">98</sup> (ובדרך ממילא גם במקום<sup data-n=\"434\">99</sup>).\nט) <b>והנה</b> אף שהנפילה בהניצוצות שבמל\"ת היא בענינים שאסורים וקשורים בידי החיצונים, מ\"מ יש להם מציאות, שלכן שייך בהם ענין של עבודה, עכ\"פ ע\"י שלילה ודחי', וכמשנת\"ל. ולכן גם האור הנמשך ע\"י מל\"ת, אף שהוא אור מקיף, בחי' י\"ה דשם הוי', מ\"מ הרי גם הי\"ה של שם הוי' הוא אותיות של שם הוי', שאותיותענינם גילויים<sup data-n=\"435\">100</sup> (אלא שבאותיות גופא יש הפרש בין ו\"ה דשם הוי' שהוא דוגמת אור פנימי, לי\"ה דשם הוי' שהוא דוגמת אור מקיף). משא\"כ נסיונות, הם בדברים שאין להם מציאות. דהנה הגם שהענינים שבהם הוא קיום מל\"ת הם ענינים של קליפה, מ\"מ, אין הכרח לומר שזהו כל מציאותם לנגד לקדושה. והא ראי' שישנם כמה ענינים שאסורים רק באכילה ומותרים בהנאה<sup data-n=\"436\">101</sup> (דעי\"ז אפשר להעלותם לקדושה<sup data-n=\"437\">102</sup>), ועד כאלו שמוכרחים בהנאתם<sup data-n=\"438\">103</sup>. ועד\"ז ישנם כו\"כ דרגות וחילוקים בענינים אסורים שאינם מנגדים לרצון ה' בכל עניניהם ובכל פרטיהם. ויתירה מזו, שלפעמים גם הדבר איסור עצמו נעשה היתר, וע\"ד משארז\"ל<sup data-n=\"439\">104</sup> דבעת כיבוש הארץ (ועד\"ז במלחמה דוגמתה<sup data-n=\"440\">105</sup>) הותרו להם גם קדלי דחזירי<sup data-n=\"441\">106</sup>, שזה נעשה דם ובשר כבשרו, ובכח זה הי' כיבוש הארץ (שלכן הותר להם, כמבואר בספרי הפשטנים), היינו שמסייע לקדושה. משא\"כ בנסיונות, שמציאותם היא שהועמד דבר להעלים ולמנוע עבודת ה', ולולא זה אין לו מציאות, אפילו לא באופן של דמיון. ומכיון שהנפילה היא למטה מטה ביותר, בענינים שכל מציאותם היא רק לנגד לרצון ה', הרי מובן, ששרשם הוא ממקום נעלה יותר. ולכן ע\"י עבודת הנסיונות, שהירידה היא למטה מטה, עי\"ז מתעלה האדם בעילוי למעלה מעלה יותר.\nי) <b>והנה</b> כל עניני קדושה נמשכים על ידי עבודה דוקא (ולא באופן של נהמא דכסופא<sup data-n=\"442\">107</sup>), שמזה מובן, דהעילוי שבעבודת הנסיונות על העבודה דמ\"ע ומל\"ת הוא לא רק מצד שרש הניצוצות שבהם, כ\"א גם מצד ההשתדלות ועבודת האדם בעבודה זו. דכשם שאינה דומה העבודה וההשתדלות בקיום מ\"ע להעבודה שבמל\"ת, שהרי כדי להזהר שלא לעבור על מל\"ת צריך לעשות סייגים וכו'<sup data-n=\"443\">108</sup>, וקדש עצמך במותר לך<sup data-n=\"444\">109</sup>, עד\"ז אינה דומה ההשתדלות בקיום מל\"ת לגבי ההתגברות ותוקף ואומץ שצ\"ל בעבודת הנסיונות. וי\"ל דזהו משארז\"ל<sup data-n=\"445\">110</sup> לגבי נסיון העקידה, שזהו נסיון הראשון שנזכר בפירוש בכתוב, דהאלקים נסה את אברהם<sup data-n=\"446\">111</sup>, שהקב\"האמר לאברהם ניסיתיך בכמה נסיונות ועמדת בכולן עכשיו עמוד לי בנסיון זה שלא יאמרו אין ממש בראשונים. והיינו, כי בט' נסיונות הראשונים לא הי' בזה עדיין שלימות העבודה וההשתדלות דנסיונות, שלכן לא נזכרו בפירוש בתושב\"כ, כי בכתב ובגילוי עדיין אין זה שלימות ענין הנסיון. ועי\"ז שעמד בנסיון זה ה\"ז משלים ומאמת כל עבודת אברהם (גם עבודתו שלפנ\"ז). שזהו מפני קשט סלה ופי' בת\"י בגלל קושטי' דאברהם לעלמין, שהוא האמת שנתגלה ע\"י עבודת אברהם. וזהו שמבאר בהמאמר, שבכדי לעמוד בנסיון אינו מספיק העבודה שע\"פ טו\"ד, ואפילו לא עבודה ע\"פ טו\"ד המיוסדת על מס\"נ, כ\"א צ\"ל עבודה שכל ענינה הוא מס\"נ. והענין הוא, דמכיון שההתעסקות בנסיונות הוא בענין שאין לו מציאות, ומציאותו היא רק שהועמד דבר להעלים ולמנוע כנ\"ל, לכן גם אופן הבירור שלו הוא לא ע\"י עבודה שנותנת מציאות ותפיסת מקום להמתברר, כ\"א בעבודה שמבטלו מכל וכל<sup data-n=\"447\">112</sup>. דהנה בעבודה שע\"פ טו\"ד, אפילו טו\"ד דקדושה של נפה\"א, מכיון שקשורה בשקו\"ט והסברה בשכל, הרי זה גופא מורה שישנה מציאות המנגדת שלוחם עמה, ולכן לא תספיק עבודה זו בשביל הנסיונות שעל ידה הוא בירור ענינים שאין להם מציאות. כ\"א הוא ע\"י מס\"נ בתוקף גדול, שאינו נכנס לשום שקו\"ט וחשבון, ומבטל הנסיון מכל וכל כאילו שאין שום מציאות שצריך ללחום עמה כו'. ולכן עבודה זו היא (במקיפי הנפש גופא) מבחי' היחידה שבנפש כנ\"ל, כי דוקא מצד בחינה זו אין מקום לשום מציאות כ\"א של קדושה, ושאר הענינים הם דמיון בעלמא, וגם המציאות של הדמיון הוא רק בשביל הקדושה, כדי שע\"י יתעלה האדם בעילוי גדול יותר, שלמעלה גם מן העלי' שנעשית ע\"י העבודה דמ\"ע ומל\"ת, עד שהוא גם למעלה מן העבודה (בעניני ל\"ת) דזדונות נעשו לו כזכיות, שהיא עבודת התשובה, ותשובה מאה\"ר בכלל<sup data-n=\"448\">113</sup>.\nיא) <b>והנה</b> גם בנסיונות גופא ישנם כמה דרגות. דכמו שבענין הנסים יש כמה דרגות זו למעלה מזו (נס, נס בתוך נס וכו'), עד\"ז הוא בנסיונות שיש בהם כמה דרגות זו למטה מזו, וכמו שמבאר כ\"ק אדמו\"ר הצ\"צ בד\"ה אחרי ה\"א גו' (שנדפס בסוף סהמ\"צ שלו<sup data-n=\"449\">114</sup>) כמה דרגות בזה. ובכללות הוא, כמו שמביא כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע במאמרו ד\"ה נתת ליראיך נס להתנוסס<sup data-n=\"450\">115</sup> את מאמר המדרש<sup data-n=\"451\">116</sup> בא וראה מה בין ראשונים לאחרונים, שהראשונים היו מתנסין ע\"י הקב\"ה שנאמר והאלקים נסה את אברהם כו' אבל אחרונים נתנסו ע\"י אוה\"ע כו'. שבהנסיונות שע\"י אוה\"ע הרי ההעלם וההסתר הוא גדול יותר מנסיונות סתם. שלכן כדי לעמוד נגד נסיונות אלו הוא ע\"י דרגא נעלית יותר בביטול ומס\"נ גופא. וי\"ל שזהו מה שעיקר ענין הנסיונות הוא בדורות האחרונים דוקא<sup data-n=\"452\">117</sup>, ובעיקר בדרא דעקבתא דמשיחא, שאזהחושך הוא כפול ומכופל, והעבודה היא במס\"נ. וכמבואר במאמרי רבותינו נשיאינו<sup data-n=\"453\">118</sup>, ובמיוחד במאמרי בעל הגאולה והשמחה<sup data-n=\"454\">119</sup>, בפירוש הכתוב<sup data-n=\"455\">120</sup> והאיש משה עניו מאד מכל האדם אשר על פני האדמה, שבעיקר הי' זה מפני דרא דעקבתא דמשיחא, שגדלו ההעלמות וההסתרים, ובכ\"ז עומדים בתוקף עצום ולומדים תורה ומקיימים מצוות במס\"נ, הנה מפני זה (בלשון המאמר<sup data-n=\"456\">121</sup>) איז משה רבינו באַיי זיך אַראָפּ גיפאַלין. וע\"ד המצב כמו שהי' בזמן המאסר באותה המדינה כו'. ועד\"ז גם עתה, אף שלא ישנם בלבולים ומניעות כאלה ח\"ו על קיום התומ\"צ, בכ\"ז הרי ישנם הנסיונות מצד ההרחבה והעשירות, שלפעמים מצד ההרחבה כו' הנסיון גדול ביותר<sup data-n=\"457\">122</sup>. דהיצה\"ר הוא אומן במלאכתו, שהיום אומר לו עשה כך כו'&lt;66&gt;, ומבלבל את האדם מעבודת ה' שעכ\"פ לא תהי' בתכלית השלימות, כמאן דבעי למעבד<sup data-n=\"458\">123</sup>. ועי\"ז מוריד את האדם מדרגא לדרגא כו', בתחלה בענינים של התגברות<sup data-n=\"459\">124</sup> דנפה\"ב שמנוגה ואח\"כ בעניני שוגג ואח\"כ כו'. וכדי לעמוד נגד כל נסיונות אלו צריך האדם לעבוד עבודתו בתוקף גדול, ובלשון התניא<sup data-n=\"460\">125</sup> ירעים עלי' בקול רעש כו' כמארז\"ל<sup data-n=\"461\">126</sup> לעולם ירגיז אדם יצ\"ט על יצה\"ר כו', שעי\"ז מבטל כל מציאותו<sup data-n=\"462\">127</sup>, ואדרבה, נעשה מסייע דגם אויביו ישלים אתו זה הנחש<sup data-n=\"463\">128</sup>. ומזה גופא שהעבודה דעקבתא דמשיחא היא קשה ביותר, הרי זה גופא הוכחה שישנם וניתנו הכחות ע\"ז<sup data-n=\"464\">129</sup>, דאיני מבקש לפי כחי אלא לפי כוחן<sup data-n=\"465\">130</sup> והיינו שניתן הכח לכאו\"א לעורר התוקף שמצד עצם הנפש, ובאופן כזה שמאיר גם בכחות הפנימיים שלו, עד למחדו\"מ שלו, שעי\"ז הם כולם מסורים לה' לתורתו ולמצוותיו.\nיב) <b>וזהו</b> מש\"נ<sup data-n=\"466\">131</sup> מפי עוללים ויונקים יסדת עוז גו' להשבית אויב ומתנקם. ומבאר כ\"ק מו\"ח אדמו\"ר בעל הגאולה והשמחה במאמרו ד\"ה וקבל היהודיםאת אשר החלו לעשות דשנת תרפ\"ז<sup data-n=\"467\">132</sup> (שמאמר זה אמרו עוד לפני מאסרו, במעמד ומצב של גזירות איומות בנוגע ללימוד התורה, ובפרט של עוללים ויונקים<sup data-n=\"468\">133</sup>), דע\"י עוז, אין עוז אלא תורה<sup data-n=\"469\">134</sup>, פועלים להשבית אויב ומתנקם. דהאויב הוא שונא הגלוי והנוקם הוא שונא נסתר ועולל עלילות כו' (שזוהי סכנה גדולה יותר מהאויב), וע\"י עוז דתורה נעשה להשבית אויב ומתנקם. וענין עוז דתורה הו\"ע התוקף, שאין מתחשבים עם המניעות וההעלמות וההסתרים כו', שע\"י תוקף זה מבטלים כל הגזירות, ומתגלה האמת שרובם אין להם מציאות והם רק ענין של הפחדה בעלמא.\n<b>וההתחלה</b> והיסוד של עוז דתורה הוא מפי עוללים ויונקים דוקא. דהנה כתיב<sup data-n=\"470\">135</sup> תורה צוה לנו משה מורשה קהלת יעקב, שהתורה היא ירושה לכאו\"א מישראל, וגם תינוק בן יומו יורש<sup data-n=\"471\">136</sup>, ויורש הכל כמש\"נ<sup data-n=\"472\">137</sup> תחת אבותיך יהיו בניך גו', שלכן גם עוללים ויונקים יש להם כל התורה בירושה. ואדרבה התורה אצלם היא היסוד כו' (יסדת עוז), וכמרז\"ל<sup data-n=\"473\">138</sup> אם אין גדיים אין תיישים. וכמו יסוד גשמי הנמצא בקרקע, שאין נוגע היופי שלו כו', כ\"א החוזק ותוקף שלו, כי צ\"ל חזק באופן כזה שיוכל להחזיק את כל הבנין, גם הגג שעל הבנין, כדי שהבנין יהי' איתן ועומד על עמדו, שכל הרוחות המנשבות בעולם לא יוכלו להזיזו ממקומו. וזהו מפי עוללים ויונקים יסדת עוז גו' להשבית אויב ומתנקם, שע\"י עוללים ויונקים דוקא, הבל התשב\"ר<sup data-n=\"474\">139</sup>, שהוא היסוד של עוז דתורה, נעשה להשבית אויב ומתנקם.\nיג) <b>ויש</b> לקשר ענין הנ\"ל (שעבודת הנסיונות היא ע\"י מס\"נ דוקא, בחי' נס בתוך נס שבנפש) עם מש\"נ בפרשת השבוע<sup data-n=\"475\">140</sup> אך בגורל יחלק את הארץ. דחלוקת הארץ, שזה קאי על חלוקת הארץ שלמטה, ועל חלוקת הארץ שלמעלה, או בלשון מאמרי רז\"ל (שהובאו במאמרי רבותינו נשיאינו<sup data-n=\"476\">141</sup>) עוה\"ב (דכל ישראל יש להם חלק לעוה\"ב<sup data-n=\"477\">142</sup> שנאמר<sup data-n=\"478\">143</sup> ועמך כולם גו' לעולם ירשו ארץ), היא ע\"י הגורל. כי בחי' הגורל שבנפש הו\"ע העבודה שלמעלה מטו\"ד<sup data-n=\"479\">144</sup>, ועוד יותר, למעלה גםמכח הרצון. וכמו גורל כפשוטו, שאינו תלוי כלל ברצונו של מטיל הגורל<sup data-n=\"480\">145</sup>. ולכן ע\"י בחי' הגורל דוקא היא חלוקת הארץ בכל הדרגות שבה כנ\"ל, הן עוה\"ב והן א\"י כפשוטה (ואין מקרא יוצא מידי פשוטו<sup data-n=\"481\">146</sup>). דהנה כתיב<sup data-n=\"482\">147</sup> ארץ אשר גו' עיני ה' אלקיך בה מרשית השנה ועד אחרית שנה, שיש בזה ב' הקצוות. מצד אחד הוא למעלה ממדידות והגבלות הזמן, שה\"ה מרשית השנה ועד אחרית שנה. ולאידך, נמשך הוא ב(מדוה\"ג ד)זמן, שלכן הוא רק עד אחרית שנה, ובשנה שלאח\"ז מתחדש אור זה באור חדש עליון יותר שלא הי' מאיר עדיין מימי עולם אור עליון כזה. ואור זה מתלבש בארץ שלמטה להחיות כו' כל משך שנה זו, וכמבואר בארוכה באגה\"ק<sup data-n=\"483\">148</sup>. ולכן חלוקת הארץ, שבה מאיר אור שלמעלה ממדוה\"ג, היא ע\"י בחי' הגורל דוקא.\nיד) <b>והנה</b> בחי' זו ישנה גם במצוות, והם המצוות שאינן תלויין ברצונו של האדם<sup data-n=\"484\">149</sup>. והענין הוא דהנה המצוות ענינם המשכת רצון העליון, וכלשון ברכת המצוות אשר קדשנו במצוותיו וציונו, שהמצוות הן ציווי הקב\"ה להאדם, שכן הוא רצון העליון, וע\"י קיום המצוה ה\"ז מקדש את האדם. ובזה גופא ישנם ב' אופנים, מ\"ע ומל\"ת. דבמ\"ע ההמשכה היא בגילוי משא\"כ במל\"ת, שלכן ברכת המצוות היא רק על מ\"ע, כי ברכה ענינה המשכה וגילוי<sup data-n=\"485\">150</sup>. אבל גם במל\"ת ישנה המשכת הרצון, אלא שאינה באופן של ברכה והמשכה בגילוי, וע\"ד המבואר בתו\"א<sup data-n=\"486\">151</sup> לענין הברכה על תפילין של ראש, דנחלקו הספרדים והאשכנזים אם יברכו עליהם ברכה מיוחדת, ומנהג ספרד שלא לברך דס\"ל שאי אפשר להמשיך המקיף ההוא ע\"י ברכה, כ\"א נמשך מאליו<sup data-n=\"487\">152</sup>. ועד\"ז מל\"ת שאין מברכין עליהם, כי ההמשכה היא מאלי' ומעצמה<sup data-n=\"488\">153</sup>. ולמעלה יותר הם המצוות שאינן תלויות כלל ברצון האדם, ע\"ד המצוה דנשיאות דכל הבורח מן הכבוד כו'<sup data-n=\"489\">154</sup>, ומצות שכחה. והטעם שאינן תלויין כלל ברצונו של האדם הוא לפי ששרשם הוא למעלה מבחי' רצון העליון. ובספירות הוא, שהמצוות בכלל הן מבחי' א\"א, רצון העליון, ומצוות שאינן תלויין ברצון האדם שרשם מבחי' עתיק, שנעתק ונבדל מכל סדר השתלשלות, גם מבחי' א\"א, וכמבואר בארוכה בלקו\"ת ס\"פ ברכה<sup data-n=\"490\">155</sup>. וזוהי בחי' הגורל שבמצוות, שעל ידה נמשך אור נעלה יותר מהאור הנמשך ע\"י מ\"ע ומל\"ת סתם.\n<b>ועד\"ז</b> ישנה בחי' הגורל בכאו\"א מישראל. דכמו שנת\"ל בענין הנסיונות, דנתת ליראיך נס להתנוסס גו' קאי על כאו\"א מישראל, הנה כמו\"כ הוא בבחי'הגורל, שישנה בכאו\"א מישראל. וכמש\"א<sup data-n=\"491\">156</sup> אשרנו מה טוב חלקנו ומה נעים גורלנו, היינו שאצל כאו\"א מישראל ישנם לא רק חלקנו כ\"א גם גורלנו, שעי\"ז הוא מיוחד עם הקב\"ה. ועוד זאת, שבחי' זו באה לידי ביטוי בענין של מעשה בפועל. וע\"ד המבואר באגה\"ק<sup data-n=\"492\">157</sup> בענין המצוה דהוה זהיר בה טפי<sup data-n=\"493\">158</sup>, שכאו\"א מישראל יש לו מצוה מיוחדה שצ\"ל זהיר בה טפי, והיא בחי' הגורל ממש. ועז\"נ<sup data-n=\"494\">159</sup> אתה תומיך גורלי, שבחי' הגורל היא מאתה, עצמותו ומהותו ית'. וכנ\"ל דבחי' הגורל (באדם התחתון) היא למעלה מכחות הפנימיים שלו, שהם בחי' השתלשלות שבאדם, ולמעלה גם מבחי' המקיפים שבערך הפנימיים, שהו\"ע הרצון, והוא ע\"ד בחי' עתיק שנעתק גם מבחי' א\"א. וזהו אתה תומיך גורלי, שהוא בחי' יחידה שבנפש, הניצוץ נברא שבו מתלבש הניצוץ בורא, שלכן נקראת בשם יחידה (וזה שמה אשר יקראו לה<sup data-n=\"495\">160</sup>), כי היא (שם ו)כלי לבחי' יחיד<sup data-n=\"496\">161</sup>, שהוא הניצוץ בורא, העצמות של כאו\"א מבנ\"י.\nטו) <b>וזהו</b> מה שממשיך בהכתוב<sup data-n=\"497\">162</sup> למען יחלצון ידידיך הושיעה ימינך וענני. דמזה שאומר למען גו' מובן, שכתוב זה הוא המשך להכתוב הקודם נתת ליראיך נס גו'. והיינו דזה שנתת ליראיך נס להתנוסס גו', שהו\"ע עבודת הנסיונות, הוא בכדי (למען) שיהי' יחלצון ידידיך הושיעה ימינך גו'. והענין הוא דהנה איתא במדרש<sup data-n=\"498\">163</sup> עה\"פ<sup data-n=\"499\">164</sup> השיב אחור ימינו, דקאי על ימינו של הקב\"ה, דבזמן הגלות נאמר השיב אחור ימינו, ובעת הגאולה אותה ימין שהיא משועבדת כו' גאלתי את ימיני כו' (ועי\"ז נעשה ג\"כ גאולת ימין של כאו\"א מישראל). וזהו הקשר לענין הנסיונות, כי בחי' ימין נמשכת ע\"י העבודה דגורל, וכמו שמביא במדרש שם (ע\"ז שבעת הגאולה תהי' גאולת ימינו של הקב\"ה) מש\"נ בדניאל<sup data-n=\"500\">165</sup> ואתה לך גו' ותעמוד לגורלך לקץ הימין. כי ימין שייכת להגורל. וביאור הענין הוא<sup data-n=\"501\">166</sup>, דאיתא במדרש שם שא\"ל קץ הימים או קץ<sup data-n=\"502\">167</sup> הימין, א\"ל קץ<sup data-n=\"502\">167</sup> הימין. ומבאר בהדרושים<sup data-n=\"503\">168</sup> דימין קאי על ימין שבא\"א, ולמעלה יותר, בחי' ימין שלמעלה מא\"א (שהו\"ע הרצון, כ\"א), שהוא עתיק שכולא ימינא דלית שמאלא בהאי עתיקא<sup data-n=\"504\">169</sup>. דבחי' זו ישנה גם בזמן הגלות וכמש\"נ<sup data-n=\"505\">170</sup> ימין ה' רוממה ימין ה' עושה חיל, אלא שבזמן הגלות היא בבחי' העלם שאינהמאירה בגילוי בנפש האדם. אבל כאשר האדם עובד עבודתו מצד ימין שבנפשו, העבודה מצד עצם נפשו (שלמעלה מן הרצון, מקיף הקרוב), שהו\"ע הגורל, הנה עי\"ז ותעמוד לגורלך לקץ הימין, שגורל שבאדם ממשיך גורל שלמעלה, דאתה תומיך גורלי כנ\"ל, שהוא בחי' עתיק. והנה ע\"י ימין, עתיק, נעשה ג\"כ הושיעה ימינך וענני, שנגאל הימין דהשיב אחור ימינו שהיתה משועבדת. וזהו הקישור שבין ב' הענינים שבקץ הימין, הא' ימין עצמה, שהיא עתיק כנ\"ל, והב' קץ הימין דקאי על ספירת המלכות<sup data-n=\"506\">171</sup> (שלכן נקרא קץ לשון סוף ותכלית, כי תכלית וסוף ההמשכה דבחי' ימין הוא במלכות<sup data-n=\"507\">172</sup>), דספירת המלכות היא למטה מכל הספירות, עד שרגלי' יורדות כו'<sup data-n=\"508\">173</sup>, עד לירידה בעולם התחתון שאין תחתון למטה ממנו. ודוקא בעבודה זו לגאול קץ הימין מירידתה למטה בא לידי גילוי ימין דותעמוד לגורלך לקץ הימין, עתיק. וע\"ד משנת\"ל דדוקא בעבודת הנסיונות, שהיא בענינים תחתונים ביותר, ובעיקר בנסיונות דדרא דעקבתא דמשיחא, שאז חושך הגלות הוא כפול ומכופל, באה לידי גילוי העבודה שמצד יחידה. וזהו הקישור בין נתת ליראיך נס להתנוסס גו' ללמען יחלצון ידידיך הושיעה ימינך וענני, כי ע\"י עבודת הנסיונות נגאל הימין.\nטז) <b>ויש</b> לקשר זה עם מ\"ש במזמור תהלים<sup data-n=\"509\">174</sup> שמתחילים לומר בי\"ב תמוז שנה זו (תשל\"ו)<sup data-n=\"510\">175</sup>, אור זרוע לצדיק ולישרי לב שמחה. ומביא כ\"ק אדמו\"ר הצ\"צ ברשימותיו לתהלים<sup data-n=\"511\">176</sup> מה שארז\"ל במדרש<sup data-n=\"512\">177</sup>, דאור זרוע לצדיק הוא האור שנברא ביום ראשון וגנזו לצדיקים לעת\"ל (ועי\"ז ולישרי לב שמחה, שהם הצדיקים שלבם ברשותם<sup data-n=\"513\">178</sup>). ומדייק אור זרוע גו', זריעה דוקא. וע\"ד זריעה גשמית, שצ\"ל רקבון הגרעין, שזה דוקא מעורר כח הצמיחה שבארץ. שכח הצמיחה שבארץ הוא כח הא\"ס, וע\"י הצמיחה הוא גילוי כח הא\"ס (כמובן מאגה\"ק ס\"כ). ועד\"ז הוא ברוחניות, שע\"י העבודה דביטול ומס\"נ מגיעים לא\"ס שלמעלה מהשתלשלות. וכמבואר במאמרים<sup data-n=\"514\">179</sup> על הכתוב<sup data-n=\"515\">180</sup> הבאים ישרש יעקב יציץ ופרח ישראל ומלאו פני תבל תנובה, שהיא העבודה דתומ\"צ בביטול (כענין הזריעה), הנה עי\"ז דוקא ומלאו פני תבל תנובה גילוי כח הא\"ס, וכמבואר ג\"כ בהמשך כל הנהנה תרנ\"ב<sup data-n=\"516\">181</sup>. וע\"ד משנת\"ל שדוקא ע\"י העבודה דנסיונות מגיעים לבחי' נס בתוך נס, עצמותו ומהותו ית'.יז) <b>וזהו</b> ג\"כ מש\"נ<sup data-n=\"517\">182</sup> וכל קרני רשעים אגדע תרוממנה קרנות צדיק, ואיתא במדרש<sup data-n=\"518\">183</sup> עשר קרנות הן שנתן הקב\"ה לישראל כו' כיון שחטאו ישראל ניטלו מהן וניתנו לעכו\"ם כו'. דענין של קרן והגבהה שייך רק בישראל. אלא שמפני חטאינו (עכ\"פ הענין דחטא ענין חסרון כמש\"נ<sup data-n=\"519\">184</sup> אני ושלמה בני חטאים) גלינו מארצנו, וכשזה קם זה נופל<sup data-n=\"520\">185</sup>, ואז קרני העכו\"ם קיימות וקרני ישראל גדועים<sup data-n=\"521\">186</sup> ר\"ל. אבל ע\"י לימוד התורה וקיום מ\"ע ושמירת מל\"ת, ובעיקר ע\"י העבודה דמס\"נ בענין הנסיונות, ובמיוחד בדרא דעקבתא דמשיחא שאז העבודה קשה ביותר כנ\"ל, שעבודה זו היא מצד בחי' נס שבתוך נס שבנפש כנ\"ל, הנה עי\"ז נעשה תרוממנה קרנות צדיק, דלא רק שישנם הקרנות (שעי\"ז כל קרני רשעים אגדע), כ\"א שהם באופן של תרוממנה, נס בתוך נס, בחי' קץ הימין שלמעלה מימין דא\"א. שזהו החידוש דגאולה העתידה על הגאולה דיצי\"מ, דיציאת מצרים היתה ע\"י זרועות דא\"א<sup data-n=\"522\">187</sup>, שהן ב' בחי', זרוע ימין וזרוע שמאל, אבל תרוממנה קרנות צדיק הוא ימין דעתיק. ודוגמתו במצוות הן המצוות שאינם תלויין ברצונו של האדם, כנ\"ל, ואדרבה, הרצון לנשיאות וכו' כנ\"ל מבלבל לקיום מצוות אלו. ובעבודה הו\"ע העבודה שלמעלה ממדוה\"ג, שעומד בתוקף נגד ההעלמות וההסתרים ואינו משים לב אליהם, בחי' הגורל הנ\"ל.\nחי) <b>והנה</b> ע\"י העבודה דגורל הנ\"ל יחלק הארץ, היינו שנעשה נוסף על כיבוש הארץ, יחלק הארץ, שהו\"ע ההתישבות. וכמו שאמרו רז\"ל<sup data-n=\"523\">188</sup> דוירשתה וישבת בה<sup data-n=\"524\">189</sup> דהיינו לאחרי שבע שכבשו ושבע שחלקו, ואז הותחל עיקר ענין קיום המצוות התלויות בארץ. ועד\"ז בענין ארץ שלמעלה, עוה\"ב, שהוא שכר המצוות, דזה שכל ישראל יש להם חלק לעולם הבא הוא מצד זה שישנה בחינת הגורל דאתה תומיך גורלי אצל כאו\"א מישראל. וגם מי שבגלוי אין ניכר אצלו ענין של טוב וקדושה, יש לו בחי' גורל בנפשו, ואדרבה יכול להיות שדוקא אצלו ישנה נשמה קדושה ביותר. ומשו\"ז יכול להפוך את עצמו בשעתא חדא וברגעא חדא שיהי' בתכלית השלימות דקדושה. ויובן זה עפ\"י המבואר בכ\"מ<sup data-n=\"525\">190</sup> בענין מה שאמר ריב\"ז<sup data-n=\"526\">191</sup> אינייודע באיזו דרך מוליכין אותי, דאף שעבודתו היתה באופן נעלה ביותר כמבואר בכ\"מ<sup data-n=\"527\">192</sup>, בכ\"ז אמר איני יודע כו', כי הי' מסופק אם עבודתו מצד עצם נפשו (בחי' הגורל הנ\"ל) היא כדבעי, כי אין ראי' מעבודתו בכחות הגלויים להבחי' שלמעלה מטו\"ד. ומרובה מדה טובה כו'<sup data-n=\"528\">193</sup>, דגם אצל מי שבכחות הגלויים שלו אין נראה שום ענין טוב, הנה אין מזה ראי' כלל על הבחי' שלמעלה מזה, ובמיוחד שעל כאו\"א מישראל נאמר&lt;156&gt; אשרנו כו' מה נעים גורלנו, הרי ברור שישנה בו נשמה גדולה ביותר, ויש לו הכח לאתהפכא ולהתגבר וכו' אפילו באם הי' אצלו ח\"ו העלם והסתר של שכלו ומחדו\"מ שלו במשך ימי חייו, וע\"ד ראב\"ד שקנה עולמו בשעה אחת<sup data-n=\"529\">194</sup>. וכמו שהוא בענין חלוקת ארץ שלמעלה, עוה\"ב, שהיא מצד בחי' הגורל שישנה אצל כאו\"א מישראל, עד\"ז הוא בענין כיבוש וחלוקת הארץ כפשוטה, שהיא מצד בחי' הגורל שישנה אצל כאו\"א מישראל, שלכן א\"י שייכת לבנ\"י בברית עולם לזרעך אחריך לאחוזת עולם<sup data-n=\"530\">195</sup>, שהיא ירושה לנו מאברהם (מפני קשט סלה), מברית בין הבתרים. ארץ שבעה אומות, ונוסף ע\"ז ירחיב ה\"א את גבולך<sup data-n=\"531\">196</sup>, שהיא ארץ הקני קניזי וקדמוני<sup data-n=\"532\">197</sup>, כמפורש בברית בין הבתרים ועוד יותר, כמבואר במדרשי רז\"ל<sup data-n=\"533\">198</sup> שירחיב ה\"א את גבולך היא עד להרחבה שלא בערך.\nיט) <b>וזהו</b> נתת ליראיך נס להתנוסס מפני קשט סלה, דקושטי' דאברהם הוא באופן של סלה, לעלמין, דאפילו בסוף כל עלמין בדרא דעקבתא דמשיחא, ובזה גופא ברגעים האחרונים של הגלות, הנה עבודת ישראל היא מתוך מס\"נ, בחי' נס בתוך נס שבנפש, דלא רק שיש אצלם ענין הקרנות, אלא עוד זאת, שהם באופן של תרוממנה קרנות צדיק (וכפירש\"י דקאי על ישראל שהם שבחו של הקב\"ה, צדיקו של עולם). ועי\"ז יחלצון ידידיך הושיעה ימינך וענני, שגואלים הימין שבזמן הגלות היא באופן דהשיב אחור ימינו. והוא ע\"י שמתגלה בחי' גורל אצל כאו\"א, דותעמוד לגורלך לקץ הימין, בחי' אתה תומיך גורלי. ועי\"ז נעשה (אך בגורל) יחלק את הארץ (ובב' הנוסחאות שבכת\"י המאמרים<sup data-n=\"534\">199</sup>, יחלק ותחלק), חלוקת הארץ כפשוטה (דאין ענין יוצא מידי פשוטו), ולמטה מעשרה טפחים בגאולה האמיתית והשלימה ע\"י משיח צדקנו, שאז יהי' כיבוש א\"י השלימה, ולאח\"ז כיבוש ארץ הקני הקניזי והקדמוני, ולאח\"ז ירחיב ה\"א את גבולך, נחלה בלי מצרים. ומכיון שכ\"ז נעשה ע\"י בחי' הגורל שהיא למעלה מטו\"ד, לכן אין צורך כלל באריכות זמן כ\"א בלשוןאדמו\"ר הזקן<sup data-n=\"535\">200</sup> דיום שכולו ארוך היינו שגם בתחלתו הוא ארוך, דבשעתא חדא באה הגאולה האמיתית והשלימה עם כל הפרטים והשלימות שבה, עד כי ירחיב ה\"א את גבולך, ע\"י ה' דוקא<sup data-n=\"536\">201</sup> (ע\"ד דאתה דייקא תומיך גורלי), בקרוב ממש בביאת משיח צדקנו, שהקב\"ה מוליך את ישראל בקומה זקופה בגאולה האמיתית והשלימה, וירם קרן משיחו<sup data-n=\"537\">202</sup>, ויהפכו ימים אלו לששון ולשמחה ולמועדים טובים<sup data-n=\"538\">203</sup>, בעגלא דידן.\n**********",[["335","*","והמשכו ביום א' פ' פינחס, י\"ג תמוז; יום ג' פ' פינחס, ט\"ו תמוז. – יצא לאור \"בסמיכות לחג הגאולה י\"ב-י\"ג תמוז . . <i>עש\"ק חו\"ב יב תמוז</i>,<i> ה'תשמ\"ו</i>\"."],["336","1","תהלים ס, ו."],["337","2","דשנת תרצ\"ג. נדפס בסה\"מ ה'תשי\"א ע' 289 ואילך."],["338","3","שמואל-ב כג, א."],["339","4","ראה שהש\"ר פ\"ד, ד (בתחילתה), שאמר ה\"זמירות (בשם כל) ישראל\"."],["340","5","ובפרט שמסיים \"סלה\" – ראה עירובין נד, א."],["341","6","תו\"א ר\"פ וארא."],["342","7","ברכות טז, ב."],["343","8","פרשתנו (בלק) כג, ט. במדב\"ר פ\"כ, יט. תיב\"ע, ת\"י ופרש\"י עה\"פ. זהר פרשתנו (בלק) רי, ב."],["344","9","ב\"ר פנ\"ט, ו. וראה תו\"ח שמות תקלז, סע\"ב [בהוצאה החדשה – תצוה ח\"ב שסד, א], בענין האהבה המסותרת שהיא בבחי' ירושה מהאבות (תניא פי\"ח) – ש\"העיקר אברהם שהוא השרש הראשון לנש\"י והוא הרועה הראשון כידוע\". וראה בנדו\"ד ד\"ה זה פר\"ת ס\"ד (סה\"מ פר\"ת ע' קיג)."],["345","10","עקב י, יב."],["346","11","ברכות לג, ב."],["347","12","<a class=\"ft-cite\" href=\"#/read/tanya/3401310047\" data-slug=\"tanya\" data-id=\"3401310047\">תניא רפמ\"ב</a>.\nומזה שאומר דיראה היא \"מילתא <i>זוטרתא</i>\" אצל כבנ\"י, מוכח, שבאמת שייך כל איש ישראל לענינים יותר נעלים מיראה."],["348","13","לשון כ\"ק מו\"ח אדמו\"ר בעל הגאולה במכתבו לחגיגת י\"ב-י\"ג תמוז בפעם הראשונה – ט\"ו סיון תרפ\"ח (נדפס בסה\"מ תרפ\"ח ע' קמו ואילך. תש\"ח ע' 263 ואילך. אגרות-קודש לכ\"ק אדמו\"ר מוהריי\"צ ח\"ב ע' פ ואילך). וראה הקדמה לד\"ה נתת ליראיך תרצ\"ג (תשי\"א) הנ\"ל. וש\"נ."],["349","14","ראה דרך חיים ע' 65. אמ\"ב שער הק\"ש פנ\"ז (נה, א). סה\"מ תרע\"ח ע' רפג. תרפ\"ח ע' קב. ובכ\"מ."],["350","15","ישעי' מא, ח. וראה אגה\"ק סי\"ג (קיט, ב). סט\"ו (קכא, סע\"א ואילך). ספר הערכים-חב\"ד ערך אברהם אבינו ס\"א-ב. וש\"נ. – וראה רמב\"ם הל' תשובה פ\"י ה\"ב."],["351","16","וראה ד\"ה הנ\"ל פר\"ת (ע' קיג): ומ\"ש נתת ליראיך הוא דכללות ענין הנסיונות הוא בחי' היראה."],["352","17","וירא כב, יב."],["353","18","ספכ\"ה."],["354","19","<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א (נח, א</a>)."],["355","20","וראה ד\"ה הנ\"ל פר\"ת (ע' קט), שהנסיון הוא \"בכדי שיתגלה בחי' יחידה שבנפש\"."],["356","21","ראה ד\"ה מה טובו תרפ\"ט בתחלתו (סה\"מ קונטרסים ח\"א מח, א. תרפ\"ט ע' 203): נתת ליראיך נס להתנוסס . . והפי' השלישי בנס הוא מלשון נפלאות כו'.\nוראה אוה\"ת שה\"ש ע' כט: והרד\"א [ר' דוד אבודרהם] בפי' ועל הנסים פי' שהוא מלשון נתת ליראיך נס להתנוסס . . וצ\"ע דשם פירש רש\"י נס לשון נסיון כו' וכן פי' ברבות פ' וירא ר\"פ נ\"ה נסיון אחר נסיון כו' וכ\"ה בילקוט בספר שופטים סימן מ\"א."],["357","22","שבת צז, א. וש\"נ. הובא בפרש\"י עה\"פ וארא ט, כד."],["358","23","ב\"ר רפל\"ט."],["359","24","שער דרושי אבי\"ע פ\"א. הובא בלקו\"ת ראה ד\"ה ושמתי כדכד השני פ\"ב. וראה סה\"מ ה'שי\"ת ע' 115 בהערה.\nוזה שייך גם למה שתחילת הכרת אלקות שלו היתה מעניני עולם, כי מצד בחינת ההשתלשלות, העולם הוא מעלים ומסתיר, משא\"כ ע\"י גילוי היחידה שקשורה עם בחי' יחיד – אין מקום לשום מציאות שחוץ ממנו ית' (כדלהלן בפנים סעיף יו\"ד), וגם העולם מראה על אלקות. וכמבואר בהמאמר דבעל השמחה והגאולה (בסופו, וראה גם שם סעיף א), שע\"י העבודה דנסיונות (שמצד בחי' יחידה) נגלה האמת דהטבע עצמו הוא למעלה מהטבע, \"וכל הנבראים הם מופתים מוחשים על האחדות הגמורה דהוי' אחד\"."],["360","25","וירא כא, לג. וראה רמב\"ם הל' ע\"ז פ\"א ה\"ג."],["361","26","סוטה י, סע\"א ואילך."],["362","27","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380888\" data-slug=\"likkutei-torah\" data-id=\"4001380888\">לקו\"ת ס\"פ תבוא (מב, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380891\" data-slug=\"likkutei-torah\" data-id=\"4001380891\">מג, ג</a>). ד\"ה אנכי ה\"א תרע\"ג (המשך תער\"ב ח\"א ע' רנז). סד\"ה ויטע אשל תש\"ב (סה\"מ תש\"ב ע' 59). ועוד."],["363","28","ואתחנן ד, לה."],["364","29","ברכות סא, ב."],["365","30","ד\"ה וירח ה' ה'ש\"ת פ\"א (סה\"מ ה'ש\"ת ע' ו). ד\"ה ויאמר גו' לך לך ה'ש\"ת ספ\"ג (שם ע' טו). סד\"ה החודש ה'ש\"ת (שם ע' 30). שיחת ליל שש\"פ ה'תש\"ג אות סז (סה\"ש תש\"ג ע' 94). ועוד."],["366","31","וירא יח, כז."],["367","32","יחזקאל לג, כד."],["368","33","ב\"ר פמ\"ב, ח."],["369","34","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו. ובכ\"מ."],["370","35","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380793\" data-slug=\"likkutei-torah\" data-id=\"4001380793\">לקו\"ת ראה (יט, ב</a> ואילך) ד\"ה אחרי ה' אלקיכם וביאורו. ד\"ה זה וביאורו בספר המצוות להצ\"צ בסופו. ד\"ה כי מנסה תש\"ח (סה\"מ תש\"ח ע' 94 ואילך). וראה בהבא להלן ד\"ה הנ\"ל פר\"ת ס\"ב (ע' קז)."],["371","36","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, רע\"ב</a>). ד\"ה הנ\"ל פר\"ת ס\"ג (ע' קט)."],["372","37","ראה סנהדרין (לח, א): בע\"ש כו' לסעודה כו'."],["373","38","זח\"ג קפח, ב."],["374","39","ויחי מח, כב."],["375","40","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370140\" data-slug=\"torah-or\" data-id=\"3901370140\">תו\"א וישב ל, ב</a>. לקו\"ת ר\"פ תצא. ובכ\"מ."],["376","41","ראה תענית בתחלתה. וראה בארוכה בקונטרס העבודה."],["377","42","תהלים לד, טו."],["378","43","ועד\"ז הוא בד\"ה הנ\"ל פר\"ת (ע' קז)."],["379","44","סה\"מ תרע\"ח ותרפ\"ח שבהערה 14. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101046\" data-slug=\"likkutei-sichot\" data-id=\"1300101046\">לקו\"ש ח\"י ע' 46</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201074\" data-slug=\"likkutei-sichot\" data-id=\"1300201074\">ח\"כ ע' 74</a> ובהנסמן בהערה 23 שם.\nולהעיר מפרי הארץ (מהרמ\"מ מהאראדאק) פ' וירא (הובא בד\"ה אחרי הנ\"ל להצ\"צ ספ\"ב. ד\"ה הנ\"ל פר\"ת ס\"ג – ע' קח). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101205\" data-slug=\"likkutei-sichot\" data-id=\"1300101205\">לקו\"ש ח\"י ע' 205</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201075\" data-slug=\"likkutei-sichot\" data-id=\"1300201075\">ח\"כ ע' 75</a> והע' 26, <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201077\" data-slug=\"likkutei-sichot\" data-id=\"1300201077\">28 שם. ע' 77</a> והע' 47 שם."],["380","45","סכ\"א. וראה לקו\"ש ח\"י שם. ח\"כ שם הע' 26, 47."],["381","46","תנחומא וירא כב."],["382","47","פרש\"י וירא כב, יב (מב\"ר פנ\"ו, ח)."],["383","48","נדפסו בלקו\"ד ח\"ד תרכו, א. ספר השיחות תר\"פ – תרפ\"ז ע' 194."],["384","49","ראה ספר השיחות תש\"א ע' 138. תש\"ב ע' 2-81."],["385","50","ראה תורת שלום ע' 26. 115."],["386","51","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181323\" data-slug=\"likkutei-sichot\" data-id=\"1300181323\">לקו\"ש חי\"ח ע' 314</a> ואילך."],["387","52","ישעי' נט, כא."],["388","53","ב\"מ פה, א."],["389","54","ראה ד\"ה הנ\"ל פר\"ת (ע' קיא): שקיום המצות הוא בשמחת נפשו . . ובכללות הוא שיהי' לו חיות פנימי בקיום המצות ובעסק התורה . . ומזה הוא [בא] להדר בעשיית המצות כו'."],["390","55","עירובין מא, א."],["391","56","לשון אדה\"ז באגה\"ק סי' ז\"ך."],["392","57","ראה יג, ד."],["393","58","לשון חז\"ל – חגיגה ה, ב."],["394","59","נוסח ברכת אלקי נשמה כו' (מברכות ס, ב. רמב\"ם הל' תפלה פ\"ז ה\"ג. ועוד)."],["395","60","ראה המשך תרס\"ו ע' תעב. תפה ואילך. <i>ובכ\"מ</i>."],["396","61","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["397","62","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז (יא, ב</a>)."],["398","63","פ\"ו. פכ\"ד."],["399","64","שער מ\"ב ספ\"ד."],["400","65","שבת פח, סע\"ב ואילך."],["401","66","שבת קה, ב."],["402","67","ר\"פ כ."],["403","68","וראה ד\"ה ברוך הגומל די\"ג תמוז תרפ\"ז (יום הגאולה) – נדפס בסה\"מ תרפ\"ז ס\"ע רח ואילך. קונטרסים ח\"א קפג, א ואילך."],["404","69","שער כ\"ו פ\"א."],["405","70","פל\"ז (מח, רע\"ב)."],["406","71","ראה גם ד\"ה הנ\"ל פר\"ת ס\"ג (ע' קט)."],["407","72","זח\"א ריז, ב."],["408","73","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א נח ט, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת ראה כה, א</a>. ובכ\"מ."],["409","74","ח\"ג לב, א."],["410","75","קידושין בסופה."],["411","76","בראשית ב, טו."],["412","77","אוה\"ת בראשית (כרך ו) תתרמא, סע\"ב – בשם ארז\"ל. וראה זח\"א כז, א. תקו\"ז תכ\"א (סב, א). שם תנ\"ה (פח, ב). זח\"א קצט, ב (הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381323\" data-slug=\"likkutei-torah\" data-id=\"4001381323\">לקו\"ת שה\"ש מח, ד</a>). ח\"ב קסה, ב. וראה תיב\"ע ות\"י עה\"פ."],["413","78","עירובין צו, א."],["414","79","קידושין מ, ב. ב\"ק יז, א. רמב\"ם הל' ת\"ת פ\"א ה\"ג. פ\"ג ה\"ג. וראה הל' ת\"ת לאדה\"ז פ\"ד ה\"ג."],["415","80","קידושין ל, ב."],["416","81","ד\"ה מה טובו (עג, ב ואילך)."],["417","82","בכללות הענינים דלהלן (סעיפים ז-ט) ראה ד\"ה הנ\"ל פר\"ת ס\"ב (ע' קז ואילך). מקומות שבהערה 35."],["418","83","עקב ח, ג."],["419","84","ל\"ת עה\"פ."],["420","85","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380129\" data-slug=\"likkutei-torah\" data-id=\"4001380129\">לקו\"ת צו יג, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380794\" data-slug=\"likkutei-torah\" data-id=\"4001380794\">לקו\"ת ראה הנ\"ל יט, ג</a>. ד\"ה אחרי הנ\"ל להצ\"צ פ\"ב. ד\"ה הנ\"ל פר\"ת שם. ובכ\"מ."],["421","86","לקו\"ת ראה, ד\"ה אחרי וד\"ה הנ\"ל פר\"ת שבהערה שלפנ\"ז. ובכ\"מ."],["422","87","וכמש\"נ (אבות פ\"ו מ\"ד) פת במלח תאכל. וראה לקו\"ת ויקרא רד\"ה ולא תשבית."],["423","88","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370294\" data-slug=\"torah-or\" data-id=\"3901370294\">תו\"א בשלח סו, א</a>."],["424","89","ראה ספר השיחות תורת שלום ע' 135-134. המשך תער\"ב ח\"ב ע' תרפא. פר\"ת ע' רצט ואילך."],["425","90","ב\"ר פ\"ג, ז. שם פ\"ט, ב. ועוד. וראה סה\"מ ה'ש\"ת ע' 55 בהערה."],["426","91","ברכה לג, ד. ד\"ה אם רוח המושל תרצ\"ה ספ\"ו (סה\"מ קונטרסים ח\"ב שסב, ב). <i>ובכ\"מ</i>."],["427","92","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז</a>."],["428","93","ר\"פ פקודי."],["429","94","נצבים כט, כח. תקו\"ז ת\"י (כה, ב). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת שם. ראה כט, א</a>."],["430","95","רמב\"ם הל' יסוה\"ת פ\"ו ה\"ד. לקו\"ת פקודי שם."],["431","96","יומא פו, ב."],["432","97","זח\"א קכט, סע\"א."],["433","98","ראה ע\"ז יז, א."],["434","99","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381119\" data-slug=\"likkutei-torah\" data-id=\"4001381119\">לקו\"ת ברכה צח, א</a>: שהמקום והזמן שניהם הם נבראים בבחינה אחד. וראה שעהיוה\"א פ\"ז (פב, רע\"א)."],["435","100","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a>. ועוד."],["436","101","ודברים שאסורים בהנאה – יש להם \"מציאות\" (ולא כנסיונות שכמה מהם אין להם מציאות וענינם הוא רק שהועמד דבר להעלים ולמנוע). ובפרט אלה שאין אומרים בהם כתותי מיכתת שיעורי'. וידוע השקו\"ט האם איסור הנאה נוגע בהצורה שלו או גם בהעצם (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300161088\" data-slug=\"likkutei-sichot\" data-id=\"1300161088\">לקו\"ש חט\"ז ע' 88</a> ואילך. וש\"נ)."],["437","102","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071311\" data-slug=\"likkutei-sichot\" data-id=\"1300071311\">לקו\"ש ח\"ז ע' 299</a>."],["438","103","להעיר ממש\"נ בעשה\"ד וחמורך."],["439","104","חולין יז, א."],["440","105","ראה רמב\"ם רפ\"ח מהל' מלכים."],["441","106","בחולין שם: <i>כתלי</i> דחזירי, אבל ברמב\"ן עה\"ת (מטות לא, כג) הוא כבפנים. וראה מגילה יג, א: שהאכילה <i>קדלי</i> דחזירי."],["442","107","ראה הנסמן בהגש\"פ עם לקוטי טעמים, מנהגים וביאורים (קה\"ת ה'תשמ\"ו) ע' תיט."],["443","108","ראה אבות פ\"א מ\"א."],["444","109","יבמות כ, א. ספרי ראה יד, כא. וראה תניא פ\"ל (לט, א) \"שהוא מדאורייתא\". וראה רמב\"ן ר\"פ קדושים. תניא פ\"ז. פכ\"ז (לד, סע\"ב). קונטרס ומעין מ\"א פ\"א. סה\"מ תש\"ח ע' 133 ובהערה ח שם."],["445","110","סנהדרין פט, ב. תנחומא וירא כב. פרש\"י וירא כב, ב. – נתבאר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201073\" data-slug=\"likkutei-sichot\" data-id=\"1300201073\">לקו\"ש ח\"כ</a> שיחה ג' לפ' וירא (ע' 73 ואילך)."],["446","111","וירא שם, א."],["447","112","ראה ד\"ה הנ\"ל פר\"ת שם (ס\"ע קז ואילך)."],["448","113","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז</a>. הובא בד\"ה הנ\"ל שם ע' קח."],["449","114","קפו, א ואילך."],["450","115","דשנת פר\"ת הנ\"ל סוף ס\"ד (ע' קיד)."],["451","116","תנחומא וירא כא. יל\"ש עה\"פ תהלים ס, ו (רמז תשעז)."],["452","117","ראה ד\"ה נתת ליראיך תרצ\"ג הנ\"ל בתחילתו. ולהעיר מהמבואר בד\"ה הנ\"ל פר\"ת ס\"ב (ע' קז):וזהו שהבירורים דזה\"ג הן בדרך נסיון, להיות שבגלות האחרון הוא שמתבררים הניצוצות היותר אחרונים ששרשן למעלה יותר ונפלו בבחי' הסתר ביותר."],["453","118","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370234\" data-slug=\"torah-or\" data-id=\"3901370234\">תו\"א שמות נב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540526\" data-slug=\"torat-chaim\" data-id=\"2300540526\">תו\"ח שם סד, ב</a> [בהוצאה החדשה – וארא ח\"א מו, ד]. סד\"ה ויאמר משה עטר\"ת (סה\"מ עטר\"ת ע' תסד, נעתק בלקו\"ד כרך א קי, א)."],["454","119","סה\"מ תרפ\"ד ס\"ע ב ואילך. קונטרסים ח\"א נג, א ואילך. תרפ\"ט ע' 214 ואילך. תש\"ב ע' 13. תש\"ט ע' 5. תש\"י ע' 237."],["455","120","בהעלותך יב, ג."],["456","121","סה\"מ קונטרסים שם."],["457","122","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021366\" data-slug=\"likkutei-sichot\" data-id=\"1300021366\">לקו\"ש ח\"ב ע' 642</a>."],["458","123","ראה כתובות סז, א."],["459","124","ראה אגה\"ק סו\"ס כח."],["460","125","פכ\"ט."],["461","126","ברכות ה, א."],["462","127","ראה תניא שם."],["463","128","משלי טז, ז. ירושלמי תרומות פ\"א סה\"ג. ב\"ר רפנ\"ד. וראה אוה\"ת בראשית מז, סע\"ב ואילך."],["464","129","ד\"ה נתת ליראיך תרצ\"ג הנ\"ל בתחלתו."],["465","130","תנחומא נשא יא. במדב\"ר פי\"ב, ג."],["466","131","תהלים ח, ג."],["467","132","נדפס בסה\"מ תרפ\"ז ע' קי ואילך. תשי\"א ע' 180 ואילך."],["468","133","ראה סה\"מ תרפ\"ז ע' רפח ואילך. תשי\"א ע' 195 ואילך."],["469","134","מדרש תהלים עה\"פ. שהש\"ר פ\"א, ד. פ\"ב, ג (ג). וראה ויק\"ר פל\"א, ה. יל\"ש בשלח רמז רמד. ועייג\"כ זבחים קטז, סע\"א.\nומש\"כ בקהלת יעקב מערכת עוז: לא מצינו בדרז\"ל כו', צע\"ק."],["470","135","ברכה לג, ד."],["471","136","נדה מג, סע\"ב ואילך (במשנה). רמב\"ם הל' נחלות ספ\"א."],["472","137","תהלים מה, יז. וראה ב\"ב קנט, א. שו\"ת צפע\"נ (ווארשא) ח\"ב סקי\"ח. ועוד."],["473","138","ויק\"ר פי\"א, ז. אסת\"ר פתיחתא יא."],["474","139","ראה שבת קיט, סע\"ב. הל' ת\"ת לאדה\"ז פ\"א ה\"ג."],["475","140","די\"ג וט\"ו תמוז. – פנחס כו, נה."],["476","141","אוה\"ת פינחס רד\"ה אך בגורל הא'. ד\"ה אך בגורל תרכ\"ו (סה\"מ תרכ\"ו ס\"ע קצח ואילך)."],["477","142","משנה סנהדרין ר\"פ חלק."],["478","143","ישעי' ס, כא."],["479","144","אגה\"ק סו\"ס ז. ועד\"ז הוא גם באוה\"ת שם ע' א'ס ואילך. תרכ\"ו שם (ע' ר ואילך). ד\"ה אשרנו תרפ\"ח ותרצ\"ו ס\"ד (סה\"מ תרפ\"ח ע' קטז ואילך. קונטרסים ח\"ב שסז, א ואילך. תרצ\"ו ע' 56 ואילך). ובכ\"מ."],["480","145","ראה גם ד\"ה אשרנו הנ\"ל שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131117\" data-slug=\"likkutei-sichot\" data-id=\"1300131117\">לקו\"ש חי\"ג ע' 117</a>. וש\"נ."],["481","146","שבת סג, א. וש\"נ. פרש\"י עה\"פ וישב לז, יז. ועוד."],["482","147","עקב יא, יב."],["483","148","סי\"ד."],["484","149","ראה אוה\"ת שם ע' א'סג. תרכ\"ו שם (ע' רד)."],["485","150","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370171\" data-slug=\"torah-or\" data-id=\"3901370171\">תו\"א מקץ לז, ג</a>. ובכ\"מ."],["486","151","שמות נב, ב."],["487","152","ראה סה\"מ תש\"ג ע' 15. תשובות וביאורים ס\"י [אגרות-קודש ח\"ב ע' נה ואילך]."],["488","153","ראה סה\"מ שם."],["489","154","ראה עירובין יג, ב."],["490","155","צט, ב ואילך. סידור (עם דא\"ח) כא, א."],["491","156","בנוסח התפלה."],["492","157","ס\"ז."],["493","158","ראה שבת קיח, ב."],["494","159","תהלים טז, ה."],["495","160","ראה שעהיוה\"א פ\"א."],["496","161","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>. ד\"ה אשרנו הנ\"ל שם. ובכ\"מ."],["497","162","תהלים ס, ז."],["498","163","איכ\"ר עה\"פ. מדרש תהלים מזמור קלז. ועוד."],["499","164","איכה ב, ג."],["500","165","בסופו."],["501","166","בהבא לקמן ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450591\" data-slug=\"or-hatorah-hb\" data-id=\"8316450591\">אוה\"ת שם ע' א'סא</a> ואילך. תרכ\"ו שם (ע' רב ואילך)."],["502","167","באיכ\"ר שם: אחרית. אבל במדרש תהלים שם (ועוד) הוא כבפנים."],["503","168","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381040\" data-slug=\"likkutei-torah\" data-id=\"4001381040\">לקו\"ת סוכות עט, א</a> ואילך. יהל אור לתהלים כאן. אוה\"ת פינחס שם. תרכ\"ו שם."],["504","169","זח\"ג קכט, א. וראה שם רפט, א."],["505","170","תהלים קיח, טז."],["506","171","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316270203\" data-slug=\"or-hatorah-hb\" data-id=\"8316270203\">אוה\"ת שם (ע' א'סג</a>) ותרכ\"ו שם (ע' רג) בשם הרמ\"ז (לזח\"ב קפא, ב) ומאו\"א (אות ק, יג)."],["507","172","אוה\"ת ותרכ\"ו שם."],["508","173","משלי ה, ה. וראה זח\"א קסא, ב. ובכ\"מ. לקו\"ת פרשתנו (פינחס) עה, ד. ובכ\"מ."],["509","174","צז, יא."],["510","175","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300221185\" data-slug=\"likkutei-sichot\" data-id=\"1300221185\">לקו\"ש חכ\"ב ע' 185</a> הערה 3."],["511","176","יהל אור עה\"פ (ע' שנב ואילך)."],["512","177","שמו\"ר ר\"פ לה. וראה בהנסמן ביהל אור שם ס\"ו (ע' שנג)."],["513","178","ב\"ר פל\"ד, י."],["514","179","תו\"א שמות נג, ג ואילך. ובכ\"מ."],["515","180","ישעי' כז, ו."],["516","181","סה\"מ תרנ\"ב ע' קכח."],["517","182","תהלים סוף מזמור עה*."],["518","183","מדרש תהלים עה\"פ."],["519","184","מלכים-א א, כא. פרש\"י ומצו\"צ עה\"פ. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. ובכ\"מ."],["520","185","פרש\"י תולדות כה, כג."],["521","186","לשון המדרש שם."],["522","187","סידור האריז\"ל בפי' עבדים היינו. סידור (עם דא\"ח) רד\"ה עבדים היינו. אוה\"ת פינחס שם (ע' א'סב). תרכ\"ו שם (ס\"ע רב)."],["523","188","קידושין לז, א ובפרש\"י שם. פרש\"י ר\"פ תבוא."],["524","189","ר\"פ תבוא."],["525","190","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380311\" data-slug=\"likkutei-torah\" data-id=\"4001380311\">לקו\"ת ויקרא בהוספות נד, סע\"ד</a>. ס' מאמרי אדה\"ז הקצרים ע' שט. – נעתק (עם הגהות) באוה\"ת וסה\"מ תרכ\"ו הנ\"ל. ד\"ה אשרנו הנ\"ל. ובכ\"מ."],["526","191","ברכות כח, ב.\n*) <i>להעיר שע\"פ המנהג לומר בכל יום הקאַפּיטל תהלים המתאים לשנות חייו (אגרות-קודש אדמו\"ר מהוריי\"צ ח\"א ע' לא</i>.<i> ח\"י ע' נג</i>.<i> וראה גם מאמרי אדה\"ז הקצרים ע' שמא</i>.<i> סה\"מ תשכ\"א ע' 231</i>.<i> סה\"מ י\"א ניסן ע' 1 ואילך) – התחילו בי\"א ניסן שנה זו דאמירת המאמר (תשל\"ו) לומר מזמור עה שבתהלים</i>. <b>המו\"ל</b>."],["527","192","ראה לדוגמא: סוכה כח, א. ר\"ה לא, סע\"ב. ועוד. הובאו כמה מהם במקומות שצויינו בהערה 190."],["528","193","סוטה יא, א. וש\"נ. הובא בפרש\"י עה\"פ יתרו כ, ו. תשא לד, ז."],["529","194","ע\"ז יז, א."],["530","195","לך לך יז, ח."],["531","196","ראה יב, כ. שופטים יט, ח."],["532","197","ספרי עה\"פ ראה שם. פרש\"י עה\"פ שופטים שם."],["533","198","ראה ספרי לראה שם. ומקרא מלא דיבר הכתוב (משפטים כג, לא): ושתי את גבולך מים סוף ועד ים פלשתים וממדבר עד הנהר (ראה מכילתא לבא יב, כה) ומסיים בלקח טוב: שנאמר (תהלים עב, ח) וירד מים עד ים ומנהר עד אפסי ארץ. וראה שבת (קיח, סע\"א ואילך) נחלת יעקב אביך (ישעי' נח, יד), ופרצת ימה וקדמה וצפונה ונגבה (ויצא כח, יד) נחלה בלי מצרים."],["534","199","ראה אוה\"ת ר\"פ פינחס בהערה."],["535","200","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370088\" data-slug=\"torah-or\" data-id=\"3901370088\">תו\"א יח, ד</a>."],["536","201","וגם הביהמ\"ק הוא דוקא ע\"י קוב\"ה כו' (זהר ח\"ג רכא, א. ח\"א כח, א)."],["537","202","שמואל-א ב, י. וראה מדרש תהלים שם, שזהו מהעשרה קרנות שנתן הקב\"ה לישראל."],["538","203","זכרי' ח, יט. וראה ד\"ה ציון במשפט תשל\"ה הערה 43 (לקמן ע' קכח)."]]],[1500390008,"<h3>בס\"ד. י\"ב תמוז ה'תשל\"ח<sup data-n=\"539\">*</sup></h3>\n<b>זה</b> היום עשה ה' נגילה ונשמחה בו<sup data-n=\"540\">1</sup>, ומביא כ\"ק מו\"ח אדמו\"ר בעל הגאולה במאמרו ד\"ה זה [שאמרו בחגיגת י\"ב תמוז הראשונה (בסעודת הודאה), בשנת תרפ\"ח<sup data-n=\"541\">2</sup>], דאיתא במדרש<sup data-n=\"542\">3</sup>, אמר ר' אבין אין אנו יודעים במה לשמוח אם ביום או בהקב\"ה, בא שלמה ופירש<sup data-n=\"543\">4</sup> נגילה ונשמחה בך בהקב\"ה, בך ביראתך, בך בתורתך, בך בישועתך<sup data-n=\"544\">5</sup>. אמר ר' יצחק בך בעשרים ושתים אותיות שכתבת לנו בתורה, ב' תרין כ' עשרין, הרי בך. ומדייק בהמאמר, מהו אומרו אין אנו יודעים במה לשמוח אם ביום או בהקב\"ה, דמכיון שזה היום עשה ה' [היינו, דגם מעלתו של היום הוא לא מצד עצמו אלא שזה היום עשה ה'], הרי מובן לכאורה שהשמחה צריכה להיות בהקב\"ה, ומהו אומרו אין אנו יודעים במה לשמוח אם ביום או בהקב\"ה. וגם מה הם ג' הענינים דיראה תורה וישועה. וגם צ\"ל המאמר דר' יצחק בך בעשרים ושתים אותיות כו', הרי בך בפשטות הוא בך בהקב\"ה, ולמה מפרש בך בעשרים ושתים אותיות.\nב) <b>והנה</b> ביאור מעלת היום (ועד שיש קס\"ד לשמוח בהיום) הוא<sup data-n=\"545\">6</sup>, כי היום שבו נעשה נס<sup data-n=\"546\">7</sup> הוא יום נעלה. ושני ענינים בזה. דהיום שבו נעשה נס הוא יום זכאי מצד עצמו (גם מקודם), שלכן נעשה בו נס, כי מגלגלין זכות ליום זכאי<sup data-n=\"547\">8</sup>. ועוד דע\"י הנס שהי' בו, נעשה יום זכאי ויום סגולה וכו' (עוד יותר מכמו שהי' לפני זה). ולא עוד אלא שביום זה עצמו עיקר העילוי הוא בהזמן הפרטי (יום או לילה) שבו נעשה הנס. כדאיתא במדרש<sup data-n=\"548\">9</sup> בשעה שאתה עושה לנו נסים ביום אנו אומרים לפניך שירה ביום (ותשר דבורה וברק בן אבינועם <i>ביום</i> וגו'<sup data-n=\"549\">10</sup>), ובשעה שאתה עושה לנו נסים בלילה אנו אומרים לפניך שירה בלילה (השיר יהי' לכם <i>כליל</i> התקדש חג<sup data-n=\"550\">11</sup>).<b>ויש</b> לומר, דהחילוק בהזמן שבו נעשה הנס, יום או לילה, הוא בהתאם לדרגת ואופן הנס, אם הנס באופן של אור וגילוי (יום) או שהוא באופן דהעלם (לילה). ועפ\"ז יומתק גם זה שהנס הוא באופן של יום, אור וגילוי<sup data-n=\"551\">12</sup>.\nג) <b>וביאור</b> הענין (השייכות דהזמן שבו נעשה הנס להנס) יובן בהקדים הידוע דנס הוא מלשון הרמה<sup data-n=\"552\">13</sup>. דע\"י הנס נעשה הרמה ועלי' בהטבע<sup data-n=\"553\">14</sup>. דזהו מה שאומרים ברוך שעשה לי נס במקום הזה<sup data-n=\"554\">15</sup>, דגם המקום שהוא גבול וטבע מתעלה בהבל\"ג דהנס שלמעלה מהטבע. ומזה מובן שעד\"ז הוא בנוגע לזמן שנעשה בו הנס, וכמו שאומרים בברכת הנסים (דחנוכה ודפורים) שעשה נסים לאבותינו בימים ההם בזמן הזה.\nד) <b>וביאור</b> הענין בפרטיות יותר, הנה ידוע<sup data-n=\"555\">16</sup> דבנסים יש (בכללות) שני סוגים. נסים שלמעלה מהטבע [כהנסים שהיו ביציאת מצרים, הפיכת מים לדם וכו' ועד להנס דקריעת ים סוף שנהפך ים ליבשה], ונסים המלובשים בדרכי הטבע. ובהם גופא ישנם שני אופנים. שלבושי הטבע הם באופן שניכר בהם שהם רק לבוש להנס שמתלבש בהם. כהנסים דחנוכה ופורים (ועד\"ז הנסים של הגאולה די\"ט כסלו<sup data-n=\"556\">17</sup> ודי\"ב תמוז), דעם היותם מלובשים בדרכי הטבע, מ\"מ הי' ניכר בגילוי (ועד שראו כל אפסי ארץ<sup data-n=\"557\">18</sup>) הנס שבהם<sup data-n=\"558\">19</sup>. ושלבושי הטבע מעלימים ומסתירים על הנס שמלובש בהם. ועד שלפעמים הם מעלימים ומסתירים לגמרי, שאין ניכר כלל שהוא נס, אין בעל הנס מכיר בנסו<sup data-n=\"559\">20</sup>.\nה) <b>והנה</b> ידוע<sup data-n=\"560\">21</sup>, דשרש הטבע הוא משם אלקים (אלקים בגימטריא הטבע<sup data-n=\"561\">22</sup>), דבכללות הוא אור הממלא שמתלבש בעולמות לפי ערכם, ושרש הנסיםהוא משם הוי', דבכללות הוא אור הסובב שלמעלה מעולמות. ומזה מובן, דהנסים שאינם מלובשים בטבע, שרש המשכתם הוא מהגילוי דהוי' עצמו, שלמעלה מהתלבשות בשם אלקים, והנסים המלובשים בטבע שרש המשכתם הוא<sup data-n=\"562\">23</sup> מהגילוי דשם הוי' כמו שמתלבש בשם אלקים<sup data-n=\"563\">24</sup>.\n<b>ויובן</b> זה עד\"מ בכח הרצון שבאדם (דרצון הוא משל על אור הסובב), שיש בו ב' מדריגות. רצון שלמעלה מטעם, ורצון שמתלבש בטעם. ובזה גופא (ברצון המלובש בטעם) שני אופנים<sup data-n=\"564\">25</sup>. דעם היותו מלובש בטעם, ניכר בו בגילוי שבעיקרו הוא רצון (שלמעלה מטעם). ושהרצון מטה את השכל באופן שהשכל עצמו נעשה כפי הרצון, ונרגש בו דזה שהוא סובר כן הוא (לא מצד הטיית הרצון אלא) מצד השכל<sup data-n=\"565\">26</sup>. ועד\"ז הוא בנמשל, בגילוי אור הסובב, שיש בו דוגמת ג' דרגות הנ\"ל, שהם שרש ג' הסוגים בנסים, נס שלמעלה מהטבע לגמרי, נס המלובש בטבע באופן שניכר הנס שבו, ונס המלובש בטבע באופן שהטבע מסתיר הנס שבו.\nו) <b>והנה</b> זה שנס הוא מלשון הרמה, שע\"י הנס נעשה הרמה ועלי' בהטבע, הוא בעיקר בהנסים המלובשים בטבע<sup data-n=\"566\">27</sup>. שבהנסים שלמעלה מהטבע, הגילוי דשם הוי' שלמעלה מהטבע הוא באופן שהטבע (הנמשך משם אלקים) בטל ע\"י הגילוי, שידוד מערכות הטבע, וענין נס מלשון הרמה שהגילוי דשם הוי' הוא באופן שהטבע (שנמשך משם אלקים) מתעלה בהאור דשם הוי', הוא (בעיקר) בהנסים המלובשים בטבע. אלא שאעפ\"כ, מזה שגם הנסים שאינם מלובשים בטבע נקראים בשם נס מלשון הרמה, מובן, שגם ע\"י נסים אלו נעשה הרמה ועלי' בהטבע. דכיון<sup data-n=\"567\">28</sup> ששידוד הטבע שע\"י הנס הוא רק בפרט אחד ולא בכללות הדבר [כהנס דקריעת ים סוף, שהשינוי (שידוד הטבע) הי' רק בזה שהמים נצבו כמו נד וכחומה<sup data-n=\"568\">29</sup>, אבל עצםחומר המים נשאר כמו שהי' מקודם<sup data-n=\"569\">30</sup>], נמצא, שגם בנסים אלה, הגילוי דשם הוי' הוא בהתלבשות בהטבע של כללות הדבר שנעשה בו הנס, ועי\"ז נעשה בו הרמה ועלי'<sup data-n=\"570\">31</sup>.\nז) <b>וזהו</b> אומרו אין אנו יודעים במה לשמוח אם ביום או בהקב\"ה, דבכל נס יש שני הענינים דיום ודהקב\"ה. דהרמת הטבע שע\"י הנס הוא יום. וכנ\"ל (סעיף ב' וג') דע\"י הנס נעשה הרמה ועלי' בהזמן (היום) שבו נעשה הנס. והנס עצמו, שענינו הוא למעלה מהטבע, שרש המשכתו הוא מאוא\"ס שלמעלה מעולמות (אור הסובב) כמו שמאיר ומתגלה בעולם<sup data-n=\"571\">32</sup> באופן דסובב ומקיף, הקדוש ברוך הוא. וכמבואר בכ\"מ<sup data-n=\"572\">33</sup> דזה שקוראים אותו ית' בשם הקדוש ברוך הוא, קאי על עצמות אוא\"ס שקדוש ומובדל מעולמות כמו שהוא נמשך (ברוך מלשון המשכה) בעולמות באופן דסובב ומקיף. ואין אנו יודעים במה לשמוח אם ביום או בהקב\"ה, כי בכל אחד מהם יש מעלה שאינה בהשני. דבדרגת האור, הנס עצמו (הענין דשידוד הטבע) הוא נעלה הרבה יותר מהרמת הטבע שע\"י הנס. דהנס עצמו (שידוד הטבע) הוא הגילוי דאור הסובב שלמעלה מעולמות, משא\"כ הרמת הטבע שע\"י הנס הוא הגילוי דאור הסובב כמו שמתלבש בעולמות. אבל בהגילוי, הענין דהרמת הטבע הוא נעלה יותר. דבהנס עצמו, הגילוי דאור הסובב, אין לאדם השגה בזה. שלכן נק' הנסים בשם נפלאות, דפלא הוא שאינו מושג בשכל. ולא עוד, אלא שכשאדם רואה דבר פלא הוא משתומם על זה, דהשתוממות הו\"ע הביטול<sup data-n=\"573\">34</sup>. וכמבואר בכ\"מ<sup data-n=\"574\">35</sup> בענין ארבעה שצריכים להודות<sup data-n=\"575\">36</sup>, דהודאה (על הנס) הו\"ע הביטול. דכמו שבעולם, ענין הנס הוא שהטבע <i>מתבטל</i> [דכיון שהנס בא מהגילוי דעצמות אוא\"ס שלמעלה מהעולמות, שהעולם אינו יכול לקבלו, נעשה עי\"ז ביטול הטבע דעולם], עד\"ז הוא בנוגע להאדם, דע\"י הנס הוא בא להודאה וביטול. משא\"כ הענין דהרמת הטבע, שהגילוי דשם הוי' שלמעלה מהטבע נתלבש בהטבע גופא, על זה כתיב<sup data-n=\"576\">37</sup> <i>דעו</i> כיהוי' הוא אלקים, ידיעה והשגה. וכיון ששמחה היא בבינה דוקא, משא\"כ בחכמה שלמעלה מהשגה אין שייך שמחה<sup data-n=\"577\">38</sup> [אף שגם החכמה היא שכל, אלא שהיא נקודה כללית ואינה בהתיישבות. דמזה מובן במכ\"ש בנוגע לפלא שלמעלה מהשכל], לכן יש קס\"ד לשמוח ביום. ויש להוסיף, דיום הוא אור וגילוי (כמבואר בארוכה בהמאמר דבעל הגאולה בתחלתו). וזהו לשמוח ביום, דהטעם על הקס\"ד לשמוח בהיום שנעשה בו הנס (הענין דהרמת הטבע) הוא, כי ענין זה הוא יום, אור וגילוי (שבא בידיעה והשגה).\nח) <b>ובא</b> שלמה ופירש נגילה ונשמחה בך בהקב\"ה בך ביראתך כו', דפירוש בך בהקב\"ה (שפירש שלמה) הוא בהקב\"ה עצמו שלמעלה גם מסובב. וכמבואר בכ\"מ<sup data-n=\"578\">39</sup> דפירוש בך הוא בך בעצמותך. דהחידוש של שלמה (החכם מכל אדם<sup data-n=\"579\">40</sup>) הוא דשרש הנסים הוא מהעצמות. דזה שהגילוי דשם הוי' שלמעלה מהטבע נתלבש בשם אלקים בגימטריא הטבע (דענין זה הוא בכל הנסים, גם בהנסים שלמעלה מהטבע, כנ\"ל סעיף ו), וגם לאחרי התלבשותו בטבע ניכר בגילוי (גם בהנסים המלובשים בטבע, כהנסים דחנוכה ופורים) שהוא נס (הגילוי דשם הוי') שלמעלה מהטבע, הוא בכח העצמות שמחבר ומאחד שני הפכים.\n<b>וזהו</b> הקשר דשני הפירושים בנגילה ונשמחה בך, בך בהקב\"ה (כפירוש המדרש) ובך בעצמותך, כי החיבור והיחוד דקדוש וברוך (סובב וממלא) הוא בכח העצמות. וכיון שהפסוק נגילה ונשמחה בך מובא במדרש בהמשך לשתי הסברות (בענין השמחה בהנסים), אם לשמוח בהקב\"ה (בהנס עצמו שנמשך מאור הסובב) או לשמוח בהיום (מהתלבשות הסובב בממלא, שעי\"ז מתלבש הנס בטבע), והחידוש דשלמה הוא שהשמחה צריכה להיות בך בעצמותך שמחבר שני הענינים, לכן אומר בך בהקדוש ברוך הוא (ולא בך בעצמותך), כי כח העצמות שמתגלה בנסים הוא בזה שמאחד ב' הבחינות דקדוש וברוך.\nט) <b>וממשיך</b> במדרש בך ביראתך בך בתורתך בך בישועתך, דהמשכת העצמות היא ע\"י היראה. וכמבואר בכ\"מ<sup data-n=\"580\">41</sup> החילוק בין אהבה ליראה, דע\"י האהבה, כיון שהיא מציאות והתפשטות, מגיעים בהגילויים דאוא\"ס (התפשטות), ודוקא ע\"י היראה שהיא ביטול, ועד ביטול שמצד עצם הנשמה, מגיעים בהעצמות. אבל, זה שע\"י היראה מגיעים בהעצמות, הוא בהעלם, ובכדי שיהי' גילוי העצמות הוא ע\"י התורה, תורה אור<sup data-n=\"581\">42</sup>. דהגם שהביטול דיראה הוא מצד עצם הנשמה, דשרשהנשמות הוא למעלה משרש התורה<sup data-n=\"582\">43</sup>, הרי הגילוי דכל ענין (גם דשרש הנשמות כמו שהם מושרשים בהעצמות) הוא ע\"י התורה.\n<b>ויש</b> להוסיף, דמכיון שאסתכל באורייתא וברא עלמא<sup data-n=\"583\">44</sup>, כל ההמשכות שבעולם הם ע\"י התורה. ושני הענינים דלמעלה מהטבע (בל\"ג) ודטבע (גבול) שבעולם, נמשכים משני הענינים דבל\"ג וגבול שבתורה. וכמבואר בכ\"מ<sup data-n=\"584\">45</sup> עה\"פ<sup data-n=\"585\">46</sup> עוטה אור כשלמה, שגליא דתורה (השלמה דתורה) היא במדידה והגבלה, ופנימיות התורה (האור דתורה) הוא בלי גבול. וע\"י היחוד דשני הענינים בתורה, שהגליא והפנימיות הם תורה אחת, ובפרט ע\"י עסק התורה באופן שבלימוד הנגלה נרגש אצלו בגילוי הפנימיות דתורה (הנפלאות שבתורה), עי\"ז נמשך בעולם החיבור דלמעלה מהטבע עם הטבע, ובאופן שגם בהטבע יהי' נרגש בגילוי הנפלאות שלמעלה מהטבע.\n<b>וזהו</b> בך ביראתך בך בתורתך בך בישועתך, שבתחילה צ\"ל ביראתך שעי\"ז ממשיכים את העצמות, ולאח\"ז בתורתך (תורה אור) שעי\"ז נעשה גילוי העצמות, ומזה נמשך להיות בך בישועתך, דהגם שהיו במצב שהוזקקו לישועה, וגם לאח\"ז (כיון שנמצאים עדיין בגלות), הישועה היא בלבושי הטבע, מ\"מ ניכר בה בגילוי, ובאופן דראו כל אפסי ארץ, שהוא נס גלוי שלמעלה מהטבע.\n<b>וממשיך</b> במדרש, אמר ר' יצחק<sup data-n=\"586\">47</sup> בך בעשרים ושתים אותיות שכתבת לנו בתורה, דזה שע\"י התורה נמשכת הישועה באופן הנ\"ל הוא בעיקר באותיות התורה. ושני ענינים בזה. כי החיבור דלמעלה מהטבע עם הטבע הוא בכח העצמות (כנ\"ל), ואותיות התורה הם כלים להמשכת העצמות (כמבואר בהמאמר דבעל הגאולה). והחיות של כאו\"א מישראל הוא ע\"י שיש לו אות בתורה<sup data-n=\"587\">48</sup>, ולכן, בכדי שיהי' נגילה ונשמחה בך (דענין השמחה היא גילוי החיות עד לגילוי פנימיות החיות<sup data-n=\"588\">49</sup>), הוא ע\"י אותיות התורה, שמהם נמשך חיות לכ\"א מישראל.\nי) <b>והנה</b> ידוע<sup data-n=\"589\">50</sup> ששמחה פורצת גדר. ומובן, שהגדרים שנפרצים ע\"י השמחה הם רק הגדרים של אותה הבחינה שבה היא השמחה. ולכן, כאשר השמחה בהנסים היא מצד הגילויים דממלא וסובב (יום והקב\"ה), שהם בגדר ידיעה (אין אנו יודעים), נשארים עדיין הגדרים שישנם בהבחינות שלמעלה מידיעה. משא\"כ ע\"י השמחה דנגילה ונשמחה בך בעצמותך, נעשה פורץ, פריצת כל הגדרים. ועי\"ז מיתוסף עוד יותר בהחיבור דלמעלה מהטבע עם הטבע שנעשה ע\"י גילוי העצמות.<b>וזהו</b> זה היום עשה ה' נגילה ונשמחה בו, דע\"י השמחה בזה היום (באופן דנגילה ונשמחה בך), מיתוסף עוד יותר בהגאולה, שהיא באופן נעלה עוד יותר מכמו שהיתה בפעם הראשונה (כפי שנמשכה מלמעלה, לפני השמחה). וכיון שבהגאולה די\"ב תמוז נגאלו כאו\"א מישראל, גם אלו אשר בשם ישראל (רק) יכונה<sup data-n=\"590\">51</sup>, לכן, גם ההוספה בהגאולה בכל שנה, שנעשית ע\"י שמחת הגאולה, היא נמשכת לכאו\"א מישראל, להגאל מכל הענינים המונעים ומעכבים לתומ\"צ. וע\"פ הידוע שכל הגאולות שייכות זל\"ז כי כולם גאולה נקראות<sup data-n=\"591\">52</sup>, יש לומר, דע\"י השמחה בחגיגת הגאולה, תהי' הוספה גם בגאולה העתידה, שם נשמחה בו<sup data-n=\"592\">53</sup>, בו בעצמותו<sup data-n=\"593\">54</sup>, בביאת משיח צדקנו, בקרוב ממש.\n**********",[["539","*","יצא לאור ב<b>קונטרס חג הגאולה י\"ב-י\"ג תמוז – תשמ\"ט</b>, \"לקראת חג הגאולה י\"ב-י\"ג תמוז . . <i>יום ג' ח' תמוז תשמ\"ט</i>\"."],["540","1","תהלים קיח, כד."],["541","2","ולאחרי עשרים שנה – בשנת תש\"ח – ציוה בעל הגאולה להדפיס את המאמר (בהוספת קיצורים וכו') בקונטרס חג הגאולה י\"ב-י\"ג תמוז ה'תש\"ח (סה\"מ ה'תש\"ח ע' 239 ואילך). ולאח\"ז נדפס גם בסה\"מ ה'תרפ\"ח ע' קנג ואילך."],["542","3","שהש\"ר פ\"א, ד (קרוב לסופו)."],["543","4","שה\"ש א, ד."],["544","5","כ\"ה בהמאמר דבעל הגאולה. ולגירסתנו במדרש הסדר הוא: בישועתך בתורתך ביראתך. ואולי גם בהמאמר הכוונה להסדר מסופו לראשו. וראה בסוף המאמר דבעל הגאולה. וראה גם לקמן סעיף ט."],["545","6","ראה עד\"ז פירוש מהרז\"ו לשהש\"ר שם."],["546","7","להעיר, דפסוק זה היום גו' בא בהמשך למ\"ש לפני זה היא <i>נפלאת</i> בעינינו. ובמצודת דוד שם \"שלא יורה עליו הטבע\"."],["547","8","תענית כט, א. ולהעיר, שכ\"ה בנוגע לי\"ב תמוז – שגם מקודם הי' יום זכאי, ובקשר לבעל הגאולה יום ההולדת שלו."],["548","9","ב\"ר פ\"ו, ב – הובא גם בפירוש מהרז\"ו לשהש\"ר שם."],["549","10","שופטים ה, א."],["550","11","ישעי' ל, כט."],["551","12","ראה מגילה כ, ב דזה היום עשה ה' קאי (לא רק על המעל\"ע, אלא גם) על יום (בניגוד ללילה). וראה בהמאמר דבעל הגאולה בתחלתו (בענין זה היום עשה ה') דיום הוא אור וגילוי."],["552","13","פרש\"י יתרו כ, יז."],["553","14","סידור עם דא\"ח מד, סע\"ב. פירוש המלות לאדמו\"ר האמצעי פקל\"ט. אוה\"ת בשלח ע' תרסה."],["554","15","ברכות נד, א. רמב\"ם הל' ברכות פ\"י ה\"ט. טושו\"ע או\"ח סרי\"ח. סדר ברכת הנהנין לאדה\"ז רפי\"ג. וראה שערי תשובה ח\"א (שער התשובה) פכ\"ג (יד, ג ואילך). שער האמונה פט\"ו* (כט, ב)."],["555","16","ראה סה\"מ תקס\"ח ח\"ה ע' שע ואילך (נוסחא שני'). ביאוה\"ז להצ\"צ ח\"א ע' שטז ואילך. ובארוכה – שער האמונה שם פט\"ו ואילך. ובכ\"מ."],["556","17","להעיר ממה שאמר אדה\"ז בחג הגאולה י\"ט כסלו תק\"ס: \"ברוך שעשה נסים לאבותינו הבעש\"ט ורבינו הרב המגיד, בימים ההם פורים וחנוכה, בזמן הזה י\"ט כסלו\" (לקו\"ד כרך א כא, א. הוספות ל<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316480361\" data-slug=\"or-hatorah-hb\" data-id=\"8316480361\">אוה\"ת חנוכה כרך ה תתריד, א</a>)."],["557","18","ולהעיר ממ\"ש אדמו\"ר הזקן בנוגע לגאולת י\"ט כסלו: \"הפלה ה' והגדיל לעשות בארץ כו' אשר נתגדל ונתקדש ברבים ובפרט בעיני כל השרים וכל העמים כו' אשר גם בעיניהם יפלא הדבר הפלא ופלא כו'\" (אגרות-קודש שלו ח\"א סי' לח. וש\"נ)."],["558","19","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370446\" data-slug=\"torah-or\" data-id=\"3901370446\">תו\"א מג\"א ק, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940148\" data-slug=\"or-hatorah-hb\" data-id=\"8159940148\">אוה\"ת אחרי ע' תקסד</a>. ביאוה\"ז שם ע' שיז. ובכ\"מ."],["559","20","נדה לא, א."],["560","21","ראה סידור ופיה\"מ שם. סד\"ה החודש תרס\"ו. סה\"מ תרע\"ח ע' פט."],["561","22","פרדס שער יב (שער הנתיבות) פ\"ב. ר\"ח שער התשובה פ\"ו ד\"ה והמרגיל (קכא, ב). וראה שם שער\n*) <i>בשער האמונה שם</i>:<i> (טז)</i>.<i> והוא ט\"ס</i>.האהבה ספ\"א ד\"ה וכדי להבין (נב, ד). של\"ה פט, א (דאיתא בזהר); קפט, א (ומרומז בזהר); שח, ב. שו\"ת חכם צבי סי\"ח. שער היחוד והאמונה רפ\"ו."],["562","23","ראה פיה\"מ שם פק\"מ (צד, ד)."],["563","24","והגם דגם <i>התהוות</i> הנבראים (כפי טבעם) הוא לא משם אלקים עצמו אלא מהארת שם הוי' שבשם אלקים – יש לומר, דבנסים המלובשים בטבע, גם כשלבושי הטבע מסתירים לגמרי, הגילוי דשם הוי' הוא באופן נעלה יותר. שלכן הם <i>נסים</i> (אלא שאין <i>מכירים</i> בהם). וראה לקמן בפנים שהוא דוגמת שהרצון מטה את השכל באופן שנרגש בו שהוא סובר כן מצד עצמו – אף שבאמת אין לזה מקום בשכל, והוא רק מצד הרצון."],["564","25","ראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081005\" data-slug=\"likkutei-sichot\" data-id=\"1300081005\">לקו\"ש ח\"ח ע' 5</a>."],["565","26","וע\"ד שוחד, דהגם שזה שסובר כן הוא מפני שהרצון מטה את השכל (ולא מצד השכל עצמו), נרגש אצלו שהשכל מצד עצמו מחייב כן (כדמוכח מזה שהשוחד יעוור)."],["566","27","ולכאורה יש לומר, דהרמת הטבע הוא גם בהנסים דאין בעל הנס מכיר בנסו. ואדרבא, כיון דזה שנסים אלו הם מוסתרים הוא מפני שהטבע עצמו נעשה כן (כנ\"ל סוף סעיף ה) – הרי הרמת הטבע שבהם הוא עוד יותר."],["567","28","ראה בארוכה ד\"ה נתת ליראיך ה'תשי\"ב [תורת מנחם – התוועדויות כרך ו ע' 44 ואילך]. וראה עד\"ז סה\"מ תרע\"ח ע' פט.\nבפיה\"מ פקל\"ט דגם ביטול הטבע הו\"ע של הרמת ועליית הטבע. אבל בסה\"מ תרע\"ח שם מבואר כבפנים."],["568","29","לשון אדמו\"ר הזקן בשער היחוד והאמונה פ\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061101\" data-slug=\"likkutei-sichot\" data-id=\"1300061101\">לקו\"ש ח\"ו ע' 90</a> הערה 27."],["569","30","שגם הנס דקריעת ים סוף הוא יש מיש ולא יש מאין (ראה שעהיוה\"א שם)."],["570","31","להעיר מפרש\"י עה\"פ חוקת כא, ח \"ולפי שהוא גבוה . . קוראו נס\". היינו, דב\"נס\" שני ענינים: שהוא עצמו גבוה ומרומם, ונס מלשון הרמה, שעל ידו נעשה הרמה בענין שני. ועפ\"ז יש לומר, דזה שהנסים שאינם מלובשים בטבע נקראים בשם נס הוא (בעיקר) מפני שהם עצמם הם גבוהים (אלא שיש בהם <i>גם</i> הענין ד(נס מלשון) הרמה, הרמת הטבע). וראה סה\"מ תרע\"ח ע' פט \"נס הוא ל' רוממות . . גילוי בחי' רוממות הא\"ס שלמעלה מהטבע . . ולכן בהנס מתבטל הטבע\", ולאח\"ז מוסיף <i>עוד</i> ענין \"נס שהוא ל' רוממות היינו רוממות הטבע\"."],["571","32","דמאור הסובב עצמו, כמו שהוא למעלה מהתגלות בעולם אפילו לא באופן דמקיף (\"קדוש\" שלמעלה מ\"ברוך\") אין שייך גם הענין דשידוד וביטול הטבע."],["572","33","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380170\" data-slug=\"likkutei-torah\" data-id=\"4001380170\">לקו\"ת תזריע כב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380176\" data-slug=\"likkutei-torah\" data-id=\"4001380176\">וראה שם כד, א</a> דזה שהמתיבתא דרקיעא זכו להגילוי דקוב\"ה אמר טהור הוא שהשיגו \"רק גילוי הרצון\" כי הגילוי דקוב\"ה הוא בחי' מקיף וסובב. ומזה מובן, שגם ההמשכה (ענין \"ברוך\") דהקב\"ה הוא שנמשך באופן דמקיף, כמו שהוא קדוש ומובדל."],["573","34","המשך תער\"ב ח\"ב ע' תתצד. ובכ\"מ."],["574","35","סידור (עם דא\"ח) מד, ד. פיה\"מ ס\"פ קלט."],["575","36","ברכות נד, ב (במשנה). רמב\"ם הל' ברכות פ\"י ה\"ח. טושו\"ע או\"ח ר\"ס ריט. סדר ברכת הנהנין לאדה\"ז פי\"ג ס\"ב."],["576","37","תהלים ק, ג. וראה פיה\"מ שם פק\"מ (צב, ד)."],["577","38","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380122\" data-slug=\"likkutei-torah\" data-id=\"4001380122\">לקו\"ת צו יא, ג</a> ואילך. פיה\"מ פקמ\"ח (צח, סע\"א ואילך). ובארוכה – ד\"ה שמח תשמח תרנ\"ז בתחלתו."],["578","39","ראה בהמאמר דבעל הגאולה בסופו. אוה\"ת דרושים לסוכות ע' א'תשס. סה\"מ ה'תש\"א ע' 94. בהנסמן להלן הערה 54."],["579","40","ראה מלכים-א ה, יא."],["580","41","קונטרס העבודה פ\"ג (ע' 18)."],["581","42","משלי ו, כג."],["582","43","ראה ד\"ה אז ישיר תרס\"ה (סה\"מ תרס\"ה ע' קיט ואילך). עטר\"ת (סה\"מ עטר\"ת ע' רח ואילך). ה'ש\"ת פ\"ג (סה\"מ ה'ש\"ת ע' 61 ואילך). ובכ\"מ."],["583","44","זח\"ב קסא, א-ב."],["584","45","המשך תער\"ב ח\"א ספ\"ח. סה\"מ ה'ש\"ת ע' 67. ועוד."],["585","46","תהלים קד, ב."],["586","47","ולהעיר דיצחק הוא שמו (השני) של בעל הגאולה."],["587","48","ראה מאמרי אדמו\"ר האמצעי דברים ח\"ג ע' תשעט. וש\"נ."],["588","49","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380476\" data-slug=\"likkutei-torah\" data-id=\"4001380476\">לקו\"ת שלח מא, א</a>."],["589","50","ראה המשך שמח תשמח תרנ\"ז ס\"ע 49 (סה\"מ תרנ\"ז ע' רכד) ואילך. ועוד."],["590","51","ל' כ\"ק מו\"ח אדמו\"ר בעל הגאולה במכתבו לחגיגת י\"ב-י\"ג תמוז בפעם הראשונה – ט\"ו סיון תרפ\"ח (נדפס בסה\"מ תרפ\"ח ע' קמו ואילך. ה'תש\"ח ע' 263 ואילך. אגרות-קודש שלו ח\"ב ע' פ ואילך)."],["591","52","ראה פרש\"י ד\"ה אתחלתא דגאולה – מגילה יז, ב."],["592","53","תהלים סו, ו. וקאי על הגאולה העתידה – ראה שער האמונה רפנ\"ב. שם ספנ\"ו. ובכ\"מ."],["593","54","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">תו\"א בשלח סד, סע\"ב</a>. שער האמונה ספנ\"ו. מאמרי אדמו\"ר האמצעי ויקרא ח\"א ע' שפד. אוה\"ת שבהערה 39. ובכ\"מ."]]],[1500390009,"<h3>בס\"ד. י\"ג תמוז, ה'תשמ\"ב<sup data-n=\"594\">*</sup></h3>\n<b>עשרה</b> שיושבין ועוסקין בתורה שכינה שרוי' ביניהם כו' אפילו חמשה כו' אפילו שלשה כו' אפילו שנים כו' אפילו אחד<sup data-n=\"595\">1</sup>, ומבאר כ\"ק מו\"ח אדמו\"ר בעל הגאולה במאמרו ד\"ה זה שניתן על ידו לחגיגת י\"ב תמוז הראשונה (שנת תרפ\"ח)<sup data-n=\"596\">2</sup>, דהגם<sup data-n=\"597\">3</sup> שגם אחד שיושב ועוסק בתורה (ומכש\"כ שנים שלשה וחמשה) הוא ממשיך גילוי אלקות (שכינה שרוי'<sup data-n=\"598\">4</sup>), מ\"מ, ההמשכה שע\"י תורה דרבים (עשרה<sup data-n=\"599\">5</sup>) היא המשכה נעלית יותר<sup data-n=\"600\">6</sup>. דכמו שבתפלה אמרו רז\"ל<sup data-n=\"601\">7</sup> תפלת רבים אינה נמאסת שנאמר<sup data-n=\"602\">8</sup> הן א-ל כביר ולא ימאס, שהרבים בתפלתם ממשיכים י\"ג מדות הרחמים<sup data-n=\"603\">9</sup>, כמו\"כ הוא בתורה, שע\"י תורה דרבים נמשך גילוי אור עליון יותר.\n<b>וביאור</b> לשון רז\"ל תפלת רבים [ובהמאמר אומר הלשון \"רבים\" גם בנוגע לתורה], אף שמדבר בנוגע לעשרה [והלשון רבים נופל גם בפחות מעשרה, ולאידך, גם עשרה אינם השלימות דרבים, שהרי יש ריבוי גדול יותר<sup data-n=\"604\">10</sup>], יש לבאר, בהקדים, דהטעם על שדבר שנעשה בפני עשרה מישראל הוא פרהסיא הכי גדולה (דלא מצינו חילוק לענין פרהסיא בין עשרה ליותר מעשרה) הוא, כי עשרה מישראל הם<sup data-n=\"605\">11</sup> דוגמת וכוללים העשרה סוגים דישראל (ראשיכם שבטיכם גו' עד חוטב עציך ושואב מימיך<sup data-n=\"606\">12</sup>), ופרסום בפני עשרה מישראל הוא כמו פרסום בכלישראל. וזהו שעשרה מישראל נקראים בשם רבים (סתם), ריבוי הכי גדול שאין ריבוי גדול ממנו.\nב) <b>והנה</b> מבואר בתניא<sup data-n=\"607\">13</sup> שהמעלה דעשרה היא בכל הענינים דתורה ומצוות, כי אין דבר שבקדושה בפחות מעשרה<sup data-n=\"608\">14</sup>. אלא שאעפ\"כ, עיקר המעלה דעשרה הוא בתפלה. דהמעלה שבתפלת רבים שהיא רצוי' ומקובלת לעולם<sup data-n=\"609\">15</sup>, וכיון שהמבוקש דתפלה הוא שהקב\"ה ימלא את בקשתו<sup data-n=\"610\">16</sup>, הרי המעלה בתפלת רבים על תפלת יחיד הוא לא שבתפלת רבים מיתוסף <i>עוד</i> ענין, כי אם, שזה נוגע להתפלה עצמה. ועפ\"ז יש לומר, דמ\"ש בהמאמר שהמעלה בתורה דרבים היא דוגמת המעלה דתפלת רבים, הכוונה בזה היא (גם) שהמעלה בתורה דרבים היא בענין עיקרי.\n<b>ולכאורה</b> הי' אפשר לבאר זה, דכיון שאין התורה נקנית אלא בחבורה<sup data-n=\"611\">17</sup>, מובן, דכשלימוד התורה הוא בחבורה גדולה יותר, התורה נקנית יותר. וכיון שהשלימות דחבורה היא בעשרה<sup data-n=\"612\">18</sup>, כי עשרה מישראל הם דוגמת וכוללים כל העשרה סוגים דישראל, כנ\"ל, לכן, כשלימוד התורה הוא בעשרה, קנין התורה הוא בשלימות. אבל ביאור זה אינו מספיק. כי מעלה הנ\"ל בתורה דרבים היא בהאדם העוסק בתורה, שכשלומד בעשרה, הקנין שלו (שקונה את התורה <i>ומקבל</i> אותה) הוא בשלימות. והדמיון דתורה ברבים לתפלת רבים הוא בההמשכה<sup data-n=\"613\">19</sup>. כמפורש בהמאמר, דכמו שהרבים בתפלתם ממשיכים י\"ג מדות הרחמים כמו\"כ ע\"י תורה ברבים נמשך אור עליון יותר.\nג) <b>ובכדי</b> לבאר מעלת ההמשכה שע\"י תורה דרבים, מקדים בהמאמר, שר' ישמעאל אומר<sup data-n=\"614\">20</sup> בשלש עשרה מדות התורה נדרשת בק\"ו ובגז\"ש וכו'<sup data-n=\"615\">21</sup>. ומבאר, דע\"י כל מדה ומדה (מי\"ג המדות שהתורה נדרשת בהן) מתגלים ענינים חדשים. והטעם על זה הוא, כי י\"ג מדות שהתורה נדרשת בהן הם כנגד י\"ג מדותהרחמים. וכתורת הרב המגיד<sup data-n=\"616\">22</sup> דכשאמר משה א-ל נא רפא נא לה<sup data-n=\"617\">23</sup>, דשם א-ל הוא מדה הראשונה<sup data-n=\"618\">24</sup> די\"ג מדות הרחמים, אמר לו הקב\"ה ק\"ו, ואבי' ירוק ירק בפני' גו' ק\"ו לשכינה<sup data-n=\"619\">25</sup>, מדה הראשונה די\"ג המדות שהתורה נדרשת בהן. ומוסיף בהמאמר, שזהו גם הקשר דשני הפירושים בהרועה בשושנים<sup data-n=\"620\">26</sup>, א\"ת שושנים אלא ששונים בהלכות<sup data-n=\"621\">27</sup> ומה שושנה אית בה תליסר עלין אוף כנס\"י אית בה תליסר מכילין דרחמי<sup data-n=\"622\">28</sup>, והקשר דשני הפירושים הוא<sup data-n=\"623\">29</sup> כי ע\"י לימוד התורה (ששונים בהלכות) נמשכים י\"ג מדות הרחמים. וזהו שע\"י תורה דרבים נמשך אור עליון יותר, כי זה שע\"י לימוד התורה נמשכים י\"ג מדות הרחמים הוא<sup data-n=\"624\">30</sup> בעיקר ע\"י לימוד תורה ברבים דוקא.\n<b>וצריך</b> להבין מה שאומר בתחלת הענין שע\"י י\"ג מדות שהתורה נדרשת בהן מתגלים ענינים חדשים, דלכאורה, השייכות די\"ג מדות שהתורה נדרשת בהן להמדובר לעיל שע\"י תורה דרבים נמשך גילוי אור עליון יותר, הוא, שי\"ג מדות אלו הם כנגד י\"ג מדות הרחמים, והמשכת יגמה\"ר הוא בעיקר ע\"י לימוד התורה ברבים דוקא, ומה נוגע כאן שע\"י י\"ג המדות שהתורה נדרשת בהן מתגלים ענינים חדשים.\n<b>ויש</b> לומר הביאור בזה, דהחילוק בין תורה לתפלה הוא, שתפלה היא <i>שהאדם</i> מבקש ומתפלל וההמשכה מלמעלה (שהקב\"ה ממלא את בקשתו) <i>נעשית</i> ע\"י התפלה, משא\"כ בעסק התורה, מכיון שהתורה שלומד היא דבר ה' (שישנו גם לפני עסק התורה דהאדם), הרי הפעולה שנעשית ע\"י עסק התורה היא לכאורה שהתורה ואוא\"ס המלובש בה יומשך להאדם. ועפ\"ז מקום לומר, שהמעלה דתורה דרבים על תורה ביחיד היא (בעיקר) רק בנוגע להאדם העוסק בתורה. דהגם שאומר בהמאמר שהמעלה דתורה ברבים היא (לא רק בקבלת האדם, שהתורה נקנית אצלו יותר, אלא גם) בההמשכה מלמעלה (כנ\"ל סעיף ב), שע\"י לימוד התורה ברבים נמשך גילוי אור עליון יותר, מ\"מ מקום לומר, שכל הענין דלימוד התורה הוא שע\"י הלימוד מאיר אור התורה (שישנו גם קודם הלימוד) להאדם הלומדה, וע\"י לימוד התורה ברבים מתגלה להאדם אור נעלה יותר. ולכן מביא בהמאמר שע\"י י\"ג המדות שהתורה נדרשת בהן מתגלים ענינים חדשים. דכמו שהתפלה ממשכת רצוןחדש, <i>יהי</i> רצון<sup data-n=\"625\">31</sup>, עד\"ז בתורה, ע\"י לימוד התורה ע\"פ י\"ג המדות שהתורה נדרשת בהן מתגלים ענינים חדשים. והטעם על זה הוא, כי י\"ג מדות שהתורה נדרשת בהן הם כנגד יגמה\"ר, שלמעלה מהתורה. דתורה היא חכמתו של הקב\"ה, ראשית ההשתלשלות, וי\"ג מדה\"ר הם למעלה מהשתלשלות. וע\"י שהאדם לומד תורה ע\"פ י\"ג המדות הוא ממשיך בהתורה (השתלשלות) יגמה\"ר שלמעלה מהשתלשלות, ועי\"ז נמשכים בתורה ענינים חדשים<sup data-n=\"626\">32</sup>. וזהו שע\"י לימוד התורה דרבים נמשך מלמעלה אור עליון יותר, כי המשכת יגמה\"ר שע\"י לימוד התורה היא בעיקר בלימוד התורה ברבים דוקא, היינו שהדרגא דיגמה\"ר שנמשכת ע\"י לימוד התורה ברבים היא דרגא נעלית יותר.\nד) <b>וממשיך</b> בהמאמר<sup data-n=\"627\">33</sup> עוד מעלה בתפלת רבים, שההמשכה מלמעלה שע\"י תפלת הרבים היא לא לפי ערך האתעדל\"ת שלהם. דנוסף לזה שהאתעדל\"ת דתפלת רבים מגעת למעלה יותר שלכן היא ממשכת המשכה נעלית יותר, הנה ע\"י תפלת רבים נמשכת המשכה מלמעלה שלא לפי ערך האתעדל\"ת, גם לא לפי ערך האתעדל\"ת דרבים. דזהו שאמרו רז\"ל<sup data-n=\"628\">34</sup> שתפלת רבים בכל ימי השנה היא כמו תפלת יחיד בעשי\"ת, שכמו שההמשכה שע\"י תפלת יחיד בעשי\"ת היא לא לפי ערך ההעלאה שלו [שלכן הוא בעשי\"ת דוקא, מפני שעשי\"ת הם עת רצון], כמו\"כ הוא ההמשכה שע\"י תפלת רבים (בכל ימי השנה), שהיא לא לפי ערך ההעלאה (גם לא לפי ערך ההעלאה דרבים). ועד\"ז הוא בתורה דרבים, שההמשכה שע\"י לימוד התורה דרבים היא לא לפי ערך הלימוד דהרבים.\n<b>וצריך</b> להבין, דגם בהביאור (שבתחלת המאמר) שהאתעדל\"ת דרבים ממשכת אור נעלה יותר, מבאר שההמשכה שע\"י אתעדל\"ת דרבים היא י\"ג מדה\"ר, דיגמה\"ר הם למעלה מהשתלשלות, והמשכה שלמעלה מהשתלשלות היא שלא לפי ערך האתעדל\"ת, ואעפ\"כ מוסיף אח\"כ (עוד ענין) שההמשכה שע\"י רבים היא שלא לפי ערך האתעדל\"ת דהרבים. ונקודת הביאור בזה, שהכוונה בזה שמוסיף שההמשכה שע\"י רבים היא שלא לפי ערך האתעדל\"ת שלהם היא, שההמשכה שע\"י רבים היא לא רק שההמשכה היא יותר מהעבודה [דענין זה הוא בכל המשכה שלמעלה מהשתלשלות] אלא גם שההמשכה היא (בעיקר) מצד למעלה<sup data-n=\"629\">35</sup>, <i>ע\"ד</i><sup data-n=\"630\">36</sup>אתערותא דלעילא מצד עצמה שנמשכת<sup data-n=\"631\">37</sup> ממקום שאין אתערותא דלתתא מגעת לשם<sup data-n=\"632\">38</sup>.\n<b>ויש</b> לומר שהוא ע\"ד הענין דיגעתי ומצאתי<sup data-n=\"633\">39</sup>, שהידיעה הבאה ע\"י היגיעה היא באופן דמציאה (מצאתי) שלא לפי ערך היגיעה, ושני אופנים בזה. ההצלחה בידיעת והבנת הענין שהתייגע בו – ע\"ד המעלה דתפלת רבים, שההמשכה היא למעלה מהשתלשלות (למעלה מסדר והדרגה), אבל (רק) ממקום זה שלשם הגיעה האתעדל\"ת. ושההצלחה בידיעת התורה הבאה ע\"י יגיעת האדם היא במקום שלא התייגע בו כלל, הוא עמל במקום זה ותורתו עומלת לו ממקום אחר<sup data-n=\"634\">40</sup> – ע\"ד ענין השני דתפלת רבים, שההמשכה שע\"י העבודה (תפלה), היא ע\"ד אתערותא דלעילא מצד עצמה שאתערותא דלתתא (גם האתעדל\"ת דתפלת רבים) אינה מגעת לשם. אלא שמ\"מ המשכה זו באה ע\"י תפלת רבים, בדוגמת שגם שתורתו עומלת לו במקום אחר הוא ע\"י העמל דהאדם<sup data-n=\"635\">41</sup>.\nה) <b>ויש</b> לומר שהחילוק דשני ענינים אלה הוא גם בשרשם, בי\"ג מדות הרחמים. והענין הוא, דמספר<sup data-n=\"636\">42</sup> י\"ג (תיקוני דיקנא) הוא י\"ב עם אחד. די\"ב הוא י\"ב בקר (שבבריאה), והא' (המיתוסף על י\"ב) הוא הים שעומד עליהם (מלכות דאצילות). ולמעלה יותר, י\"ב הוא י\"ב גבולי אלכסון שבאצילות, והא' (המיתוסף על י\"ב) הוא למעלה מאצילות. ויש לומר דזה שי\"ג הוא למעלה מהשתלשלות, הוא, כי ע\"י הא' שמיתוסף בהי\"ב, גם הי\"ב הם למעלה מהשתלשלות. ויש לומר, דשני אופנים (מדריגות) בזה. שהא' נמשך בהי\"ב כמו שהם במקומם, דבאופן זה, גם לאחרי שנמשך בהם הא', הם גבול (<i>גבולי</i> אלכסון), אלא שע\"י שנמשך בהם הא' שלמעלה מהשתלשלות יש בהם כח בלתי מוגבל. ועוד אופן, שהי\"ב מתעלים ונכללים בהא', שעי\"ז הם יוצאים מהגבלתם ונעשים בבחי' בל\"ג. ויש לומר דזהו שאחד בגימטריא י\"ג, שכל הי\"ג הם אחד.\n<b>ויש</b> לומר, דשני הענינים בההמשכה שעל ידי עבודה (תפלה או לימוד התורה) דרבים, שההמשכה היא שלא בהדרגה (למעלה מהשתלשלות), ושע\"י עבודתם נמשך גם ממקום שא\"א לאתעדל\"ת (גם לאתעדל\"ת דרבים) לעורר שם, הוא בשתידרגות הנ\"ל. דבהדרגא די\"ג, שהא' נמשך בהי\"ב, כיון שי\"ב הוא גבול, ההמשכה משם היא ע\"י אתעדל\"ת. אלא שע\"י הא' שנמשך בהי\"ב, ההמשכה היא שלא בהדרגה (בדוגמת יגעתי ומצאתי). ובהדרגא די\"ג, שהי\"ב נכללים בהא' וכל הי\"ג הם בל\"ג, ההמשכה משם היא דוגמת אתעדל\"ע שמצד עצמה.\nו) <b>ויש</b> לקשר זה עם חג הגאולה י\"ב י\"ג תמוז, שבי\"ב תמוז [יום ההולדת של בעל הגאולה] הודיעו לו שהגיעה פקודה לשחררו, והשחרור בפועל הי' בי\"ג תמוז<sup data-n=\"637\">43</sup>. ויש לומר, דזה שבי\"ב (תמוז) הודיעו לו ע\"ד השחרור, הו\"ע י\"ב כמו שנמשך בו הא'<sup data-n=\"638\">44</sup>. וכיון שי\"ב כמו שהוא במקומו, גם כשנמשך בו הא', הוא גבול, לכן בי\"ב הי' עדיין לפני הגאולה בפועל. כי ענין הגאולה הוא למעלה ממדידה והגבלה [ובפרט להמבואר בהמכתב דבעל הגאולה [שבא בתור הקדמה להמאמר ד\"ה עשרה שיושבין] שלא אותו בלבד גאל הקב\"ה אלא גם את כל ישראל, כולל גם אלו אשר בשם ישראל (רק<sup data-n=\"639\">45</sup>) יכונה<sup data-n=\"640\">46</sup>. ולהוסיף, שבזה נכללים גם הדורות שלאח\"ז, כי הגאולה די\"ב-י\"ג תמוז היא פעולה נמשכת, שממשכת גאולה לכל ישראל שבמשך כל הדורות, גאולה בנוגע ללימוד התורה וקיום המצוות שלהם וגם גאולה בנוגע לענינים הגשמיים שלהם, בני חיי ומזוני, שיהיו כולם \"רויחי\", למעלה ממדידה והגבלה. ויתירה מזו, שהיא (הגאולה די\"ב-יג תמוז) גם הקדמה והכנה לגאולה האמיתית והשלימה ע\"י משיח צדקנו<sup data-n=\"641\">47</sup>, שאז יהי' אמיתית הענין דלמעלה ממדידה והגבלה], והגאולה בפועל היתה בי\"ג בגימטריא אחד, שהי\"ב מתעלים בהא', למעלה מהגבלה.\nז) <b>וממשיך</b> בהמאמר&lt;33&gt;, דהגם שתורה היא המשכה מלמעלה למטה מ\"מ גם בתורה צ\"ל עבודה ויגיעה, ושני ענינים בזה. שבכדי שלימוד התורה יהי' כדבעי הוא ע\"י [הקדמת<sup data-n=\"642\">48</sup>] עבודת התפלה, דכל האומר אין לי אלא תורה אפילו תורה אין לו<sup data-n=\"643\">49</sup>. ושגם לימוד התורה עצמו צ\"ל בעבודה ויגיעה. ובזה שני ענינים. היגיעה בהבנת התורה, יגעתי ומצאתי. והיגיעה בתורה לשנות טבעו ורגילותו, כמאמר רז\"ל<sup data-n=\"644\">50</sup> שאינו דומה שונה פרקו מאה פעמים לשונה פרקו מאה פעמים ואחד<sup data-n=\"645\">51</sup>, שאז דוקא נקרא עובד אלקים.<b>וצריך</b> להבין, הרי ענין האתעדל\"ת שבתורה הוא לכאורה בעיקר בהיגיעה שצריכה להיות בלימוד התורה עצמו, והסדר בהמאמר הוא שבתחלה מבאר שבכדי שלימוד התורה יהי' כדבעי צ\"ל העבודה והיגיעה דתפלה ולאח\"ז אומר (כמו דבר נוסף) שצ\"ל יגיעה גם בלימוד התורה עצמו. ולהעיר, שגם בתניא<sup data-n=\"646\">52</sup> מדבר בשני ענינים אלה, היגיעה בתורה והיגיעה בעבודת ה' בכלל שעיקר העבודה הוא עבודת התפלה<sup data-n=\"647\">53</sup>, וסדר הענינים שבתניא הוא שבתחלה מביא הפסוק<sup data-n=\"648\">54</sup> ושבתם וראיתם גו' בין עובד אלקים לאשר לא עבדו, דעל פסוק זה איתא בגמרא שעובד אלקים הוא מי ששונה פרקו מאה פעמים ואחד, שינוי טבע הרגילות בלימוד התורה, ומאמר רז\"ל זה הוא המקור להמבואר שם שגם קיום כל המצוות [ובפרט עבודת התפלה] צ\"ל באופן זה. ומזה (שסדר הענינים בהמאמר הוא באופן הפוך מהסדר שבתניא) מוכח עוד יותר שסדר הענינים בהמאמר הוא בכוונה.\nח) <b>ויובן</b> זה בהקדים ביאור הדיוק (שבהמאמר) הגם שתורה היא המשכה מלמעלה למטה. דהביאור בזה בפשטות הוא, דכיון שתורה היא המשכה מלמעלה למטה, אין צורך ברבים. דבתפלה שההמשכה היא ע\"י עבודת המטה צריך שעבודת המטה תהי' עבודה דרבים, משא\"כ בתורה שהיא המשכה מלמעלה, אין חילוק אם המטה הוא רבים או יחיד. וע\"פ הידוע<sup data-n=\"649\">55</sup> שהטעם שע\"י תפלה נמשך רצון חדש הוא מצד גודל העילוי דהעלאת מ\"ן, למעשה ידיך תכסוף<sup data-n=\"650\">56</sup>, יש לומר, שהכוונה בהדיוק שתורה היא המשכה מלמעלה למטה היא גם לאידך גיסא, דכיון שהתורה היא המשכה מלמעלה, גם ע\"י לימוד תורה דרבים א\"א להיות המשכה נעלית ביותר כההמשכה שע\"י תפלה [דרבים].\n<b>ועפ\"ז</b> יש לבאר סדר הענינים בהמאמר, שבתחלה מבאר העבודה והיגיעה דתפלה שצריכה להיות בשביל עסק התורה ולאח\"ז העבודה והיגיעה שבלימוד התורה עצמו, כי עיקר העבודה והיגיעה היא עבודת התפלה, שלכן נקראת בשם עבודה סתם. כי ענין העבודה הוא שינוי הטבע והרגילות, וזה נעשה בעיקר ע\"י עבודת התפלה. ובפרט ע\"י תפלת העמידה שהאדם המתפלל הוא כעבדא קמי מארי'<sup data-n=\"651\">57</sup>, ביטול בתכלית. ולכן מקדים בהמאמר העבודה והיגיעה דתפלה שבשביל עסק התורה, כי העבודה והיגיעה דעסק התורה (מצד עצמה) אין בכחה להמשיך המשכה שלא לפי ערך העבודה כלל. וזה שע\"י לימוד התורה (דרבים) נעשה המשכה שלא לפי ערך העבודה כלל, כההמשכה שע\"י תפלה (דרבים), היא בעיקר ע\"י העבודה דתפלה שבשביל עסק התורה. אלא שביאור זה אינו מספיק, כי בתורה, ההמשכה שלא לפי ערך ההעלאה באה בידיעת והבנת התורה, שהצלחתו בידיעתוהבנת התורה היא שלא לפי ערך היגיעה שלו, ולכן צריכה להיות גם היגיעה דשינוי הטבע והרגילות בלימוד התורה עצמו, שעי\"ז, הלימוד שלו הוא כלי לההמשכה שע\"י העבודה דתפלה (שבשביל עסק התורה).\n<b>ויש</b> להוסיף בביאור השייכות דהשונה פרקו מאה פעמים ואחד (היגיעה דשינוי הטבע והרגילות בלימוד התורה) לי\"ג מדות הרחמים, דע\"י הלימוד בפעם המאה ואחד, גם הלימוד דמאה הפעמים שלפנ\"ז הוא באופן של עבודה. בדוגמת המבואר לעיל (סעיף ה) בהמספר י\"ג, שע\"י הוספת האחד, נעשה עילוי (שינוי או הוספה עכ\"פ) בהי\"ב.\nט) <b>ועפ\"ז</b> יש לבאר שבתורת הרב המגיד המובאת בהמאמר כנ\"ל שע\"י שמשה הזכיר שם א-ל (מדה הראשונה די\"ג מדה\"ר) אמר לו הקב\"ה קל וחומר (מדה הראשונה די\"ג מדות שהתורה נדרשת), מדייק שמשה <i>בתפלתו</i> אמר א-ל נא רפא נא לה. דיש לומר, שהדיוק בתפלתו הוא לרמז שעיקר המשכת י\"ג מדות הרחמים שלמעלה מהשתלשלות הוא בתפלה, ועי\"ז באה אח\"כ ההמשכה גם בתורה. וזהו גם הטעם דענין ההמשכה שלא לפי\"ע ההעלאה שע\"י תורה (דרבים) למדין מההמשכה שע\"י תפלה (דרבים), כי עיקר (ומקור) ענין זה הוא בתפלה, ועי\"ז נמשך אח\"כ גם בתורה.\n<b>ולהוסיף</b><sup data-n=\"652\">58</sup><b>,</b> דענין זה (שע\"י התפלה נמשך אח\"כ גם בתורה) מרומז גם בשני הקאַפּיטלאַך תהלים השייכים ליום ההולדת<sup data-n=\"653\">59</sup> דבעל הגאולה בשנה זו. דבמזמור קב [ששייך להסיום דשנת הק\"ב] מתחיל <i>בתפלה</i> לעני גו' ובהמשך המזמור אומר תכתב זאת לדור אחרון גו'<sup data-n=\"654\">60</sup> דקאי על התורה שהיא נצחית. ועד\"ז במזמור קג [ששייך לשנת הק\"ג, מתחיל מיום ההולדת] שמתחיל ברכי נפשי את ה' שהוא תפלת שבח והודי', ובהמשך המזמור אומר ברכו ה' מלאכיו גבורי כח עושי דברו לשמוע בקול דברו<sup data-n=\"655\">61</sup>, ברישא עושי והדר לשמוע<sup data-n=\"656\">62</sup>, הקדמת נעשה לנשמע שהיתה הכנה לקבלת התורה.יו\"ד) <b>והנה</b> ידועה תורת הבעש\"ט<sup data-n=\"657\">63</sup> דכל מה שאדם רואה או שומע הוא הוראה בעבודת השם. ומוסיף הרב המגיד<sup data-n=\"658\">64</sup> שכל מה שרואה ושומע וכל מקרה שיקרה לאדם הוא בשביל עבודת ה'. והביאור בזה, כי גם כל מקרה הוא בהשגחה פרטית, וזה שנקרא בשם מקרה הוא שלמטה בעוה\"ז הוא באופן של מקרה. וע\"ד מ\"ש<sup data-n=\"659\">65</sup> כי יקרא קן צפור לפניך וארז\"ל<sup data-n=\"660\">66</sup> פרט למזומן, דהגם שכל הענינים הם בהשגח\"פ, ויתירה מזו שהם מזומנים ממחשבה הקדומה דא\"ק, מ\"מ, אומר הכתוב כי <i>יקרא</i> קן צפור פרט למזומן, כי ישנם ענינים שהכוונה שבהם נשלמת ע\"י שגם למטה הם באופן דמזומן, וישנם ענינים שהכוונה שבהם נשלמת ע\"י שלמטה הם באופן דמקרה, כי יקרא. ומזה מובן במכש\"כ בנוגע להענינים שבתורה, שכל הפרטים שבה, גם כשנראים בחיצוניות שהם רק בדרך אגב (ע\"ד מקרה), הם הוראה<sup data-n=\"661\">67</sup>.\n<b>ועפ\"ז</b> יש לומר, דזה שהמדה די\"ג המדות שבתורה שנמשכה מיגמה\"ר שבתפלה היא מדת קל וחומר הוא להורות, דהגם שעיקר ההמשכה דיגמה\"ר הוא בתפלה ועי\"ז באה ההמשכה גם בתורה, מ\"מ, יש מעלה בההמשכה שבתורה לגבי ההמשכה שבתפלה, ע\"ד מדת קל וחומר, דהגם שהחמור למידין מהקל, מ\"מ, הוא חמור לגבי הקל. וכמו שמבאר בהמאמר<sup data-n=\"662\">68</sup> דזה שלמידין ההמשכה שלא לפי ערך ההעלאה שע\"י תורה דרבים מההמשכה שע\"י תפלת רבים הוא לימוד באופן דמכש\"כ, ק\"ו.\n<b>והענין</b> הוא, דהחילוק בין תורה ותפלה הוא ע\"ד החילוק בין ברכה ותפלה&lt;55&gt;. דבתפלה, המתפלל הוא למטה <i>ומבקש</i> שישפיעו לו מלמעלה, ובברכה, המברך [זה שיש לו כח לברך, כמו הכהנים שניתן להם כח לברך] הוא למעלה מהמקור שממנו נמשכת הברכה ומצַוה שתהי' ההמשכה למטה. וכהלשון בברכת כהנים יברכך ה' וגו'<sup data-n=\"663\">69</sup>, שהוא לשון ציווי. ועד\"ז הוא בהמשכת ההשפעות שע\"י תורה. דכיון שכתר תורה הוא הפקר לכל<sup data-n=\"664\">70</sup>, הרי ביכלתו של כל אחד מישראל לזכות בה ע\"י עסק התורה באופן שהיא נעשית תור<i>תו</i><sup data-n=\"665\">71</sup> (דהלומד), ונעשה בעל הבית כביכול על התורה ומכש\"כ על המשכת ההשפעות שע\"י התורה.\n<b>ועוד</b> מעלה בברכת כהנים<sup data-n=\"666\">72</sup>, שההמשכה דברכת כהנים היא מלמעלה מהשתלשלות. דברכה בכלל היא להמשיך מה שכבר נמצא בהמקור ולא דבר חדש, דבעניןזה מעלה בתפלה לגבי ברכה, שעל ידי התפלה נעשה רצון חדש. ובברכת כהנים שתי המעלות, שההמשכה היא מלמעלה מהשתלשלות, ובדרך ציווי. וכמו\"כ הוא בההמשכה שעל ידי תורה, שיש בה שתי המעלות, שההמשכה היא מלמעלה מהשתלשלות ובאופן דציווי. וזוהי המעלה בההמשכה שעל ידי תורה (דרבים) לגבי ההמשכה שע\"י תפלה (דרבים), דההמשכה שע\"י תורה היא באופן שהוא בעה\"ב על ההמשכה.\nיא) <b>והנה</b> אף שברכת כהנים היא מצוה בפני עצמה, קבעוה חכמים בתפלה<sup data-n=\"667\">73</sup>. ומזה מובן, דהגם שתפלה היא מלמטלמ\"ע מ\"מ ע\"י התפלה מגיעים לההמשכה דברכת כהנים שהיא מלמעלה למטה. ועפ\"ז יש להוסיף בהלימוד דק\"ו, דכמו שתפלה וברכת כהנים, הגם שהם ענינים שונים, דתפלה היא בקשה (מלמטה למעלה) וברכת כהנים היא ציווי (מלמעלה למטה), ואעפ\"כ ע\"י התפלה מגיעים לברכת כהנים, עד\"ז הוא בתורה ותפלה, דהגם שההמשכה דיגמה\"ר שלמעלה מהשתלשלות שע\"י לימוד התורה (מצד עצמה) היא למטה מההמשכה דיגמה\"ר שע\"י תפלה (כנ\"ל סעיף ח), מ\"מ, ע\"י לימוד התורה נמשכת (אח\"כ) גם ההמשכה שע\"י תפלה שלמעלה מההמשכה דיגמה\"ר דתורה.\n<b>ויש</b> להוסיף, שגם לימוד זה הוא באופן דק\"ו. דתפלה היא מלמטה למעלה וברכת כהנים היא מלמעלה למטה, ואעפ\"כ ע\"י תפלה מגיעים לברכת כהנים, הרי בנוגע תורה ותפלה, שגם ההמשכה דתורה (מצד עצמה) היא יגמה\"ר שלמעלה מהשתלשלות ורק שהמשכה זו היא למטה מההמשכה דתפלה, זה שע\"י התורה נמשכת גם ההמשכה דתפלה, הוא במכש\"כ וק\"ו. ויש לומר, דע\"י שתורה היא תור<i>תו</i> של האדם העוסק בתורה שהוא בעל הבית כביכול על התורה, עי\"ז הוא נעשה בעה\"ב גם על דרגת ההמשכה דתפלה שנמשכת בתורה. וזהו שהלימוד דתורה ותפלה הוא במדת קל וחומר, כי ההמשכה בתפלה שע\"י תורה יש לה יתרון לגבי ההמשכה דתפלה מצד עצמה.\nיב) <b>ויש</b> להוסיף, דע\"י המאמר עשרה שיושבין ועוסקין בתורה שניתן מבעל הגאולה ללמדו בחג הגאולה, עשה את כל אחד לשלוחו של בעל הגאולה לעסוק בענין זה, ונתן לו נתינת כח מיוחדת להצליח בזה, הצלחה בהתייסדות שיעורים ברבים, והצלחה בכל הענינים (המבוארים בהמאמר) הנמשכים ע\"י עסק התורה דרבים.\n<b>וכל</b> זה באופן דברכת כהנים, שהמשכת הברכה היא באופן דמהירות, כמבואר בלקו\"ת ד\"ה והנה פרח מטה אהרן גו' ויגמול שקדים<sup data-n=\"668\">74</sup>, ועל ידי השקדיםהטובים דמטה אהרן יהפכו השקדים המרים<sup data-n=\"669\">75</sup> דג' השבועות<sup data-n=\"670\">76</sup> לששון ולשמחה, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש.\n**********",[["594","*","יצא לאור ב<b>קונטרס חג הגאולה י\"ב-י\"ג תמוז – תש\"נ</b>, \"לקראת חג הגאולה י\"ב-י\"ג תמוז . . <i>יום ג' פ' בלק יו\"ד תמוז</i>,<i> שנת ה'תש\"נ</i>\"."],["595","1","אבות פ\"ג מ\"ו."],["596","2","נדפס לראשונה בקונטרס יב-יג תמוז תש\"ח, ואח\"כ: בסה\"מ תש\"ח, סה\"מ תרפ\"ח, ובקונטרס בפ\"ע – כמה פעמים לפני חג הגאולה דהשנה, ובשנה זו [תש\"נ], עוד פעם."],["597","3","בכמה ענינים שבהמאמר דשנת תרפ\"ח – ראה גם סה\"מ תרכ\"ט ע' רט ואילך. סה\"מ עטר\"ת ס\"ע תסח ואילך."],["598","4","ד\"מנין אפילו חמשה כו' אפילו אחד\" קאי על \"שכינה שרוי'\" שלפנ\"ז (סה\"מ עטר\"ת שם ע' תע). וצע\"ק במ\"ש באגה\"ק סכ\"ג (קטו, א) \"אלא לקביעת שכר בלבד\". ואכ\"מ."],["599","5","בהמשך המאמר שם (נעתק לקמן בפנים) מובא דוגמא לזה מתפלת רבים. ומזה מוכח שכוונתו ב\"רבים\" היא לעשרה."],["600","6","ראה ברכות ו, א ובנו\"כ המשנה (אבות שם) דיש חילוק בין עשרה לחמשה, בין חמשה לשלשה וכו'. והחידוש בהמאמר הוא שהשראת השכינה בעשרה שעוסקים בתורה היא סוג בפ\"ע (משא\"כ החילוק דחמשה שלשה וכו')."],["601","7","ברכות ח, רע\"א."],["602","8","איוב לו, ה."],["603","9","השייכות דיגמה\"ר לזה שתפלת רבים אינה נמאסת – יש לומר, כי יגמה\"ר אינן חוזרות ריקם (ר\"ה יז, ב)."],["604","10","להעיר משו\"ע אדה\"ז או\"ח הל' תפלה סימן צ ס\"י \"ואע\"פ שיכול להתפלל בביתו בעשרה מ\"מ ברוב עם הדרת מלך\"."],["605","11","בנוגע <i>לכמה</i> ענינים. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041331\" data-slug=\"likkutei-sichot\" data-id=\"1300041331\">לקו\"ש ח\"ד ע' 1332</a> ובהערות שם."],["606","12","נצבים כט, ט-יו\"ד. וראה לקו\"ת ר\"פ נצבים."],["607","13","אגה\"ק סכ\"ג (קלו, סע\"א ואילך)."],["608","14","ברכות כא, ב. מגילה כג, ב. ועוד."],["609","15","ראה שו\"ע אדה\"ז או\"ח הל' ברכות השחר ר\"ס נב \"תפלת צבור היא רצוי' ומקובלת לעולם שנאמר <i>כביר לא ימאס</i>\"."],["610","16","דהגם שגם כשיודע שלא תמולא בקשתו – כי עליו נאמר (ישעי' א, טו. רמב\"ם הל' תשובה פ\"ד ה\"ז) \"גם כי תרבו תפלה אינני שומע\" – פשוט שבתפלתו מקיים מצות תפלה, מ\"מ, <i>המבוקש</i> דתפלה הוא שהקב\"ה <i>ימלא</i> בקשתו. ולא עוד אלא שיש <i>ציווי וחיוב</i> להשתדל שהקב\"ה ימלא בקשתו. ראה שו\"ע אדה\"ז שם רסנ\"ב. ובכ\"מ."],["611","17","ברכות סג, ב. הל' ת\"ת לאדה\"ז פ\"ד ה\"י."],["612","18","ועפ\"ז יומתק המשך הענינים בהל' ת\"ת שם \"שאין התורה נקנית אלא <i>בחבורה</i> ואמרו חכמים <i>עשרה</i> שיושבים כו'\"."],["613","19","ויש לומר, שבהל' ת\"ת שם מדבר בשני הענינים: \"שאין התורה <i>נקנית</i> אלא בחבורה\", ולאח\"ז מוסיף \"ואמרו חכמים עשרה שיושבין כו' <i>שכינה שרוי'</i> ביניהם\", שהמעלה היא גם בההמשכה."],["614","20","ויש לומר, דזה שמעתיק בהמאמר גם \"ר' ישמעאל אומר\" הוא כי \"ישמעאל\" על שם \"שמע ה' אל עניך\" (לך לך טז, יא) מורה על ההמשכה שע\"י תפלה, ולכן מעתיק גם \"ר' ישמעאל אומר\" לרמז שי\"ג המדות שהתורה נדרשת נמשכים מיגמה\"ר שבתפלה. ראה לקמן סעיף ט."],["615","21","תו\"כ בתחלתו."],["616","22","או\"ת (הוצאת קה\"ת) ס\"פ בהעלותך (מו, ב. בהוצאת תש\"מ ואילך – סי' קלז). וראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830099\" data-slug=\"or-hatorah-hb\" data-id=\"8158830099\">אוה\"ת בהעלותך ע' תב</a>. שם פ' ראה ע' תשפה. המשך יונתי תר\"ם ע' מט. סה\"מ תרכ\"ט ועטר\"ת שבהערה 3."],["617","23","בהעלותך יב, יג."],["618","24","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041347\" data-slug=\"likkutei-sichot\" data-id=\"1300041347\">לקו\"ש ח\"ד ס\"ע 1348</a> ואילך. וש\"נ."],["619","25","בהעלותך שם, יד. ב\"ק כה, א. הובא בפרש\"י עה\"פ."],["620","26","שה\"ש ו, ג."],["621","27","ראה זח\"ב כ, ב. שם עדר, א. שבת ל, ב."],["622","28","הקדמת הזהר בתחילתה."],["623","29","ראה גם המשך וככה תרל\"ז פס\"ט (ע' קט) \"ענינם (דשני פירושים אלה) אחד הוא\"."],["624","30","ראה בהמאמר (דשנת תרפ\"ח) רפ\"ב."],["625","31","ראה בהנסמן להלן הערה 72. ועוד."],["626","32","ראה המשך תרס\"ו (ע' שפג. שם ע' שצג. ועוד) ש\"הגם דלכאורה כל הענינים דתושבע\"פ (שחידשו חז\"ל) הכל מתושב\"כ\", הנה באמת \"כל עניני תושבע\"פ הן בבחי' חידוש בכח עצמם ויגיעתם דוקא\", וע\"י היגיעה שלהם המשיכו \"לא מבחי' תוה\"ק לבד כ\"א מבחי' העלם העצמי דא\"ס\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191400\" data-slug=\"likkutei-sichot\" data-id=\"1300191400\">לקו\"ש חי\"ט ע' 387</a> הערה 54."],["627","33","פ\"ב."],["628","34","ר\"ה יח, א."],["629","35","כמ\"ש בהמאמר בנוגע לתפלת יחיד בעשי\"ת (הובא לעיל), שההמשכה היא מפני שעשי\"ת הם <i>עת רצון</i>."],["630","36","אבל לא ממש – ראה לקמן הערה 41."],["631","37","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381225\" data-slug=\"likkutei-torah\" data-id=\"4001381225\">לקו\"ת שה\"ש כד, א</a>."],["632","38","ראה סה\"מ תרכ\"ט ע' רט בשוה\"ג שהוא \"ע\"ד אתערותא דלעילא שלמעלה מאתערותא דלתתא\"."],["633","39","מגילה ו, ב."],["634","40","סנהדרין צט, ב."],["635","41","מהמשך הענינים בהמאמר (וראה לקמן סעיף ח) משמע, שגם המשכה זו נמשכת ע\"י העבודה [ודלא כאתעדל\"ע הג' שבלקו\"ת שם].\nואולי יש לומר, דכיון שכל התורה ענין אחד, לכן גם העמל במקום אחד פועל שהתורה עומלת לו במקום אחר. אלא שמ\"מ, כיון דזה שהתורה עומלת לו ממקום אחר הוא שנמשכת לו ידיעה בענין <i>פרטי</i> – השייכות והדמיון דהאתעדל\"ת (העמל דהאדם) עם האתעדל\"ע (התורה עומלת לו) בזה ששניהם הם תורה אחת (<i>כללות</i> התורה) אינו מספיק, ולכן הוא <i>דוגמת</i> אתעדל\"ע שמצד עצמה.\nועד\"ז צריך לפרש בהנמשל, שהשייכות והדמיון דתפלת רבים לההמשכה שעל ידה, היא רק שייכות כללית וכיו\"ב. ועצ\"ע."],["636","42","בהבא לקמן – ראה אוה\"ת בראשית ח, רע\"א."],["637","43","מכתב בעל הגאולה נדפס באגרות-קודש שלו ח\"ב ע' סו, ובקונטרס יב-יג תמוז תרפ\"ח (קה\"ת תש\"נ) ע' 15."],["638","44","ויש לומר, דזהו שכותב במכתבו הנ\"ל שבי\"ב תמוז הודיעו לו (לא רק שהגיעה פקודה לשחררו, אלא גם) שתעודת החופש יקבל <i>בי\"ג</i> תמוז."],["639","45","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300081340\" data-slug=\"likkutei-sichot\" data-id=\"1300081340\">לקו\"ש ח\"ח ע' 329</a> ואילך."],["640","46","בהמכתב שבהקדמה להמאמר כותב כ\"ז בנוגע <i>י\"ב</i> תמוז. ויש לומר, שזהו מפני שכללות יגמה\"ר (גם הדרגא די\"ב שנמשך בהם הא') הם <i>בכללות</i> למעלה מהשתלשלות."],["641","47","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181323\" data-slug=\"likkutei-sichot\" data-id=\"1300181323\">לקו\"ש חי\"ח ע' 314</a> ואילך."],["642","48","כ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380094\" data-slug=\"likkutei-torah\" data-id=\"4001380094\">לקו\"ת ויקרא ה, א</a>."],["643","49","יבמות קט, ב. וראה לקו\"ת ויקרא שם. הערה ז בהמאמר דשנת תרפ\"ח שם."],["644","50","חגיגה ט, ב. וראה בארוכה תניא פט\"ו."],["645","51","בכמה מקומות הובאה הגירסא (כבע\"י) \"אחת\" (הל' ת\"ת לאדה\"ז פ\"ב ס\"ג. ועוד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261208\" data-slug=\"likkutei-sichot\" data-id=\"1300261208\">לקו\"ש חכ\"ו ע' 208</a> הערה 45)."],["646","52","פט\"ו."],["647","53","שלכן נקראת בשם עבודה (סתם). וראה לקמן סעיף ח."],["648","54","מלאכי ג, יח."],["649","55","ראה ד\"ה שיר המעלות גו' הנה מה טוב תשכ\"ב ס\"ג (לעיל ח\"ג ס\"ע רעא ואילך). וש\"נ."],["650","56","איוב יד, טו."],["651","57","שבת יו\"ד, א."],["652","58","בהבא לקמן, ראה בארוכה ד\"ה עשרה שיושבין דט\"ו תמוז שנה זו (תשמ\"ב), שבא בהמשך למאמר זה (לקמן ע' פד ואילך)."],["653","59","ע\"פ המנהג לומר הקאַפּיטל תהלים המתאים למספר שנותיו* (מכתב כ\"ק מו\"ח אדמו\"ר, נדפס בקובץ מכתבים אודות גודל ערך אמירת תהלים. אגרות-קודש כ\"ק אדמו\"ר מוהריי\"צ ח\"י ס\"ע נג). סיימו קאַפּיטל קב והתחילו בי\"ב תמוז שנה זו (תשמ\"ב) לומר מזמור קג שבתהלים."],["654","60","פסוק יט."],["655","61","פסוק יט."],["656","62","שבת פח, א.\n*) <i>וזה שייך גם לאחר ההסתלקות – ראה רשימת כ\"ק אדמו\"ר מוהריי\"צ בהוספות לסה\"מ פר\"ת ע' שנז</i>.<i> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051115\" data-slug=\"likkutei-sichot\" data-id=\"1300051115\">לקו\"ש ח\"ה ע' 103</a> ואילך</i>.<i> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201413\" data-slug=\"likkutei-sichot\" data-id=\"1300201413\">ח\"כ ס\"ע 400</a></i>.<i> ד\"ה ויהיו חיי שרה תשמ\"א ס\"ט (לעיל ח\"א ע' רפד)</i>.<i> סה\"מ י\"א ניסן ח\"א ע' 1 ואילך</i>.<i> ועוד</i>."],["657","63","כתר שם טוב (הוצאת קה\"ת תשנ\"ט) בהוספות סי' קעט ואילך. וש\"נ."],["658","64","לקו\"א סרי\"ג (נב, ב ואילך)."],["659","65","תצא כב, ו."],["660","66","חולין קלט, א. פרש\"י עה\"פ (תצא שם)."],["661","67","וזה גופא שנראים בחיצוניות שהם רק בדרך אגב – גם בזה יש כוונה (במכש\"כ מענין המקרה שבעולם, שהוא לפי שהכוונה דכמה ענינים נשלמת דוקא באופן זה)."],["662","68","פ\"ד."],["663","69","נשא ו, כב ואילך."],["664","70","ראה רמב\"ם הל' ת\"ת רפ\"ג. הל' ת\"ת לאדה\"ז רפ\"ד."],["665","71","קידושין לב, ריש ע\"ב. ע\"ז יט, א."],["666","72","בהבא לקמן, ראה ד\"ה אמר ריב\"ל כל כהן שמברך כו' תרכ\"ט (סה\"מ תרכ\"ט בתחלתו). ד\"ה כה תברכו תרנ\"ד (סה\"מ תרנ\"ד ס\"ע שטו ואילך). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101038\" data-slug=\"likkutei-sichot\" data-id=\"1300101038\">לקו\"ש ח\"י ס\"ע 38</a> ואילך, ובהנסמן שם."],["667","73","שו\"ע אדה\"ז או\"ח רסקכ\"ח. וש\"נ."],["668","74","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380536\" data-slug=\"likkutei-torah\" data-id=\"4001380536\">לקו\"ת ס\"פ קרח (נה, ג</a> ואילך). וראה גם ד\"ה זה דש\"פ קרח אדר\"ח תמוז ה'תשל\"ג (לעיל ח\"ג ע' שפד ואילך)."],["669","75","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380539\" data-slug=\"likkutei-torah\" data-id=\"4001380539\">לקו\"ת שם (נו, ב</a>). וראה ד\"ה הנ\"ל סעיף ט."],["670","76","קה\"ר עה\"פ (יב, ז) וישב העפר. זו\"ח שה\"ש סא, ג. איכה צג, א. פרש\"י עה\"פ ירמי' א, יב."]]],[1500390010,"<h3>בס\"ד<sup data-n=\"671\">*</sup>. ט\"ו תמוז, ה'תשמ\"ב<sup data-n=\"672\">**</sup></h3>\n<b>עשרה</b> שיושבין ועוסקין בתורה שכינה שרוי' ביניהם<sup data-n=\"673\">1</sup>, ומבאר כ\"ק מו\"ח אדמו\"ר בעל הגאולה במאמרו ד\"ה זה שניתן על ידו לחגיגת י\"ב תמוז הראשונה (שנת תרפ\"ח), דהגם שגם אחד שיושב ועוסק בתורה ממשיך גילוי אלקות, וכהמשך מאמר המשנה ומנין אפילו חמשה כו' אפילו שלשה כו' אפילו שנים כו' אפילו אחד כו', מ\"מ, ההמשכה שע\"י תורה דרבים היא המשכה נעלית יותר. דכמו שבתפלה אמרו רז\"ל<sup data-n=\"674\">2</sup> תפלת רבים אינה נמאסת, כי ע\"י תפלת רבים נמשכים י\"ג מדות הרחמים שלמעלה מהשתלשלות, ויתירה מזו<sup data-n=\"675\">3</sup> דההמשכה מלמעלה שע\"י תפלת רבים היא לא לפי ערך האתערותא דלתתא שלהם (גם לא לפי ערך האתעדל\"ת דרבים), כמו\"כ הוא בתורה, שע\"י לימוד התורה דרבים הוא המשכת י\"ג מדות הרחמים שלמעלה מהשתלשלות [דהגם שההמשכה די\"ג מדות הרחמים ע\"י עסק התורה הוא מצד <i>מעלת התורה</i>, די\"ג המדות שהתורה נדרשת בהן הם כנגד י\"ג מדות הרחמים. דמזה מובן, שההמשכה די\"ג מדות הרחמים היא גם כשאחד יושב ועוסק בתורה, מ\"מ המשכת י\"ג מדות הרחמים ע\"י עסק התורה היא בעיקר ע\"י לימוד תורה ברבים דוקא, היינו שהדרגא די\"ג מדות הרחמים שנמשכת ע\"י עסק התורה ברבים היא דרגא נעלית יותר], ויתירה מזו, שההמשכה שע\"י לימוד התורה דרבים היא לא לפי ערך הלימוד דהרבים.\nב) <b>ויש</b> לומר, שהדמיון דתורה לתפלה, מרומז גם במאמר המשנה הנ\"ל ומנין אפילו אחד שנאמר<sup data-n=\"676\">4</sup> בכל המקום אשר אזכיר את שמי אבוא אליך וברכתיך, דבכל המקום גו' קאי על בית המקדש [מקום שהשכינה באה שם, אבוא אליך], שבו ניתן רשות להזכיר שם המפורש [אזכיר את שמי]<sup data-n=\"677\">5</sup>, ובית המקדש שייך לעמוד העבודה, קרבנות<sup data-n=\"678\">6</sup> ותפלה<sup data-n=\"679\">7</sup> [ולהוסיף, שגם ברכת כהנים שבה היו מזכירים בבית המקדש אתהשם ככתבו&lt;5&gt;, היתה אחרי הקרבת תמיד של שחר<sup data-n=\"680\">8</sup> (ההתחלה דכל הקרבנות), וגם עכשיו קבעו חכמים ברכת כהנים בתפלה<sup data-n=\"681\">9</sup>, ובתפלה עצמה – בברכת עבודה<sup data-n=\"682\">10</sup>]. ובמשנה מביא פסוק זה (בכל המקום אשר אזכיר את שמי אבוא אליך וברכתיך) לענין השראת השכינה שע\"י לימוד התורה, ומזה משמע שתורה ותפלה שייכים זל\"ז ובענין זה במיוחד.\n<b>ולהוסיף</b><b>,</b> דהפירוש שבכל המקום אשר אזכיר את שמי גו' קאי על בית המקדש שבו ניתן רשות להזכיר את שם המפורש, הוא פשוטו של מקרא<sup data-n=\"683\">11</sup> (תורה שבכתב), והפירוש שאזכיר את שמי קאי על לימוד התורה הוא ע\"פ דרשת חז\"ל (תורה שבעל פה). וע\"פ הידוע<sup data-n=\"684\">12</sup> שכל הענינים דתושבע\"פ נמשכים מתושב\"כ, יש לומר, דזה שהלימוד שאפילו אחד שיושב ועוסק בתורה שכינה שרוי' הוא מהפסוק בכל המקום אשר אזכיר את שמי גו' שבפשטות קאי על ביהמ\"ק ששייך לעמוד העבודה, הוא, כי עיקר הענין דהשראת השכינה באופן דאבוא אליך, המשכת אוא\"ס שלמעלה מהשתלשלות (אבוא, אני בעצמי), הוא ע\"י קו העבודה, העלאה מלמטה למעלה. וכמבואר בתניא<sup data-n=\"685\">13</sup> דהטעם שע\"י תפלה נמשך אוא\"ס שלמעלה מהשתלשלות [שע\"י המשכה זו נעשה שינוי בהנבראים, לרפאות החולים ולברך השנים] הוא מפני גודל העילוי דהעלאת מ\"ן. וע\"י התפלה באה אח\"כ המשכה זו גם בתורה.\n<b>וע\"פ</b> מ\"ש בהמאמר דבעל הגאולה (הובא לעיל סעיף א) דזה שע\"י תפלה וע\"י תורה ממשיכים יגמה\"ר שלמעלה מהשתלשלות הוא בעיקר בתפלת רבים<sup data-n=\"686\">14</sup> ובתורה דרבים, ועד שההמשכה שע\"י תפלת רבים ותורה דרבים היא שלא לפי ערך האתערותא דלתתא (דהרבים), מובן, דענין הנ\"ל שההמשכה שלמעלה מהשתלשלות שבתורה היא ע\"י התפלה, מודגש עוד יותר בההמשכה שע\"י רבים. וכמו שנתבאר לעיל (בהמאמר די\"ג תמוז<sup data-n=\"687\">15</sup>), דהטעם שענין ההמשכה שלא לפי ערך ההעלאה שע\"י תורה דרבים נלמד (בהמאמר דבעל הגאולה) מההמשכה שע\"י תפלה דרבים<sup data-n=\"688\">16</sup>, הוא, כי עיקר ומקור ענין זה הוא בתפלה, ועי\"ז נמשך אח\"כ גם בתורה.ג) <b>והגם</b> שהמעלה דהעלאת מ\"ן ישנה לכאורה גם בתורה, וכמבואר בהמאמר דבעל הגאולה<sup data-n=\"689\">17</sup> שגם בתורה צ\"ל עבודה ויגיעה, מ\"מ, עיקר הענין דהמשכה שלמעלה מהשתלשלות הוא ע\"י העלאת מ\"ן דתפלה דוקא<sup data-n=\"690\">18</sup>. ונקודת הביאור בזה, שהמעלה דעבודת האדם (העלאת מ\"ן) שעל ידה נמשך אוא\"ס שלמעלה מהשתלשלות, היא (בעיקר) כשהעבודה היא בביטול<sup data-n=\"691\">19</sup>, וענין הביטול הוא בעבודת התפלה. שהיגיעה בלימוד התורה, כיון שענין הלימוד הוא שיבין וישיג מה שלומד, לכן היגיעה בתורה, גם היגיעה דשונה פרקו מאה פעמים ואחד<sup data-n=\"692\">20</sup>, אף שיגיעה זו היא לא (רק) בשביל הבנת התורה אלא בכדי לשנות טבעו ורגילותו, אינה אמיתית ענין הביטול, כיון שגם הלימוד דפעם המאה ואחד הוא בהבנה והשגה. ועיקר הביטול הוא בעבודת התפלה, שהאדם המתפלל הוא כעבד<sup data-n=\"693\">21</sup> בפני רבו<sup data-n=\"694\">22</sup>. ויש לומר, שגם העבודה דתפלה שבשביל עסק התורה (דכל האומר אין לי אלא תורה אפילו תורה אין לו<sup data-n=\"695\">23</sup>), כיון שהתפלה היא בשביל התורה שענינה הוא הבנה והשגה, אינה אמיתית ענין הביטול<sup data-n=\"696\">24</sup>. ולכן עיקר הענין דהמשכה שלמעלה מהשתלשלות (ומכ\"ש המשכה שלא לפי ערך ההעלאה) הוא ע\"י העלאת מ\"ן דתפלה, ועי\"ז נמשך אח\"כ גם בתורה. דע\"י העבודה שבתורה [העבודה דתפלה שבשביל התורה, ולמטה מזה – העבודה דשונה פרקו מאה פעמים ואחד בכדי לשנות טבעו ורגילותו, ולמטה מזה – היגיעה <i>בהבנת</i> התורה], התורה שלומד היא כלי לההמשכה שלמעלה מהשתלשלות שע\"י תפלה.\nד) <b>והנה</b><sup data-n=\"697\">25</sup> ענין זה (שע\"י התפלה נמשך אח\"כ גם בתורה) מרומז גם בשני הקאַפּיטלאַך תהלים השייכים ליום ההולדת<sup data-n=\"698\">26</sup> דבעל הגאולה בשנה זו (תשמ\"ב), בקאַפּיטל קב שסיימו לומר בערב יום ההולדת<sup data-n=\"699\">27</sup> ובקאַפּיטל קג שהתחילו לומר ביום ההולדת. דבמזמור קב מתחיל בענין התפלה – תפלה לעני גו', ובתפלהעצמה – בתפלה שבתכלית הביטול, תפלה לעני כי יעטוף ולפני הוי' ישפוך שיחו. וכתורת הבעש\"ט הידועה<sup data-n=\"700\">28</sup> עה\"פ, שתפלת העני היא שלפני הוי' ישפוך שיחו. דזה שאינו מבקש שום דבר (גם לא ענינים רוחניים<sup data-n=\"701\">29</sup>) וכל מבוקשו הוא לשפוך שיחו לפני הוי', הוא מפני גודל הביטול שלו. [ויש לומר, דענין זה (שאינו רוצה ומבקש שום דבר גם לא ענינים רוחניים ורק לשפוך שיחו לפני הוי') הוא<sup data-n=\"702\">30</sup> ע\"ד האהבה דמי לי בשמים ועמך לא חפצתי<sup data-n=\"703\">31</sup>, וכלשון אדמו\"ר הזקן<sup data-n=\"704\">32</sup> \"איך וויל זע גאָר ניסט איך וויל ניט דאיין ג\"ע איך וויל ניט דאיין עוה\"ב כו' איך וויל מער ניט אַז דיך אַליין\". ויש לומר, דע\"י שאמר אדמו\"ר הזקן איך וויל מער ניט אַז דיך אַליין, ובפרט לאחרי שנתפרסם זה ע\"י הצמח צדק, ניתן הכח<sup data-n=\"705\">33</sup> לכאו\"א שהולך בעקבותיו (וואָס האַלט זיך אין דער קליאַמקע<sup data-n=\"706\">34</sup>) שבנוגע לפועל עכ\"פ יהי' אצלו מעין זה. ובפרט ע\"י לימוד תורתו של אדמו\"ר הזקן (ועאכו\"כ ע\"י לימוד ענין זה), שעי\"ז מתייחדים ביחוד נפלא<sup data-n=\"707\">35</sup> עם תורתו של אדמו\"ר הזקן, ועי\"ז – עם אדמו\"ר הזקן עצמו<sup data-n=\"708\">36</sup>]. ובהמשך המזמור<sup data-n=\"709\">37</sup> אומר תכתב זאת לדור אחרון גו', דקאי על התורה שהיא נצחית. ויש לומר, שהקשר דשני הענינים הוא, כי הענין דנצחיות התורה בעבודת האדם הוא שהתורה שלומד היא <i>חקוקה</i> במוחו ולבו<sup data-n=\"710\">38</sup>, שאז דוקא אין שייך שיהי' בזה שינוי (נצחיות), ובכדי שלימוד התורה שלו יהי' באופן דחקיקה הוא ע\"י הקדמת עבודת התפלה. ונקודת הביאור בזה, דענין החקיקה דתורה הוא (בעיקר) בהתורה כמו שהיא בשרשה, בבחינת הכתר שלמעלה מחכמה<sup data-n=\"711\">39</sup>. ולאחרי שנמשכה ונתלבשה בחכמה [דלמעלה, ועאכו\"כ לאחרי שירדה ונתלבשה בשכל האדם] היא באופן דכתיבה. ובכדי שלימוד התורה בהבנה והשגה תהי' באופן דחקיקה הוא ע\"י המשכת השורש דתורה (כתר) בהתורה שלמטה. ויש לומר, דזהו מ\"ש תכתב זאת לדור אחרון, תכתב לשון עתיד, שבכדי שהתורה שלומד תהי' אצלו בבחינת נצחיות (לדור אחרון), צריך להגיע לדרגת החקיקה דתורה שלמעלה מבחינת כתיבה, ולהמשיך משם בחינת הכתיבה דתורה, תכתב לשון עתיד. וזוהי השייכות דתכתב זאת לדור אחרון לתפלה לעני גו', שע\"יהקדמת הביטול דתפלה, ובפרט כשהתפלה היא בתכלית הביטול, שתפלתו היא שלפני הוי' ישפוך שיחו, עי\"ז הוא ממשיך גילוי אוא\"ס שלמעלה מהשתלשלות, והמשכה זו באה אח\"כ גם בלימוד התורה שלו, תכתב זאת לדור אחרון.\nה) <b>ועד\"ז</b> הוא במזמור קג שמתחיל בענין התפלה – ברכי נפשי את ה', שהוא תפלת שבח והודי', ובתפלה עצמה – תפלה שבתכלית הביטול. דהשבח וההודי' של דוד להקב\"ה (ברכי נפשי את ה') היתה על כל מאורע ומאורע, כדאיתא בגמרא<sup data-n=\"712\">40</sup> שדוד דר בחמשה עולמים ובכל עולם אמר שירה (חמשה ברכי נפשי<sup data-n=\"713\">41</sup>), דיש לומר, שכל המאורעות דהאדם נחלקות לחמשה סוגים (חמשה עולמים) ודוד אמר שירה להקב\"ה על כל המאורעות, דאמירת שירה להקב\"ה גם על הענינים דהיפך הטוב הנראה והנגלה הוא מפני גודל ועוצם הביטול. ובהמשך המזמור<sup data-n=\"714\">42</sup> אומר ברכו ה' מלאכיו גבורי כח עושי דברו לשמוע בקול דברו, ברישא עושי והדר לשמוע<sup data-n=\"715\">43</sup>, הקדמת נעשה לנשמע שהיתה הכנה לקבלת התורה. ויש לומר שהקשר דשני הענינים<sup data-n=\"716\">44</sup> הוא, כי הביטול דהקדמת נעשה לנשמע הוא לא רק בנוגע לקיום המצוות אלא גם בלימוד התורה<sup data-n=\"717\">45</sup>. דע\"י שלפני מתן תורה הקדימו נעשה לנשמע, ניתן הכח לכ\"א מישראל שלימוד התורה שלו יהי' בביטול, באופן דתען לשוני אמרתך<sup data-n=\"718\">46</sup>, כעונה אחר האומר<sup data-n=\"719\">47</sup>, ועד שהדיבור שלו (בתורה) אינו תלוי ברצונו ובבחירתו<sup data-n=\"720\">48</sup>, ועד שהביטול שלו כשעוסק בתורה הוא דוגמת הביטול דעל<sup data-n=\"721\">49</sup> כל דיבור ודיבור פרחה נשמתן<sup data-n=\"722\">50</sup>. וזוהי השייכות ד(עושי דברו) לשמוע בקול דברו<sup data-n=\"723\">51</sup> לברכי נפשי את ה', כי ע\"י עבודת התפלה, ובפרט כשהתפלה היא שאומר שירה על כל מאורע (חמשה ברכי נפשי), נמשך הביטול דתפלה גם בעסק התורה שלו.\n<b>ויש</b> להוסיף בביאור השייכות ד(עושי דברו) לשמוע בקול דברו לחמשה ברכי נפשי, דעיקר החידוש בהביטול דלימוד התורה הוא בתושבע\"פ, שלימודה צ\"ל בהבנה והשגה [דכשאינו מבין הפירוש אינו נחשב לימוד<sup data-n=\"724\">52</sup>] ואעפ\"כ הלימודהוא בביטול. וע\"ד על כל דיבור ודיבור פרחה נשמתן, דהגם שכל דיבור הוא דיבור פרטי<sup data-n=\"725\">53</sup> (דענין ההתחלקות שייך לההבנה וההשגה דתורה) מ\"מ על כל דיבור ודיבור פרחה נשמתן. וזוהי השייכות דלשמוע בקול דברו לחמשה ברכי נפשי, כי החידוש בהביטול דחמש פעמים ברכי נפשי (שבמזמור קג) על הביטול דלפני הוי' ישפוך שיחו (שבמזמור קב), הוא, שהביטול דלפני הוי' ישפוך שיחו הוא שאין נוגע לו שום דבר (כי כל מבוקשו הוא לדבר עם המלך), והביטול דחמש ברכי נפשי שאומר שירה על כל המאורעות (גם על הענינים דהיפך הטוב הנראה והנגלה) הוא שגם הענינים השייכים למציאותו הם בתכלית הביטול. וע\"י ביטול זה בתפלה נמשך אח\"כ גם בעסק התורה שלו, שגם הלימוד בהבנה והשגה הוא בביטול.\nו) <b>וממשיך</b> בהמאמר דבעל הגאולה<sup data-n=\"726\">54</sup> (לאחרי שמבאר שני הענינים דתפלה ותורה), דבריאת העולם היא בשביל ישראל ובשביל התורה, כמ\"ש<sup data-n=\"727\">55</sup> בראשית ברא אלקים גו', בראשית הוא ב' ראשית, דבריאת העולם הוא בשביל ישראל שנקראים ראשית ובשביל התורה שנקראת ראשית<sup data-n=\"728\">56</sup>. שהכוונה דבריאת העולם היא שישראל ילמדו תורה כמו שניתנה למטה בעוה\"ז דוקא. ויש לומר, שהשייכות דב' ראשית ישראל ותורה להמבואר לפנ\"ז בענין תפלה ותורה, הוא, כי תפלה היא עבודת וביטול האדם (ישראל), ולכן שני הענינים דתפלה ותורה שייכים לב' ראשית ישראל ותורה<sup data-n=\"729\">57</sup>. ומה שאומר בהמאמר \"שישראל ילמדו <i>תורה</i>\", יש לומר, כי ענין התפלה הוא העלאה מלמטה למעלה (יציאה מהעולם<sup data-n=\"730\">58</sup>), והכוונה דבריאת העולם היא שיומשך גילוי אלקות בהעולם, ולכן, כשמדבר בענין הכוונה דבריאת העולם, אומר גם בנוגע לישראל \"שישראל ילמדו <i>תורה</i>\". ועפ\"ז יש לבאר גם מה שמביא בהמאמר (בהמשך להענין שהכוונה דבריאת העולם היא שישראל ילמדו תורה) מה שאמרו רז\"ל&lt;43&gt; תנאי התנה הקב\"ה עם מעשה בראשית אם יקיימו ישראל את תורתי כו', ומבאר, <i>דיקיימו</i> ישראל את תורתי הוא קיום <i>המצוות</i> [והלשון יקיימו ישראל את <i>תורתי</i> הוא, כי קיום המצוות צריך להיות ע\"פ התורה דוקא], כי זה שהעולם נברא בשביל התורה הוא (בלשון המאמר) שכל <i>עניני העולם</i> יהיו ע\"פ התורה, ופעולת התורה בעולם היא ע\"י קיום <i>מצוות</i> התורה<sup data-n=\"731\">59</sup>.ז) <b>והנה</b> לאחרי שמבאר בהמאמר שבריאת העולם הוא בשביל ישראל ובשביל התורה ושקיום העולם הוא ע\"י קיום מצוות התורה, ממשיך בהמאמר<sup data-n=\"732\">60</sup> ביאור החילוק בין לימוד התורה דיחיד ללימוד התורה דרבים, שע\"י תורה דרבים נמשך אור עליון יותר, ומוסיף, שזה מובן <i>במכש\"כ</i> מזה שע\"י תפלת רבים ההמשכה היא שלא לפי ערך ההעלאה. ומסדר הענינים שבהמאמר משמע, דזה שהלימוד דההמשכה שע\"י תורה מההמשכה שע\"י תפלה הוא באופן <i>דמכש\"כ</i>, שייך להמבואר לפנ\"ז בענין הכוונה דבריאת העולם. ויש לומר הביאור בזה, שהכוונה דדירה בתחתונים היא שעשיית הדירה (המשכת הגילוי אלקות בעולם) תהי' ע\"י האדם. וכיון שעבודת התפלה היא העלאה מלמטה למעלה, וההמשכה שע\"י התפלה היא מצד <i>למעלה</i> אלא שבאה <i>ע\"י</i> התפלה (עבודת האדם)<sup data-n=\"733\">61</sup>, לכן יש יתרון בההמשכה שע\"י תורה [שלימוד התורה דהאדם ממשיך גילוי אלקות בעולם] לגבי ההמשכה שע\"י תפלה. וע\"פ הידוע<sup data-n=\"734\">62</sup> שאמיתית הענין דאין ערוך הוא דוקא לגבי העצמות, יש לומר, דענין ההמשכה שלא לפי ערך ההעלאה הוא בעיקר בההמשכה שע\"י תורה, כי בהמשכה זו דוקא נשלמת הכוונה דדירה בתחתונים, כוונת העצמות. ועפ\"ז יש לבאר סדר הענינים בהמאמר, דזה שהלימוד דההמשכה שע\"י תורה מההמשכה שע\"י תפלה הוא באופן דמכש\"כ בא (דוקא) לאחרי הביאור דכוונת הבריאה, כי בההמשכה שע\"י תורה שני ענינים, ההמשכה שע\"י תורה מצד מעלת התורה עצמה – דהמשכה זו היא למטה מההמשכה שע\"י תפלה (כנ\"ל סעיף ג), וההמשכה שע\"י תורה מצד זה שעל ידה נמשך גילוי אלקות בעולם ע\"י עבודת (לימוד) האדם – דהמשכה זו היא למעלה מההמשכה שע\"י תפלה, כנ\"ל. ולכן, לאחרי הביאור בכוונת הבריאה [ושכוונה זו נשלמת ע\"י התורה], מוסיף שהלימוד דתורה מתפלה הוא באופן <i>דמכש\"כ</i>, שיש יתרון בההמשכה דתורה לגבי ההמשכה דתפלה.\nח) <b>ויש</b> לקשר זה עם המאמר ד\"ה הוי' לי בעוזרי ואני אראה בשונאי<sup data-n=\"735\">63</sup> שאמר בעל הגאולה בי\"ב תמוז הראשון (תרפ\"ז)<sup data-n=\"736\">64</sup>, דצריך להבין<sup data-n=\"737\">65</sup> אומרו הוי' לי בעוזרי, דמשמעות הלשון הוא שישנם כמה עוזרים (עוזרי לשון רבים) והבקשה היא שגם הקב\"ה יהי' בין העוזרים, והרי כל ישראל מאמינים באמונה פשוטה שהוא ית' לבדו הוא העוזר והמושיע להאדם בכל עניניו. וביותר אינו מובן, דמשמעות הלשון הוי' לי בעוזרי הוא שהעיקר הם העוזרים לשון רבים והבקשה היא שהקב\"ה יצטרף אליהם. גם צריך להבין אומרו ואני אראה בשונאי (שיראה נקמה בשונאיו), דלכאורה הוה לי' לבקש שיעשו תשובה ויהפכו לאוהבים. ובפרטשדוד עצמו אמר<sup data-n=\"738\">66</sup> יתמו חטאים ולא חוטאים. [וביותר אינו מובן אומרו ואני <i>אראה</i> בשונאי, הרי חוש הראי' הוא מהחושים הכי נעלים, ועד שמהחידושים שיהיו לע\"ל הוא<sup data-n=\"739\">67</sup> ונגלה כבוד הוי' <i>וראו</i> כל בשר גו'<sup data-n=\"740\">68</sup>, ועד\"ז הוא בנוגע למתן תורה שמעיקרי המעלות דמתן תורה הוא<sup data-n=\"739\">67</sup> אתה <i>הראת</i> לדעת גו'<sup data-n=\"741\">69</sup>, ואעפ\"כ ביקש דוד ואני <i>אראה</i> בשונאי, שהראי' שלו תהי' בנקמת שונאיו]. גם צריך להבין השייכות דואני אראה בשונאי להוי' לי בעוזרי.\n<b>ונקודת</b> הביאור בזה (בהמאמר), דעוזרי קאי על הניצוצות המתבררים ע\"י עבודת האדם, שהם העוזרים של האדם. והבקשה הוי' לי בעוזרי היא, שע\"י העבודה דבירור הניצוצות (עוזרי) יהי' <i>הוי'</i> לי, שיומשך לו גילוי שם הוי' שלמעלה מהשתלשלות. ויש לומר, דע\"י שהמשכת הגילוי דשם הוי' להאדם (הוי' לי) הוא ע\"י בירור הניצוצות (בעוזרי), הגילוי הוא בפנימיות. דהגילוי שנמשך לו מלמעלה בדרך אתערותא דלעילא מצד עצמה, הוא בבחינת מקיף, ולכן אין לו קיום<sup data-n=\"742\">70</sup>. ועד\"ז הוא בנוגע לההמשכה שנמשכת לו ע\"י בקשתו בתפלה. ולכן אומר הוי' לי <i>בעוזרי</i>, שהמשכת הגילוי דשם הוי' אליו היא לא בדרך נהמא דכסופא<sup data-n=\"743\">71</sup> אלא שזה (כאילו) מגיע לו עבור עבודתו בעבודת הבירורים, תכלית כוונת הבריאה. ועי\"ז נעשה הוי' <i>לי</i>, שהוא מתאחד עם הגילוי, שלכן הגילוי הוא דבר קיים לעולם, דכל מקום שנאמר לי אינו זז לעולם<sup data-n=\"744\">72</sup>.\nט) <b>וממשיך</b> בהכתוב ואני אראה בשונאי, דבבירור הניצוצות שני ענינים בכללות. בירור הניצוצות שבק\"נ ע\"י עבודת הצדיקים, ובירור הניצוצות שבגקה\"ט ע\"י עבודת התשובה. ולכן במקום שבעלי תשובה עומדין אין צדיקים גמורין יכולים לעמוד בו<sup data-n=\"745\">73</sup>, כי שורש הניצוצות שנפלו בגקה\"ט שמתבררים ע\"י הבע\"ת הוא למעלה יותר משורש הניצוצות שנפלו בק\"נ שמתבררים ע\"י הצדיקים<sup data-n=\"746\">74</sup>. ועד\"ז הוא בעבודת הצדיקים (ועמך כולם צדיקים<sup data-n=\"747\">75</sup>), שיש יתרון בהבירור דדברי הרשות ע\"י העבודה דכל מעשיך יהיו לשם שמים<sup data-n=\"748\">76</sup> על הבירור דדברים הגשמיים שע\"י קיום המצוות. דכיון שדברי הרשות, גם כשעושה אותם לשם שמים הם נשארים דברי הרשות (מעשי<i>ך)</i>, לכן, ע\"י הבירור דדברי הרשות נשלמת יותר הכוונהדדירה בתחתונים, תחתון<sup data-n=\"749\">77</sup> שאין תחתון למטה ממנו<sup data-n=\"750\">78</sup>. ולכן, העלי' שנעשית בהנשמה ע\"י ירידתה למטה [שעיקר העלי' היא עי\"ז שבירידתה למטה היא משלימה הכוונה דדירה בתחתונים<sup data-n=\"751\">79</sup>] היא בעיקר ע\"י הבירור דדברי הרשות. וזהו ואני אראה בשונאי, שע\"י בירור הניצוצות שבשונאי – הניצוצות שבדברים האסורים, ועד\"ז הניצוצות שבדברי הרשות, שגם הם נכללים ב\"שונאי\" כתורת הבעש\"ט הידועה<sup data-n=\"752\">80</sup> עה\"פ<sup data-n=\"753\">81</sup> כי תראה חמור שונאך – באים לראי' באלקות, ואני אראה<sup data-n=\"754\">82</sup>.\nיו\"ד) <b>והנה</b> מבואר בכ\"מ<sup data-n=\"755\">83</sup> שהצדיקים עבודתם היא בעצמם וענין התשובה הוא שהאדם פועל גם בדבר שחוץ ממנו ומאיר את העולם. ועפ\"ז יש לומר, שהענין ד\"אני אראה\" בכללות הוא נוסף על בירור דברי הרשות (בשונאי), אלא גם ע\"י לימוד התורה עם זולתו. וכדמשמע בהמאמר (די\"ב תמוז תרפ\"ז) דזה שאמרו רז\"ל<sup data-n=\"756\">84</sup> הבא לטהר מסייעין לו, דמשמעות לשון לטהר (ולא ליטהר) הוא לטהר אחרים, הוא, כי העזר והסיוע דניצוצות המתבררים (מסייעין לשון רבים, ע\"ד בעוזרי) כשבא לטהר אחרים הוא באופן נעלה יותר.\n<b>ועפ\"ז</b> יש להוסיף עוד ענין במעלת עשרה שיושבין ועוסקין בתורה, דכיון שאין דיעותיהן שוות<sup data-n=\"757\">85</sup>, הרי כל אחד מהעשרה יש לו ההסברה שלו (בהענין שלומדים), וע\"י שלומדים יחד וכל אחד אומר ההסברה שלו להמשתתפים בהשיעור, יש בזה גם המעלה דעסק התורה עם זולתו. ועוד ענין בזה, דע\"י שעשרה מישראל עוסקים בענין אחד, בתורה או בתפלה או בקיום מצוה, מיתוסף בהם ענין חדש – ענין הציבור<sup data-n=\"758\">86</sup>, אור העולה על כולנה<sup data-n=\"759\">87</sup>.\nיא) <b>והנה</b> לשון רז\"ל הוא <i>הבא</i> לטהר מסייעין לו. שכשבא לטהר אחרים, הסיוע הוא מיד <i>כשבא</i> לטהר. ומזה מובן, שכל אלה שמסרו עצמם למלאות שליחותו של בעל הגאולה בכלל, ובפרט בהשליחות<sup data-n=\"760\">88</sup> לייסד שיעורים ברבים, שע\"י ההתמסרות עצמה (אַריינוואַרפן זיך אין דער אַרבעט, עוד לפני העשי' בפועל) נמשך סיוע ונתינת כח נוספים להצליח עוד יותר במילוי השליחות.<b>ויהי</b> רצון, שע\"י המסירה ונתינה למלאות שליחותו של בעל הגאולה, ובפרט אַז מ'האַלט שוין באמצע, והוי' לי (לכל אחד מהמתעסקים בזה) בעוזרי לסיים את השליחות בתכלית השלימות, נזכה מיד לגאולה האמיתית והשלימה ע\"י משיח צדקנו. וכיון שנמצאים כעת ביום זכאי – יום השלישי<sup data-n=\"761\">89</sup> שהוכפל בו כי טוב<sup data-n=\"762\">90</sup>, ויום החמשה עשר דחודש הגאולה שבו קיימא סיהרא באשלמותא<sup data-n=\"763\">91</sup> (השלימות דחודש הגאולה), הרי הזכות דיום זכאי ימהר<sup data-n=\"764\">92</sup> עוד יותר הגאולה, במהרה בימינו ממש.\n**********",[["671","*","יצא לאור ב<b>קונטרס י\"ט תמוז – תש\"נ</b>, \"בקשר עם י\"ט תמוז הבעל\"ט, יום מלאות מאה ועשר שנים לכניסת כ\"ק אדמו\"ר מהוריי\"צ נ\"ע לבריתו של אאע\"ה (תר\"ם – תש\"נ), ויום השביעי דחגיגת הבר מצוה שלו (בשנת תרנ\"ג)* . . <i>עש\"ק פ' פינחס</i>,<i> שנת ה'תש\"נ</i>\"."],["672","**","מאמר זה הוא המשך למאמר ד\"ה זה די\"ג תמוז שנה זו (תשמ\"ב), שי\"ל בקונטרס שלפני זה (י\"ב-י\"ג תמוז ה'תש\"נ (נדפס לעיל ע' עג ואילך)), ולכן לא נכפלו כאן (רוב) הציונים והמ\"מ שכבר נסמנו שם."],["673","1","אבות פ\"ג מ\"ו."],["674","2","ברכות ח, רע\"א."],["675","3","ראה בארוכה בהמאמר די\"ג תמוז ס\"ד ואילך (לעיל ע' עו ואילך)."],["676","4","יתרו כ, כא."],["677","5","פרש\"י עה\"פ יתרו שם, מסוטה לח, א."],["678","6","דענינו של בית המקדש הוא \"בית לה' מוכן להיות מקריבים בו הקרבנות\" (רמב\"ם ריש הלכות בית הבחירה)."],["679","7","דבית המקדש נקרא \"בית תפלה\" (ישעי' נו, ז). וגם עליית התפלות שמחוץ לביהמ\"ק הוא ע\"י ביהמ\"ק\n*) <i>ראה </i>\"<i>מפתח</i>\"<i> המאמרים שבריש סה\"מ תרנ\"ב-תרנ\"ג ס\"ע </i>VII<i> ואילך</i>.<i> הוספות לסה\"מ שם ע' שכה-שכו</i>.<i> לקמן ע' קג הערה 4 [קונטרס בר-מצוה תרנ\"ג (קה\"ת</i>,<i> תש\"ס)]</i>.– ראה ברכות ל, א. רמב\"ם הל' תפלה פ\"ה ה\"ג. טושו\"ע (ודאדה\"ז) או\"ח הל' תפלה סצ\"ד ס\"א-ב. ובירושלמי ברכות פ\"ד ה\"ה – בענין הנ\"ל – מוסיף ומסיים: הה\"ד כי ביתי בית תפלה יקרא לכל העמים."],["680","8","רמב\"ם הל' נשיאת כפים פי\"ד ה\"ט והי\"ד."],["681","9","שו\"ע אדה\"ז או\"ח הל' נשיאת כפים סקכ\"ח ס\"א. וש\"נ."],["682","10","סוטה לח, ב. שו\"ע אדה\"ז שם סי\"ב. וש\"נ."],["683","11","שהרי הוא פירוש <i>רש\"י</i>."],["684","12","וכלשון הרגיל בש\"ס \"מנא הני מילי אמר קרא\". וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381103\" data-slug=\"likkutei-torah\" data-id=\"4001381103\">לקו\"ת ברכה צד, א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381176\" data-slug=\"likkutei-torah\" data-id=\"4001381176\">שה\"ש יא, ד</a>. ובכ\"מ."],["685","13","קו\"א ד\"ה להבין מ\"ש בפע\"ח (קנה, א)."],["686","14","ראה בארוכה אוה\"ת שבת שובה ע' א'תסג ואילך, שגם בתפלת יחיד (גם בכל השנה) נמשכים יגמה\"ר, אלא שיש בזה כמה חילוקי דרגות."],["687","15","סעיף ט (לעיל ע' פ)."],["688","16","משא\"כ ענין ההמשכה דאחד שיושב ועוסק בתורה אינו נלמד מההמשכה שע\"י תפלה, שהרי להפירוש שבמס' אבות מדבר הכתוב <i>בתורה</i>."],["689","17","סעיף ב."],["690","18","כדמוכח גם מהמבואר בקו\"א שבהערה 13, שדוקא ע\"י תפלה נעשה שינוי בהנבראים, \"משא\"כ בתו\"מ שאין שינוי בקלף התפילין ע\"י הנחתן בראש ובזרוע\" – כי ההמשכה דלמעלה מהשתלשלות שעל ידה נעשה שינוי בהנבראים היא דוקא ע\"י העלאת מ\"ן."],["691","19","ראה אוה\"ת שבהערה 21."],["692","20","חגיגה ט, ב. וראה בארוכה תניא פט\"ו."],["693","21","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830275\" data-slug=\"or-hatorah-hb\" data-id=\"8158830275\">אוה\"ת נשא ע' ערה</a> (בענין המעלה דתפלה לגבי תורה) \"ע\"י ביטול העבד ממשיך יהי רצון מה שלמעלה מהחכמה\". וראה ברכות לד, סע\"ב (הובא באוה\"ת שם) דהטעם על זה שהועילה תפלתו של רחב\"ד הוא לפי שהוא \"כעבד לפני המלך\"."],["694","22","טושו\"ע (ודאדה\"ז) או\"ח הל' תפלה סו\"ס צה. וראה גם שבת יו\"ד, א. שו\"ע אדה\"ז שם סק\"ד ס\"ב."],["695","23","יבמות קט, ב."],["696","24","והגם דכיון שתפלה היא בקשת צרכיו נמצא לכאורה <i>שכל</i> תפלה היא בשביל ענין אחר – יש לומר: שצרכיו דעבד באים ע\"י שמבקש מרבו (ובאופן <i>דעבד</i> המבקש), לכן, כשהעבד מבקש צרכיו מרבו (והבקשה שלו היא בביטול <i>דעבד</i> המבקש מרבו), <i>לא</i> נתערב \"מציאות\" שאינה עבדות, כי זהו הסדר דעבד. משא\"כ כשהתפלה היא בשביל לימוד התורה. ועצ\"ע."],["697","25","בהבא לקמן ראה גם (בקיצור) בהמאמר די\"ג תמוז ס\"ט (לעיל ע' פ)."],["698","26","ראה מאמר הנ\"ל הערה 59."],["699","27","אלא שאעפ\"כ שייך הוא ליום ההולדת – ראה לעיל ח\"א ע' רס הערה 51."],["700","28","כתר שם טוב (הוצאת קה\"ת) סי' צז (יג, ג)."],["701","29","כמובן מהמשך הענין שבתורת הבעש\"ט שהובא בספר אור המאיר פ' וישלח – נעתק לעיל ח\"ג ע' קלד."],["702","30","ראה גם לעיל ח\"ג שם."],["703","31","תהלים עג, כה."],["704","32","הובא בשרש מצות התפלה להצ\"צ פ\"מ (דרמ\"צ קלח, סע\"א)."],["705","33","ראה עד\"ז לעיל שם ע' קלז ואילך."],["706","34","ראה סה\"מ תרפ\"ד בהוספות ס\"ע שנד."],["707","35","<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>."],["708","36","וע\"ד פי' הידוע במרז\"ל (שבת קה, א – ע\"פ גירסת הע\"י) \"אנא נפשי כתבית יהבית\" (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380507\" data-slug=\"likkutei-torah\" data-id=\"4001380507\">לקו\"ת שלח מח, סע\"ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460086\" data-slug=\"or-hatorah-hb\" data-id=\"8316460086\">אוה\"ת יתרו ע' תתקא</a> ואילך), שהקב\"ה \"נתן\" ו\"הכניס\" את עצמו בתורתו. והרי \"צדיקים דומין לבוראן\" (ב\"ר פס\"ז, ח. ובכ\"מ)."],["709","37","פסוק יט."],["710","38","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380209\" data-slug=\"likkutei-torah\" data-id=\"4001380209\">לקו\"ת</a> ס\"פ קדושים (ל, ד)."],["711","39","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380277\" data-slug=\"likkutei-torah\" data-id=\"4001380277\">לקו\"ת בחוקותי מו, ד</a>."],["712","40","ברכות יו\"ד, א."],["713","41","לשון הגמרא בברכות שם. ובפרש\"י שם: \"לעיל חשיב להו\". ואף דשירה השני' (ד\"לעיל\") היא \"ברכו ה' מלאכיו גבורי כח עושי דברו לשמוע בקול דברו וגו'\", הרי בנ\"י הקדימו נעשה לנשמע."],["714","42","פסוק יט."],["715","43","שבת פח, א."],["716","44","ובפרט שפסוק זה עצמו הוא אחד מחמשה השירות, תפלה."],["717","45","להעיר, שכשראה ההוא צדוקי שרבא \"מעיין בשמעתא ויתבה אצבעתא דידי' תותי כרעא כו'\" (טרדתו של רבא <i>בלימוד התורה</i>), אמר לי' \"עמא פזיזא דקדמיתו פומייכו לאודנייכו\" (שבת שם)."],["718","46","תהלים קיט, קעב."],["719","47","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א יתרו סז, ב</a>. ובכ\"מ. ובהוספות לתו\"א שם (קי, ריש ע\"ב) מקשר זה עם ענין נעשה ונשמע."],["720","48","הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370487\" data-slug=\"torah-or\" data-id=\"3901370487\">תו\"א שם (קי, א</a> ואילך)."],["721","49","שבת פח, ב."],["722","50","הוספות ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370483\" data-slug=\"torah-or\" data-id=\"3901370483\">תו\"א שם (קט, א</a>)."],["723","51","להעיר מאוה\"ת (יהל אור) לתהלים עה\"פ (ע' שפו) \"לשמוע בקול דברו שיהי' תען לשוני אמרתך\"."],["724","52","הל' ת\"ת לאדה\"ז ספ\"ב. וש\"נ."],["725","53","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380380\" data-slug=\"likkutei-torah\" data-id=\"4001380380\">לקו\"ת במדבר יח, א</a>."],["726","54","סעיף ג."],["727","55","בראשית א, א."],["728","56","תנחומא (באבער) בראשית ג. ה. לקח טוב ר\"פ בראשית. פרש\"י ורמב\"ן עה\"פ. וראה ב\"ר ר\"פ בראשית. ויק\"ר פל\"ו, ד."],["729","57","להעיר מסה\"מ פר\"ת ע' רנא, דהחילוק שבין תפלה לתורה הוא כהחילוק שבין נש\"י לתורה."],["730","58","להעיר מזה שחסידים ואנשי מעשה היו מגיעים (בעת תפלתם) <i>להתפשטות הגשמיות</i> (שו\"ע אדה\"ז או\"ח הל' תפלה סצ\"ח ס\"א. הל' ת\"ת לאדה\"ז פ\"ד ס\"ה)."],["731","59","להעיר, שו\"ה (דשם הוי') הם תורה ומצוות (תקו\"ז ת\"י (כה, ב). אגה\"ת ספ\"ד. <i>ובכ\"מ)</i>. והרי המשכת הו' (ז\"א) למטה הוא ע\"י ה' תתאה (מלכות).\nאלא שמ\"מ חילוק בין תורה לתפלה, דתפלה הוא בחי' י\"ה (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380832\" data-slug=\"likkutei-torah\" data-id=\"4001380832\">לקו\"ת ראה כט, א</a> ואילך), \"נסתרות\". משא\"כ ו' (תורה) הוא המשכה למטה (אלא שהמשכתו הוא ע\"י הה', מצוות). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380839\" data-slug=\"likkutei-torah\" data-id=\"4001380839\">לקו\"ת שם (ל, ד</a>) \"בחי' ו\"ה רומז לבחי' בוניך שהוא ענין דירה <i>בתחתונים</i>\"."],["732","60","סעיף ד."],["733","61","להעיר מסה\"מ תרס\"ה ע' קמג-ד."],["734","62","סה\"מ תרנ\"ב ע' ז ואילך. ובכ\"מ."],["735","63","תהלים קיח, ז."],["736","64","נדפס בסה\"מ קונטרסים ח\"א קעט, א ואילך. תרפ\"ז ע' רא ואילך."],["737","65","ראה גם רד\"ה הוי' לי בעוזרי בלקו\"ת דרושים לשמע\"צ (פח, ב)."],["738","66","תהלים קד, לה. וראה ברכות יו\"ד, א."],["739","67","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו (מו, א</a>). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380145\" data-slug=\"likkutei-torah\" data-id=\"4001380145\">לקו\"ת צו יז, ב</a> ואילך. ובכ\"מ."],["740","68","ישעי' מ, ה."],["741","69","ואתחנן ד, לה."],["742","70","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380083\" data-slug=\"likkutei-torah\" data-id=\"4001380083\">לקו\"ת ויקרא ב, סע\"ב</a> ואילך."],["743","71","ראה ירושלמי ערלה פ\"א ה\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380107\" data-slug=\"likkutei-torah\" data-id=\"4001380107\">לקו\"ת צו ז, ד</a>."],["744","72","ויק\"ר פ\"ב, ב. מדרש שמואל פ' יט. נת' בלקו\"ת במדבר ט, ג ואילך. ובכ\"מ."],["745","73","רמב\"ם הל' תשובה פ\"ז ה\"ד, מברכות לד, ב."],["746","74","ראה בארוכה סהמ\"צ להצ\"צ קצא, א."],["747","75","ישעי' ס, כא."],["748","76","אבות פ\"ב מי\"ב. רמב\"ם הל' דעות ספ\"ג. טושו\"ע או\"ח סרל\"א."],["749","77","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא רפל\"ו</a>."],["750","78","ראה לעיל ח\"ב ע' כג ואילך. וראה בארוכה שם (ע' כח ואילך), שהיתרון בהעבודה דכל מעשיך לשם שמים על העבודה דקיום המצוות הוא ע\"ד מעלת הבע\"ת על צדיקים."],["751","79","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151255\" data-slug=\"likkutei-sichot\" data-id=\"1300151255\">לקו\"ש חט\"ו ע' 242</a> ובהערות שם."],["752","80","\"היום יום\" כח שבט. אגרות-קודש אדמו\"ר מוהריי\"צ ח\"ג ע' שכה. כתר שם טוב הוספות סי' טז [בהוצאת תשנ\"ט – סי' כא]."],["753","81","משפטים כג, ה."],["754","82","ד\"ה הוי' לי בעוזרי תרפ\"ז בסופו. וראה גם לקו\"ת דרושים לשמע\"צ שם (צ, ב)."],["755","83","סה\"מ תרפ\"ג ע' רכב. ה'תש\"ט ע' 184."],["756","84","שבת קד, א."],["757","85","ראה ברכות נח, א. סנהדרין לח, א."],["758","86","דענין ציבור הוא לא צירוף של עשרה יחידים, כ\"א שנעשה מציאות חדשה, וכמו שהאריך בזה בצפע\"נ – ראה מפענח צפונות פ\"ד ס\"ב ואילך."],["759","87","ראה שעהיוה\"א רפי\"ב. ובכ\"מ."],["760","88","ראה בהמאמר די\"ג תמוז שנה זו (תשמ\"ב) סי\"ב (לעיל ס\"ע פב)."],["761","89","ולהעיר, שגם ענין זה שייך להגאולה די\"ב תמוז, כי הקביעות די\"ב תמוז בשנת הגאולה (תרפ\"ז) הי' ביום השלישי, וראה בארוכה לעיל ח\"ב ע' קמב השייכות ד\"שלישי\" ל\"פדה בשלום נפשי\"."],["762","90","פרש\"י עה\"פ בראשית א, ז, מב\"ר פ\"ד, ו."],["763","91","זהר ח\"ב רטו, א. וראה גם שם ח\"א קנ, רע\"א. רכה, סע\"ב. רמט, ב. ח\"ב פה, רע\"א."],["764","92","דמגלגלין זכות ליום זכאי – תענית כט, א."]]],[1500390011,"<h3>בס\"ד. ד' פ' פינחס, ט\"ז תמוז, תשל\"ה<sup data-n=\"765\">*</sup>.</h3>\n<b>אך</b> בגורל יחלק את הארץ<sup data-n=\"766\">1</sup>, חלוקת ארה\"ק, שכבשו את ארץ כנען<sup data-n=\"767\">2</sup> ועשו אותה ארץ ישראל, ועד שעוד בהיות בנ\"י במדבר (טרם שבאו לא\"י) נאמר עלי' ארץ אשר גו' עיני ה\"א בה מרשית השנה ועד אחרית שנה<sup data-n=\"768\">3</sup>, הנה מבאר אשר חלוקת ארה\"ק הייתה ע\"פ הגורל. והוספה בזה על פי ה'<sup data-n=\"769\">4</sup> ומפרש רש\"י<sup data-n=\"770\">5</sup> ברוח הקודש. ועוד ענין הי' בחלוקת הארץ לרב תרבה נחלתו ולמעט תמעיט נחלתו<sup data-n=\"771\">6</sup>, שהו\"ע עפ\"י שכל. שהרי פירוש הפשוט בלרב תרבה גו' הוא כמו שמפרש רש\"י [אשר פירוש רש\"י עה\"ת הוא פשוטו של מקרא<sup data-n=\"772\">7</sup>] לשבט שהי' מרובה באוכלוסין נתנו חלק רב שלא היו החלקים שוים כו', דחלוקה זו היא ע\"פ שכל. [והגם דהרמב\"ן פליג ע\"ז וכן יש פירושים אחרים ברש\"י<sup data-n=\"773\">8</sup>, הרי הרמב\"ן מפרש כוונת רש\"י כפשוטה. ואפילו להרמב\"ן וכן לפי מפרשים אלו שמפרשים את דברי רש\"י כדעת הרמב\"ן, הנה מזה גופא שלפי פירושם הוצרך הכתוב לשלול החלוקה ע\"פ שכל מוכח שיש לחלוקה זו שייכות לשכל. אבל עיקר המדובר כאן הוא פשטות הכתוב ופשטות פירוש רש\"י והספרי<sup data-n=\"774\">9</sup>. שהחלוקה הייתה לפי מספר האנשים, שהיא חלוקה ע\"פ שכל]. נמצא שבחלוקת הארץ היו ג' ענינים. ע\"פ גורל, ע\"פ רוה\"ק, וע\"פ שכל המובן גם בנפש השכלית.\nב) <b>והנה</b> הענין דחלוקת הארץ ע\"פ גורל מבאר כ\"ק אדמו\"ר הצ\"צ<sup data-n=\"775\">10</sup>, מיוסד על מאמר כ\"ק אדמו\"ר הזקן<sup data-n=\"776\">11</sup> במה שאמר ריב\"ז איני יודע באיזו דרך מוליכים אותי<sup data-n=\"777\">12</sup>, דלכאורה תמוה, והרי ריב\"ז לא הלך ד\"א בלא תורה ובלא תפילין<sup data-n=\"778\">13</sup>, ופ' שנה למד ולימד תורה<sup data-n=\"779\">14</sup> וכו', ומה מקום לספק באיזו דרך מוליכין אותו, ומבאר בזה כ\"ק אדה\"ז שזהו מצד עצם הנפש, היינו מצד בחי' הנפש שלמעלה מטו\"ד. ולכןאמר ריב\"ז איני יודע כו', אע\"פ שעסק בתורה וכו', כי זה שעסק בתורה הו\"ע השייך לטו\"ד ואין מזה ראי' להבחי' שלמעלה מטו\"ד. והנה גם בחינה זו, מכיון שיש בזה הענין דשכר ועונש (כמובן מזה גופא שאמר ריב\"ז איני יודע באיזו דרך מוליכין אותי), מוכח מזה, שיש אפשריות ויכולת ורשות לכל אדם נתונה<sup data-n=\"780\">15</sup> גם בנוגע לבחינה זו שבנפש. והיינו שיש עבודה כזו שפועלת גם בעצם הנפש ושעל ידה תהי' כדבעי<sup data-n=\"781\">16</sup>. ובחינה זו שבנפש, וכן העבודה השייכת לבחינה זו, נקראת בשם גורל<sup data-n=\"782\">17</sup>. ועפ\"ז מבאר הצ\"צ הענין דחלוקת הארץ שע\"פ גורל.\nג) <b>וביאור</b> השייכות של ג' הדברים (הגורל בנפש ובעבודת האדם ובחלוקת הארץ), הנה כל הדברים שבעולם ישנם בישראל<sup data-n=\"783\">18</sup>. ובפרט החלק שבעולם השייך בפרט לישראל, וכמאמר חז\"ל<sup data-n=\"784\">19</sup> כשברא העולם חלק הארצות כו' ובחר בארץ ישראל כו' ובחר לחלקו ישראל כו' יבואו ישראל שבאו לחלקי וינחלו את הארץ שבאה לחלקי, שלכן נתן הקב\"ה את כל ארץ כנען לאברהם אבינו לו ולזרעו אחריו לאחוזת עולם<sup data-n=\"785\">20</sup>. ומזה מובן שהדברים שבארץ ישראל הם בהתאם להדברים שבישראל, וכן לאידך גיסא שהדברים שבישראל הם בהתאם להדברים שבארץ ישראל. ומכיון שבנוגע לא\"י, בכיבוש ארץ כנען לעשות אותה ארץ ישראל, היו בה ג' הדברים דגורל רוה\"ק ושכל (שהו\"ע לרב תרבה גו' ולמעט תמעיט גו'), הרי מובן שג' דברים אלו ישנם בישראל, היינו ברוחניות דישראל [וגם זה דרב ומעט, מכיון שישנו (בחלוקת א\"י) בנוגע להגוף (שהוא טפל), הרי עאכו\"כ שישנו בנוגע להרוחני, הנשמה, שזה העיקר]. ומכיון שהתכלית דישראל הוא כמרז\"ל<sup data-n=\"786\">21</sup> אני נבראתי לשמש את קוני, הרי מובן, שכל ג' דברים הנ\"ל ישנם גם בהענין דלשמש את קוני, בעבודת ה'.\nד) <b>והענין</b> הוא, דהנה נתבאר בהמאמרים דימי הגאולה י\"ב וי\"ג תמוז<sup data-n=\"787\">22</sup> (אשר הימים האלה באים בהמשך לימי הגאולה), שבישראל יש ג' דרגות. כמו שהם בבחי' מעין גנים, כמו שהם בבחי' באר מים חיים, וכמו שהם באים (ע\"י עלי באר ענו לה) לבחי' ונוזלים מן לבנון, ונוזלים הוא מלשון מזל, דמזל שענינו למעלה מחו\"ב הו\"ע הגורל כמבואר בכ\"מ<sup data-n=\"788\">23</sup>. ונתבאר בזה שמעין גנים קאי על הנשמות כמו שהם למעלה קודם שירדו למטה. ואז הם נק' בשם בנות ירושלים, שירושלים מורהעל שלימות היראה, וכדאיתא בתוספות<sup data-n=\"789\">24</sup> שירושלים נקרא על שם יראה ועל שם שלם ולכך אין אנו נותנין יו\"ד בירושלים (בין למ\"ד למ\"ם). ולכן הנשמות כמו שהם למעלה נק' בשם בנות ירושלים לפי שאז הם בשלימות היראה. ובאר (מים חיים) קאי על הנשמות כמו שירדו למטה ומלובשות בגופים גשמיים, בדוגמת הבאר שנמצא בעומק הארץ כו'. אמנם ירידה זו היא צורך עלי', שע\"י עבודת הנשמה למטה דוקא היא מתעלית בבחי' נעלית יותר מכמו שהייתה קודם ירידתה. וזהו שחורה אני ונאוה בנות ירושלים<sup data-n=\"790\">25</sup>, שהנשמות שירדו למטה להתלבש בגוף ונה\"ב אומרות להנשמות שלמעלה שנקראות בנות ירושלים, הגם ששחורה אני, כי ע\"י ירידתה לעוה\"ז התחתון שאין תחתון למטה ממנו בענין הסתר אורו ית'<sup data-n=\"791\">26</sup> היא נעשית בבחי' שחרות שהוא העדר האור לגמרי, מ\"מ ע\"י ששחורה אני הנה דוקא עי\"ז ונאוה, שהיא מתעלית יותר מכמו שהייתה למעלה בהיותה נקראת בנות ירושלים. דכמו שהבאר ע\"י שמימיו עוברים את גידי האדמה המעלימים ומסתירים על המים נעשה בהם זיכוך וכו' עד שנעשים מים חיים, שהוא עילוי נעלה יותר מבחי' מעין, וכדאיתא במשנה<sup data-n=\"792\">27</sup> שדוקא מים חיים (משא\"כ מעין) מטהרים את ג' טומאות החמורות עד לטומאת מת שהיא אבי אבות הטומאה, עד\"ז הוא גם בנוגע להנשמה, שע\"י ירידתה למטה והתלבשותה בגוף ונה\"ב המעלימים ומסתירים על אור הנשמה כשהיא מתגלית מהכיסוי וההסתר ע\"י העבודה דחפרוה שרים כרוה נדיבי העם, שענין החפירה והכרי' הוא הסרת ההעלם והסתר של הגוף ונה\"ב המעלימים ומסתירים על אור הנשמה (בדוגמת חפירת וכריית הבאר שהיא הסרת העפר וכו' המעלים ומסתיר על המים), שבעבודה זו שני ענינים. א' ענין ההתבוננות הנק' שרים<sup data-n=\"793\">28</sup>, ב' ענין המדות שבלב הנק' נדיבי העם<sup data-n=\"793\">28</sup>, שעל ידם בא לסור מרע ועשה טוב בפועל, הנה עי\"ז דוקא מתעלית הנשמה למעלה יותר מכמו שהייתה קודם ירידתה, שנעשים בחי' מים חיים (שלמעלה יותר מבחי' מעין גנים), ועד שעי\"ז דוקא באה לבחי' ונוזלים מן לבנון. דזהו שחורה אני ונאוה, שדוקא ע\"י שחורה אני נעשה ונאוה. אלא שהכח שיש להנשמה שבגוף לעבודה זו נמשך לה משרשה שלמעלה. דזהו האמירה לבנו\"י<sup data-n=\"794\">29</sup> שחורה אני ונאוה בנות ירושלים, שהכח להנשמה שבגוף לברר את השחרות וכו' ולהיות ונאוה הוא ע\"י הסיוע שנמשך (להנשמה שבגוף) משרשה שלמעלה הנק' בנות ירושלים.\nה) <b>ובזה</b> מובן<sup data-n=\"795\">30</sup> שהשירה עלי באר ענו לה אמרו ישראל לסוף מ' שנה, אף שהבאר ניתנה להם מתחילת ארבעים (כמובא בפירש\"י עה\"ת<sup data-n=\"796\">31</sup>), כי ישראל שהיובמדבר, אף שהיו דור דיעה וכמבואר בארוכה בקבלה<sup data-n=\"797\">32</sup> גודל העילוי שלהם, שהיו נשמות דעולם המחשבה, היינו שגם בהיותם למטה היו בבחי' עולם המחשבה, מ\"מ (מצד זה גופא) לא הי' בהם העילוי דבחי' באר מים חיים ונוזלים מן לבנון, כי עילוי זה נעשה ע\"י בירור דברים הגשמיים דוקא. וזהו מה שהשירה עלי באר ענו לה אמרו הדור שנכנסו לארץ דוקא (בסוף ארבעים, לפני הכניסה לארץ), כי הענין דא\"י הו\"ע בירור דברים הגשמיים דוקא שעי\"ז נעשה עילוי הנ\"ל, טובה הארץ מאד מאד<sup data-n=\"798\">33</sup>. ומכיון שדור שנכנסו לארץ עמדו במסירת הנפש והרצון ליכנס לארץ טובה ורחבה, ובפרט בסוף ארבעים שנה שאז כבר הי' להם כל ההכנה שצריכים לזה, ועד שכבר הי' גם כיבוש<sup data-n=\"799\">34</sup> ארץ סיחון ועוג שהיא התחלת ענין הכניסה לא\"י (לא רק הכנה והקדמה להכניסה אלא גם התחלת הכניסה. שהרי ארץ סיחון ועוג היא שוה לא\"י בנוגע לכמה דינים<sup data-n=\"800\">35</sup>), לכן הנה בסוף ארבעים שנה דוקא היו ניסים אלו שפעלו בישראל שיאמרו השירה עלי באר גו'.\nו) <b>והנה</b> אמירת שירה הנ\"ל באה ע\"י מסעי בנ\"י (וכמ\"ש לפנ\"ז משם נסעו ויחנו מעבר ארנון גו' ע\"כ יאמר גו'<sup data-n=\"801\">36</sup>). והוא בדוגמת מה שכללות ענין התומ\"צ הוא ע\"י נסיעה דוקא, וכמש\"נ במ\"ת<sup data-n=\"802\">37</sup> וירד הוי' על הר סיני (הנסיעה של הקב\"ה) ואל משה אמר עלה אל הוי' (הנסיעה של בנ\"י), וכ\"ה בהעבודה של כאו\"א מישראל שהתחלת העבודה היא לך לך מארצך וממולדתך ומבית אביך היציאה מהטבע והרגילות והגסות שלו (וכמבואר בהמשך תרס\"ו<sup data-n=\"803\">38</sup> פרטי הענינים דארצך מולדתך ובית אביך), ועי\"ז דוקא ואברכך ואגדלה שמך והי' ברכה עד אשר ונברכו בך כל משפחות האדמה. וכ\"ה גם בנוגע להגילוי דגאולה העתידה, שאז יהי' הענין דונברכו בך כל משפחות האדמה בגילוי ובתכלית השלימות וכמש\"נ<sup data-n=\"804\">39</sup> אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' לעבדו שכם אחד, שהגילוי דגאולה העתידה הוא ע\"י הקדמת הגלות דוקא<sup data-n=\"805\">40</sup>. וע\"ד השירה עלי באר גו' (בהתחלת הכניסה לארץ) שהייתהע\"י ענין המסעות דוקא כנ\"ל, עד\"ז הוא גם בנוגע להשירה דשירו להוי' שיר חדש [תהלים צו, שהוא המזמור של בעל הגאולה שהותחל בי\"ב תמוז<sup data-n=\"806\">41</sup>] שקאי על השיר שבגאולה העתידה [שלכן נאמר שיר חדש לשון זכר, כי גאולה העתידה היא גאולה שלימה ונצחית שאין אחרי' גלות<sup data-n=\"807\">42</sup>], שזה בא ע\"י קדימת הגלות דוקא. דענין הגלות הוא (בדוגמת ו)משתלשל מענין דויגרשהו ע\"י חטא עה\"ד<sup data-n=\"808\">43</sup>, ולפנ\"ז הענין דמיעוט הירח<sup data-n=\"809\">44</sup>, אשר ירידה זו הייתה בכוונה תחילה (כמו שמבאר כ\"ק אדמו\"ר האמצעי<sup data-n=\"810\">45</sup> בארוכה בענין נורא עלילה על בני אדם<sup data-n=\"811\">46</sup>) בכדי שע\"י הירידה יהי' אח\"כ תכלית העילוי והשלימות בישראל, שעי\"ז יהי' במילא תכלית העילוי והשלימות בכל סדר ההשתלשלות, מתחיל מעוה\"ז התחתון שאין תחתון למטה ממנו, וכמשל הליווע\"ר<sup data-n=\"812\">47</sup>, שכשרוצים להגבי' על ידו בית וכיו\"ב, צריך לאחוז את הליווע\"ר בחלק הכי תחתון של הבית, וע\"י הגבהת חלק התחתון דוקא יוגבה כל הבית. ועל דרך זה הוא גם בעליית העולמות, אשר על ידי עליית עוה\"ז התחתון דוקא נעשה עלי' בכל העולמות, ועלי' באופן דאין ערוך, וע\"ד המבואר בההמשך דיום ההילולא<sup data-n=\"813\">48</sup> (של בעל הגאולה), שהענין דלמטה עד אין תכלית שייך להענין דלמעלה עד אין קץ.\nז) <b>וע\"פ</b> הנ\"ל יובן מאמר בעל הגאולה<sup data-n=\"814\">49</sup> שרק הגוף הלך בגלות ולא הנשמה. דלכאורה הרי איתא בגמרא<sup data-n=\"815\">50</sup> שהגלות מבלבל להבנה והשגה, ועאכו\"כ להבנה והשגה באופן דלאסוקי שמעתתא אליבא דהילכתא, וא\"כ הרי הגלות פועל לכאורה גם על הנשמות. אך אחד הביאורים בזה, על פי מה שאיתא במס' עירובין<sup data-n=\"816\">51</sup> כיון דכתיב בהו על פי ה' יחנו ועל פי ה' יסעו כמאן דקביע להו דמי, דמכיון שהחני' היא על פי ה', לכן (הגם שהיא רק לפי שעה) חשובה היא להיות נידונת קבע. דכמו כן הוא גם בנוגע לזמן הגלות, מכיון שהוא על פי ה'<sup data-n=\"817\">52</sup>, לכן גם העבודה דתורהומצוות<sup data-n=\"818\">53</sup> שבזמן הגלות הוא באופן של קביעות ונצחיות. וענין זה הוא לא חוקה כ\"א אפשר להסבירו גם <i>בשכל</i> דנפש האלקית ע\"פ המבואר בתניא<sup data-n=\"819\">54</sup> שהיחוד הנעשה ע\"י לימוד התורה וקיום המצוות הוא נצחי לעולם ועד, והיינו שיחוד נצחי זה (שלמעלה) הוא גם למטה<sup data-n=\"820\">55</sup>. וענין זה אפשר להסביר גם בהשכל דנפש הבהמית [שהתכלית דלימוד התורה הוא שע\"י השכל דנפה\"א, יהי' גם השכל דנפה\"ב מיוחד ביחוד נפלא<sup data-n=\"821\">56</sup> כו'], שמכיון<sup data-n=\"822\">57</sup> שכוונה העליונה בהירידה היא לצורך עלי', הרי פשוט שזה שהוריד הוא בעה\"ב הן על הירידה והן על העלי'<sup data-n=\"823\">58</sup>, ומובן שהענין דירידה צורך עלי' הוא בתכלית השלימות, היינו שכל פרט שבהירידה הוא רק בשביל העלי'. ומכיון שהוא ית' הוא עצם הטוב ומטבע הטוב להטיב, ועד שאומרים על זה הלשון טבע כביכול<sup data-n=\"824\">59</sup>, הרי מובן שזה מה שבחר בירידה גדולה כזו הוא לפי שזוהי הדרך היחידה שעל ידה דוקא אפשר לבוא לעלי' גדולה הלזו. וע\"י התבוננות זו פועלים גם בנפש הבהמית שתהי' במנוחת הנפש, ואז הנה לא רק שהנפה\"א אינה בגלות אלא שגם נפש הבהמית אינה בגלות, כי גם הכחות דנה\"ב (כולל גם כח השכל) הם בתכלית שלימותם, שמצד זה אפ\"ל אצלו הבנה והשגה בתורה ועד לאסוקי שמעתתא אליבא דהילכתא (גם בזמן הגלות), כי גם מצד נפשו הבהמית הוא במצב של מנוחת הנפש.\nח) <b>והנה</b> גם כשלא הגיע לדרגא הנ\"ל, כי לא נקלטה עדיין בשכלו הסברה הנ\"ל שהירידה בעוה\"ז התחתון שאין תחתון למטה ממנו, ובפרט הירידה שבעקבתא דמשיחא (שבעולם התחתון גופא) שהיא ירידה גדולה ביותר כמבואר בש\"ס<sup data-n=\"825\">60</sup> וכפי שרואים זה גם במוחש בעיני בשר, היא רק בשביל העלי' שלכן אינהירידה אמיתית<sup data-n=\"826\">61</sup>, אעפ\"כ מכיון שהוא רוצה ומצפה להיות בדרגת העלי', הרי עי\"ז גופא הוא נמצא בדרגא זו, כמאמר הבעש\"ט<sup data-n=\"827\">62</sup> שבמקום שמחשבתו ורצונו של אדם שם הוא נמצא. אמנם להיות שישנם ענינים חיצוניים המבלבלים ומסתירים, הנה בזה העצה היעוצה אין עומדין להתפלל אלא מתוך כובד ראש<sup data-n=\"828\">63</sup>. תפלה הו\"ע ההתקשרות [דזהו מה שאמרו הלואי שיתפלל אדם כל היום כולו<sup data-n=\"829\">64</sup>, היינו שכל היום כולו יהי' בהתקשרות כזו כמו בעת התפלה, דע<sup data-n=\"830\">65</sup> לפני מי אתה עומד], וההכנה הו\"ע הכובד ראש, כי ע\"י הכובד ראש מתבטלים הדברים המבלבלים. ובפרט ע\"פ תורת הרב המגיד<sup data-n=\"831\">66</sup> שהכוונה בכובד ראש היא כובד של רישא דכל רישין שהרגש זה בא ע\"י ההתבוננות שהנשמה היא חלק אלקה ממעל [בתורת הרב המגיד שם מובא הלשון חלק אלקה ממעל<sup data-n=\"832\">67</sup>, בלי הוספת תיבת ממש. ובזה רואים את החידוש של רבינו הזקן בספר התניא<sup data-n=\"833\">68</sup> שהוא התושב\"כ דחסידות חב\"ד<sup data-n=\"834\">69</sup>], הנה עי\"ז מתבטלים כל הענינים המעלימים ומסתירים, ותיכף ומיד מתגלה מחשבתו [ששם הוא נמצא, כנ\"ל], שמצד מחשבתו הוא בבחי' עלי'. ומבחינת המחשבה, שעיקר מחשבה זו הוא בדרגת הנפש שלמעלה מטו\"ד, כי מחשבה זו היא עצם ענין האדם וכדאיתא בתקו\"ז<sup data-n=\"835\">70</sup> מ\"ה איהו אדם מחשבה חשב מ\"ה כו' דאיהו אדם מחשבה, הנה מבחי' הנפש שלמעלה מטו\"ד נמשך אח\"כ גם בהשכל שלו, שגם בשכלו נקלטה ההסברה שמכיון שע\"פ ה' יחנו כמאן דקביע להו דמי, ועד שזה נמשך אח\"כ גם במעשה בפועל.\nט) <b>והנה</b> עד\"ז הוא גם בכללות ענין העבודה, שיש בה ג' אופנים<sup data-n=\"836\">71</sup>: העבודה בנוגע לסור מרע ועשה טוב בפועל, שהמעשה הוא העיקר, ועד\"ז לרב תרבה גו' ולמעט תמעיט גו', שעבודתו של כל אחד היא לפי אופן חלקו בעולם שניתן לו שצריך לפעול בו בשני הקווין דסור מרע ועשה טוב. למעלה יותר היא העבודה שע\"פ רוח הקודש, ובזה נכללו שני ענינים. וכידוע שרוה\"ק הוא בחינת מלכות שהיא ספירה העשירית, ולפעמים מבואר (בד\"ה ושאבתם<sup data-n=\"837\">72</sup> מכ\"ק אדמו\"ר (מהורש\"ב) נ\"ע), שרוח הקודש היא בחי' חכמה, שמשם שואבים רוה\"ק דבחי' מלכות, [ודוגמת הידוע בפי' ראשית, ובראשית ב' ראשית, ששתי הבחינות דראשית (חכמה ומלכות) נעשים תיבה אחת], שבזה נכללות כל העשר ספירות, והיינו שהענין דרוה\"ק כולל גםהבחינות והדרגות שבינתיים דחכ' ומל' דבנפש. ולמעלה יותר היא העבודה דגורל, שגם בזה שני ענינים, כמו שמבאר כ\"ק אדמו\"ר הצ\"צ<sup data-n=\"838\">73</sup> שני פי' בענין הגורל<sup data-n=\"839\">74</sup>, א' אמונה, ב' ביטול שלמעלה מהשכל. ששני אופנים אלו הם ב' קצוות, דענין האמונה היא בעיקר בספירת המלכות שהיא למטה וסופא דכל דרגין, והביטול שלמעלה מטו\"ד הוא מצד עצם הנשמה שלמעלה מהשכל, שע\"י אמונה זו או ביטול זה לא נשאר שום ספק באיזו דרך מוליכין אותו, ודבר ברור הוא שמוליכין אותו לכל טוב, ועד לתכלית שלימות הטוב, ועד שזוכה לעולמך תראה בחייך<sup data-n=\"840\">75</sup>, שמתגלה אצלו בחי' אך בגורל יחלק את הארץ, למטה מעשרה טפחים, נשמה בגוף.\nי) <b>והנה</b> כמו שבחלוקת א\"י שבהכניסה לא\"י בפעם הראשונה היו ג' הדברים הנ\"ל (אך בגורל יחלק את הארץ, על פי ה' ברוח הקודש, ולרב תרבה גו' ולמעט תמעיט גו'), וע\"י ג' דברים הנ\"ל חלקו את הארץ ובאופן שלכ\"א הי' גפנו ותאנתו, ובני ישראל היו במנוחה ושלוה איש תחת גפנו ותחת תאנתו<sup data-n=\"841\">76</sup>, עד\"ז יהי' גם עכשיו ע\"י מעשינו ועבודתינו, ועוד ביתר שאת ויתר עז מכמו שהי' אז, מכיון שהי' ירידה גדולה ביותר בעקבתא דמשיחא, ובפרט המאסר והגלות של נשמות כלליות נשיאי ישראל, ועד להמאסר וגלות של נשיא ישראל דדורנו (לפני יב-יג תמוז), הנה ע\"י הגאולה שלו, אשר לא אותו בלבד גאל הקב\"ה כי אם גם את כל מחבבי תורתינו הק' שומרי מצוה וגם את אשר בשם ישראל יכונה<sup data-n=\"842\">77</sup>, הרי גאולה זו היא הכנה קרובה וצנור וכלי להמשיך גאולה הכללית של כל בנ\"י בכל מקום שהם, שיהי' שוב פעם כיבוש א\"י ובאופן דונתתי שלום בארץ גו' ואולך אתכם קוממיות, ע\"י ג' אופני העבודה דגורל רוה\"ק ולרב תרבה גו'. והעיקר והיסוד – ע\"י ההחלטה בתוקף ובמס\"נ וכמאמר בעל השמחה<sup data-n=\"843\">78</sup> שענין המס\"נ הוא ההחלטה אַזוי און ניט אַנדערש, און אַז אַ איד זאָגט (כאשר יהודי אומר) שהוא מחליט כן, אין נפק\"מ איך הי' מצבו ומעמדו ברגע שלפנ\"ז, וכפסק הרמב\"ם<sup data-n=\"844\">79</sup> שמיד כשאומר רוצה אני מתגלה רצונו האמתי מה שכל אחד מישראל רוצה לקיים את רצון הבורא ולעשות כל התלוי בו שיקויים רצון הבורא,\n<b>שבזה</b> גם שיקויים רצון הבורא (שהוא עצם הטוב ומטבע הטוב להטיב) להוציא את כאו\"א מישראל מהגלות בכל מקום שהוא, ובאופן דואתם תלוקטו לאחד אחד בני ישראל<sup data-n=\"845\">80</sup>, שאופן זה מראה גודל החביבות וגודל האהבה וגודלההשגחה פרטית על כאו\"א מישראל<sup data-n=\"846\">81</sup>, ויוליכנו קוממיות לארצנו<sup data-n=\"847\">82</sup> בקרוב ממש<sup data-n=\"848\">83</sup> בביאת משיח צדקנו.\n**********",[["765","*","יצא לאור בשעתו, \"<i>יום שלישי שהוכפל בו כי טוב פ' מטו\"מ</i>,<i> ה'תשל\"ה</i>\"."],["766","1","פינחס כו, נה – והוא בהשיעור דיום השלישי (דשבוע זה) שהוכפל בו כי טוב; ופרטי החלוקה (לבאי הארץ) – שתלוים בדיני הירושה (מיוצאי מצרים) – נאמרו בהשיעור דיום הרביעי (יום בו נאמר המאמר)."],["767","2","עיין תו\"א, תו\"ח וכו' ר\"פ וישב."],["768","3","עקב יא, יב."],["769","4","יהושע יט, נ."],["770","5","פרשתנו כו, נו. ולכל הגירסאות בפרש\"י כאן – הייתה חלוקה גם ע\"פ רוה\"ק."],["771","6","פרשתנו כו, נד."],["772","7","פירש\"י בראשית ג, ח. כד. ועוד."],["773","8","ראה רא\"ם כאן ועוד. וש\"נ לב\"ב (קיז, א. קכב, א) וספרי כאן."],["774","9","וראה ג\"כ ראב\"ד הובא בש\"מ לב\"ב שם. הרי\"א ליהושע. מלבים כאן. ועוד."],["775","10","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450590\" data-slug=\"or-hatorah-hb\" data-id=\"8316450590\">אוה\"ת פרשתנו ע' א'נט</a> ואילך. וראה גם ד\"ה אך בגורל תרכ\"ו."],["776","11","הובא באוה\"ת וד\"ה אך בגורל שם. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380295\" data-slug=\"likkutei-torah\" data-id=\"4001380295\">לקו\"ת ויקרא נ, סע\"ד</a>. ד\"ה אשרנו תפר\"ח ותרצ\"ו. סד\"ה להבין כו' הי' בעיניך (קצורים לתניא ע' מא ואילך)."],["777","12","ברכות כח, ב."],["778","13","סוכה כח, א."],["779","14","ר\"ה לא, סע\"ב. סנהדרין מא, א."],["780","15","לשון הרמב\"ם הל' תשובה רפ\"ה. וראה שם ה\"ד, שבאם <i>לא</i> הי' רשות נתונה, \"באי זה דין ואיזה משפט נפרע מן הרשע או משלם שכר לצדיק\"."],["781","16","להעיר מתו\"ש ע' 171. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031007\" data-slug=\"likkutei-sichot\" data-id=\"1300031007\">לקו\"ש ח\"ג ע' ז</a>1016."],["782","17","ראה אגה\"ק סו\"ס ז'. בהנסמן בהערה 10. ד\"ה אשרנו שם. – ועפ\"ז יל\"פ מש\"כ בתשובות הגאונים (ווילנא תרמ\"ה סנ\"ז) אין הגורל אלא מפי שמים שנאמר ע\"פ הגורל תחלק הארץ והעובר על הגורל כעובר על עשה\"ד."],["783","18","וכמש\"נ גם את העולם נתן בלבם (קהלת ג, יא) כו' – <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380329\" data-slug=\"likkutei-torah\" data-id=\"4001380329\">לקו\"ת במדבר (ה, ב</a>)."],["784","19","תנחומא ראה ח. וראה מכילתא בשלח (טו, יז)."],["785","20","לך יז, ח."],["786","21","משנה קדושין בסופו."],["787","22","ראה גם ד\"ה אז ישיר בלקו\"ת (סב, ב ואילך) ואוה\"ת פ' חקת (ע' תתס ואילך). ובכ\"מ."],["788","23","לקו\"ת ר\"פ האזינו. ובכ\"מ."],["789","24","תענית טז, א (ד\"ה הר)."],["790","25","שה\"ש א, ה. וראה ד\"ה זה בלקו\"ת (שה\"ש ו, ג ואילך). אוה\"ת עה\"פ. בסה\"מ תר\"ל. תש\"ב. ועוד."],["791","26","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["792","27","מקואות ספ\"א – הובא ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830178\" data-slug=\"or-hatorah-hb\" data-id=\"8158830178\">אוה\"ת</a> חוקת שם (ע' תתסד)."],["793","28","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830181\" data-slug=\"or-hatorah-hb\" data-id=\"8158830181\">אוה\"ת שם (ע' תתסז</a>)."],["794","29","דיש בזה ב' ענינים – וכמו בפי' ענו לה (אתדל\"ע שלפני ושלאחרי אתדל\"ת)."],["795","30","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830185\" data-slug=\"or-hatorah-hb\" data-id=\"8158830185\">אוה\"ת שם (ע' תתעא</a>)."],["796","31","חקת כא, יז."],["797","32","נסמן בלקו\"ת ר\"פ שלח ובכ\"מ."],["798","33","שלח יד, ז. וראה לקו\"ת שם."],["799","34","עפמש\"כ בבמדב\"ר ס\"פ חוקת כיבוש ממש (עכ\"פ דסיחון) וז\"ל: כיון שלא קיבל סיחון הפילו הקב\"ה מפניהם כו' ולא עוד אלא אף אותן שהטמינו עצמן במערות להרגן רמז הקב\"ה להר ורצץ אותן שנאמר (תהלים עד) שברת ראשי כו' אז ישיר ישראל כו' – ועפ\"ז בטלה <i>מעיקרא</i> השאלה למה פתח בשלום לאחרי שנטמנו במערות להרוג את בנ\"י. – וגם ע\"פ פשטות הכתובים – עכ\"פ כבר עמדו בגבול ארץ סיחון ועוג והקב\"ה כבר אמר ראה <i>נתתי</i> בידך את סיחון גו'. ועוד וג\"ז עיקר – בשירת הבאר נכלל השבח ומבמות הגיא – נבו."],["800","35","כמבואר בדיני עבר הירדן. וראה במדב\"ר פ\"ז, ח: ארץ ישראל מקודשת מכל הארצות ומה היא קדושתה כו' ארץ כנען מקודשת מעבר הירדן. וראה ירושלמי ומפרשי המשנה לביכורים פ\"א מ\"י. רמב\"ן דברים ב, כג. אוה\"ח לדברים ג, יג. ואכ\"מ."],["801","36","וגם הבאר עצמה ובענין זה עצמו \"ירדה לתוך הנחל (ואח\"כ) עלי באר מתוך הנחל\" (רש\"י כאן)."],["802","37","שמו\"ר פי\"ב, ג. וראה שיחת ט\"ז סיון תשל\"ה (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131181\" data-slug=\"likkutei-sichot\" data-id=\"1300131181\">לקו\"ש חי\"ג ס\"ע 181</a> ואילך)."],["803","38","סד\"ה לך תרס\"ו ותרס\"ז. וראה גם סד\"ה זה דשנת תש\"ב ותש\"ה."],["804","39","צפני' ג, ט. וראה רמב\"ם הל' מלכים ספי\"א: ילחום מלחמות ה' כו' וקבץ נדחי ישראל כו' אז אהפוך כו'."],["805","40","להעיר דלך לך מארצך גו' – הוא ענין דגלות וכן דגאולה (ד\"ה לך באוה\"ת עה\"פ, בסה\"מ תרכ\"ז)."],["806","41","ראה קובץ מכתבים לתהלים ע' 114 המנהג לאמר הקאַפּיטל תהלים המתאים למספר שנותיו – וענין זה הוא גם לאחרי ההסתלקות (ראה רשימת כ\"ק מו\"ח אדמו\"ר מיום כ' מ\"ח תש\"ה (נעתקה בהקדמה לד\"ה סמוכים לעד פר\"ת, וב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021220\" data-slug=\"likkutei-sichot\" data-id=\"1300021220\">לקו\"ש ח\"ב ע' 496</a>. וראה גם סה\"מ י\"א ניסן ע' 1 ואילך)). וראה צפע\"נ לרמב\"ם הל' תשובה (פ\"ח, ה\"ד) בגדר הזמן לאחר מיתה. וי\"ל דבנוגע לצדיקים שהם חיים גם לאחרי ההסתלקות – כ\"ע מודי. ואכ\"מ."],["807","42","ראה תוספות פסחים קטז, ב (ד\"ה הכי גרסינן)."],["808","43","ראה פתיחתא דאיכ\"ר ד' (עה\"פ והמה כאדם). רשימות הצ\"צ לאיכה ע' 14 (אוה\"ת נ\"ך כרך ב' ע' א'מג) ואילך. ובארוכה – ד\"ה איכה עת\"ר (סה\"מ עת\"ר ע' ריג ואילך)."],["809","44","ראה ד\"ה איכה שם (ע' ריז). ד\"ה ע\"כ יאמרו המושלים תרצ\"א פ\"ב."],["810","45","תו\"ח תולדות יג, א ואילך. וראה גם איכה שם ש\"כל זה (שבה\"כ ומיעוט הירח וחטא עה\"ד וחורבן ביהמ\"ק) לא הי' במקרה ח\"ו . . והכל בשביל היתרון אור\"."],["811","46","תהלים סו, ה. תנחומא וישב ד."],["812","47","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370014\" data-slug=\"torah-or\" data-id=\"3901370014\">תו\"א ד, א</a>."],["813","48","באתי לגני ה'שי\"ת פי\"ב ואילך. (אולי ע\"פ ז\"ח יתרו לד, סע\"ג: לעילא עד א\"ס ולתתא עד אין תכלית)."],["814","49","ג' תמוז תרפ\"ז – נדפס בקונ' יד בתחילתו (סה\"מ תרפ\"ז ע' קצו). לקו\"ד ח\"ד תרצב, א."],["815","50","ראה מגילה יב, ב: מיום שחרב ביהמ\"ק וגלינו מארצנו ניטלה עצה ממנו ואין אנו יודעים לדון כו'. וראה עירובין סה, א שאפי' טירדא קלה מבלבלת כו'."],["816","51","נה, ב."],["817","52","ועפ\"ז יומתק המשך הענינים (בהרשימה דג' תמוז) \"אבינו מלכנו ית' האָט אונז פאַרטריבן אין גלות. . נאָר אונזערע גופים כו'\" – דמכיון <i>שאבינו מלכנו ית'</i> שלח אותנו בגלות (על פי ה'), לכן רק גופותינו ניתנו בגלות כו'.\nוע\"פ המבואר לקמן [שזה מה שרק גופותינו הם בגלות הוא מצד זה שהירידה דגלות היא צורך עלי' שתהי' בגאולה העתידה] – יומתק גם מה שמוסיף שם \"והוא ית' וועט אונז אויס לייזען כו'\", שי\"ל הכוונה בזה: מכיון שאבינו מלכנו ית' הגלנו מאדמתינו, והטעם למה שהגלנו הוא <i>בשביל</i> העלי' שתהי' כאשר \"הוא ית' וועט אונז אויס לייזען כו'\", לכן \"נאָר אונזערע גופים כו'\"."],["818","53","שאז היא חני' ע\"פ הוי' – דעבדי אתם ו(במילא) לא עבדים לעבדים (קדושין כב, ב. וש\"נ)."],["819","54","פכ\"ה."],["820","55","אלא שלמטה הוא באותה שעה לבדה כו' (עיי\"ש בתניא)."],["821","56","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>."],["822","57","ע\"פ מ\"ש בפנים [שהטעם על זה שגם העבודה שבזה\"ג היא באופן של קביעות ונצחיות הוא לפי שהירידה דגלות היא בשביל העלי' שתהי' אח\"כ בהגאולה], יש לבאר מה שאמרו בעירובין שם \"כיון דכתיב בהו על פי ה' יחנו ועל פי ה' יסעו כמאן דקביע להו דמי\"\n– דלכאורה: מה שנוגע לשם הוא רק \"על פי ה' <i>יחנו</i>\", ולמה הועתק בגמרא גם \"על פי ה' <i>יסעו</i>\"?\nאלא – גם \"על פי ה' יסעו\" מחזק את הקביעות ד\"יחנו\". והביאור בזה: בעת חנייתן במדבר, שאז <i>נתעכבו</i> מללכת לא\"י – הוא דוגמת ענין הגלות; משא\"כ בעת נסיעתם, מכיון שאז נתקרבו לא\"י – הוא מקרב ודוגמת ענין הגאולה,\nומכיון שהכוונה העליונה (\"על פי ה'\") בהירידה ד\"יחנו\" היא בכדי שתביא תוספות ב\"יסעו\", הרי שבהירידה ד\"יחנו\" יש גם העילוי ד\"יסעו\" – הקביעות דארץ ישראל."],["823","58","דלא כהטעות דאין בעה\"ב יכול להוציא כליו (סוטה לה, א)."],["824","59","ראה ד\"ה אתה אחד לאדמו\"ר האמצעי (ברוקלין, תשכ\"ה) ע' 4 ואילך (מאמרי אדמו\"ר האמצעי קונטרסים ע' ה ואילך)."],["825","60","סוף מס' סוטה."],["826","61","וכפס\"ד דהמקלקל ע\"מ לתקן מתקן הוא (שבת קה, ב)."],["827","62","הוספות לכתר שם טוב (קה\"ת תשל\"ג) סל\"ח [בהוצאת תשנ\"ט סמ\"ח] ובהערה שם."],["828","63","ברכות רפ\"ה."],["829","64","ברכות כא, א. וראה תניא פי\"ג (יט, א)."],["830","65","ל' התקשרות והתחברות כו' (<a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא ספ\"ג</a>)."],["831","66","או\"ת ר\"פ ויגש. וראה גם שם קח, ג."],["832","67","שבפסוק (איוב לא, ב) – היינו שג\"ז די לההתבוננות הנ\"ל דלפני התפלה, ובמילא שייכת גם קודם שמבין הענין דממש."],["833","68","רפ\"ב. ראה בארוכה מכתב כ\"ק מו\"ח אדמו\"ר [אגרות-קודש שלו ח\"ד ע' תד. תז] בביאור הוספה זו."],["834","69","\"קיצורים והערות לתניא\" ע' קיח."],["835","70","תי' סט (קיב, ב)."],["836","71","וי\"ל שזהו ג\"כ בכל לבבך, בכל נפשך (עשר כחות הנפש), בכל מאדך (גורל)."],["837","72","תרס\"ט. וראה לקו\"ת לשמע\"צ פז, ג. זח\"ג סא, א. קה\"י בערכו. ולהעיר מאדר\"נ פל\"ד, ח: עשרה שמות נקרא רוה\"ק כו'."],["838","73","אוה\"ת פינחס ע' א'ס. – וריב\"ז לגודל ביטולו ועבודתו בלמד ולימד דתורה לא הי' זה אצלו בהרגש כלל."],["839","74","ראה לקוטי לוי יצחק לתניא ע' לד, לט דגורל בכתר, במל'."],["840","75","ברכות יז, סע\"א."],["841","76","מלכים-א ה, ה."],["842","77","מכתב כ\"ק מו\"ח אדמו\"ר לחגיגת י\"ב וי\"ג תמוז הראשונה – נדפס בסה\"מ תפר\"ח ע' קמו. בסה\"מ תש\"ח ע' 263."],["843","78","סה\"ש תש\"ה ע' 112."],["844","79","הל' גירושין ספ\"ב."],["845","80","ישעי' כז, יב. וברש\"י נצבים ל, ג: כאילו הוא עצמו . . אוחז בידיו ממש איש איש ממקומו."],["846","81","ואף שברש\"י שם \"ואף בגליות שאר האומות מצינו כן\" – כבר נתבאר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091180\" data-slug=\"likkutei-sichot\" data-id=\"1300091180\">לקו\"ש ח\"ט ס\"ע 180</a> ואילך שכוונת רש\"י בזה היא רק להענין ד\"כאילו הוא עצמו\" – \"ושבתי\". אבל בשאר האומות, ה\"ושבתי\" – הוא רק בנוגע לכללות האומה, עיי\"ש באריכות."],["847","82","ארץ ישראל השלימה – כולל הקני הקניזי והקדמוני, וכנאמר בברית בין הבתרים לזרעך נתתי (כבר נתתי. ירושלמי חלה פ\"ב, ה\"א) את הארץ הזאת גו'. רמב\"ם הל' רוצח פ\"ח ה\"ד (והמקור בספרי יט, ח, ואולי לא הי' זה בגירסת הספרי דהכס\"מ. או שיפרש שאינו <i>מוכרח</i> שגם ערי המקלט יהיו בהקני קו\"ק. וראה רש\"י ורמב\"ן עה\"פ שם)."],["848","83","וכפס\"ד הרמב\"ם (הל' תשובה פ\"ז, ה\"ה. וראה אגה\"ת פי\"א) דישראל עושין תשובה <i>ומיד</i> הן נגאלין."]]]]});
